/* chinese/idioms/data/set1.js — 作者 A 的成語（catalog.js 第二欄 = 1 的那幾個）＋素養閱讀。照 set0.js 的寫法寫；規格 kids-member/docs/CHINESE_IDIOM_SPEC.md。
   成語照編號順序寫進 DATA_CY，素養閱讀寫進 DATA_CY_READ。每寫完一則跑：node test/chinese-idiom.test.js
   出處、人物、朝代、注音、近反義已對過教育部《成語典》（dict.idioms.moe.edu.tw）正文條目（進階版：釋義、典源、典故說明、用法說明、辨識）；故事、解說、例句、題目全部原創。 */
window.DATA_CY = (window.DATA_CY || []).concat([
  // ==================== L1 常用寓言 ====================
  {
    id: 'cy004', lv: 1, word: '井底之蛙', zhuyin: 'ㄐㄧㄥˇ ㄉㄧˇ ㄓ ㄨㄚ', src: '《莊子．秋水》',
    quote: '井鼃不可以語於海者，拘於虛也',
    facts: ['語本《莊子．秋水》：秋天河水上漲，河伯以為天下的美景都在自己這裡，到了北海才知道自己渺小｜教育部《成語典》典源、典故說明', '「井底之蛙」出自北海的海神（北海若）對河伯說的話：不能跟井底的青蛙談大海，因為牠被住的地方限制住了｜《莊子．秋水》', '典源寫作「井鼃」，「鼃」就是「蛙」｜教育部《成語典》注解'],
    story: [
      '秋天到了，一連下了好多天的大雨，大大小小的河流都把水灌進黃河。黃河的河面變得好寬好寬，站在這一岸往對岸看，連對面吃草的是牛還是馬，都分不清楚。',
      '黃河的河神叫做河伯。他看著自己又寬又長的河水，得意得不得了：「哈哈！天下最壯觀、最美麗的景色，全都在我這裡了！」',
      '河伯順著河水一路往東走，想讓大家看看他有多了不起。走著走著，他來到了北海。他往東邊一望，整個人愣住了：眼前是一大片藍色的海水，一直連到天邊，怎麼看也看不到盡頭。',
      '河伯收起了得意的表情，抬起頭，對著北海的海神嘆了一口氣：「俗話說，聽過一點點道理，就以為沒有人比得上自己，說的就是我呀！要不是今天來到這裡，我恐怕會一直被見識廣的人笑話。」',
      '北海的海神說：「住在井底的青蛙，你沒辦法跟牠談大海，因為牠被小小的井限制住了；只活一個夏天的蟲子，你沒辦法跟牠談冰雪，因為牠被短短的時間限制住了。今天你走出河岸，看見了大海，知道自己的不足，我才能跟你談更大的道理。」',
      '接著，海神又說：「我雖然這麼大，可是從來不覺得自己了不起。跟整個天地比起來，我只像大山上的一顆小石子。」',
      '莊子用這個故事提醒我們：一個人眼中的世界有多大，常常被他待的地方限制住。願意走出去、多看多聽，才不會像井底的青蛙一樣，把井口那一小片天空當成全世界。'
    ],
    mean: '住在井底的青蛙，只看得到井口那一小片天空。比喻見識淺薄、眼光狹小的人。',
    usage: ['用來形容見識少，只知道身邊一小塊地方，就以為那是全部的人（貶義）。', '也可以拿來謙虛的說自己見識不多，例如：「我真是井底之蛙，第一次聽說這種東西。」', '「井底之蛙」重在「見識少」；如果重點是「見識少又驕傲自大」，可以用「夜郎自大」。'],
    misuse: [],
    eg: ['這次去科學博物館，我才發現世界上有這麼多我不知道的事，以前的我真像井底之蛙。', '多讀課外書、多出去走走，才不會變成只看得見自己的井底之蛙。'],
    syn: ['坐井觀天', '管中窺豹'], ant: ['見多識廣', '高瞻遠矚'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '河伯一開始為什麼那麼得意？', opts: ['秋天河水上漲，黃河變得又寬又大', '他剛去北海玩過，看過了更大的海', '北海的海神特地跑來黃河稱讚他', '他的河水比大海還要深很多'], a: 0, why: '第一、二段：大雨讓黃河「變得好寬好寬」，河伯就以為天下最美的景色都在他這裡。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '河伯到了北海，往東邊看，看不到海水的盡頭。', a: true, why: '第三段：海水「一直連到天邊，怎麼看也看不到盡頭」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '河伯說「我恐怕會一直被見識廣的人笑話」，表示他心裡明白了什麼？', opts: ['以前把自己看得太了不起了', '黃河的景色其實比北海還要美', '北海的海神其實不歡迎他來', '自己找不到回黃河的路'], a: 0, why: '第四段河伯說「聽過一點點道理，就以為沒有人比得上自己，說的就是我」，他發現自己以前太驕傲了。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '海神同時說到「井底的青蛙」和「夏天的蟲子」，是想說明什麼共同的道理？', opts: ['人的眼光會被自己待的環境限制', '青蛙和蟲子都是又小又笨的動物', '夏天比冬天更適合出門到遠方旅行', '住在井裡比住在海裡更安全'], a: 0, why: '第五段：青蛙被井限制、蟲子被時間限制，都是被自己所在的環境限制住，所以看不見更大的世界。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '北海的海神那麼大，卻說自己「只像大山上的一顆小石子」。你覺得他為什麼這樣說？這跟河伯一開始的態度有什麼不同？',
        ref: '海神知道天地比大海還要大，所以不覺得自己了不起。河伯一開始只看到黃河，就以為自己最厲害。兩個人的差別是：一個知道外面還有更大的世界，所以很謙虛；一個沒看過更大的東西，所以很驕傲。',
        rubric: ['說出海神這樣說的原因（知道天地更大、很謙虛）', '指出河伯一開始的態度（只看到黃河就很得意）', '比較兩者的不同，說法合理'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「井底之蛙」用來形容哪一種人？', opts: ['見識少、眼光狹小的人', '很會游泳、愛玩水的人', '住在鄉下、很少進城的人', '說話很大聲、愛唱歌的人'], a: 0, why: '井底之蛙只看得到井口那片天，比喻見識淺薄的人。重點在見識，不在住哪裡或會不會游泳。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小傑轉魔術方塊只要一分鐘，班上沒有人比他快，他常常說自己一定是全世界最快的。這學期他報名縣內的比賽，才發現很多選手二十秒就轉好了，有個二年級的小朋友還會蒙著眼睛轉。小傑看完比賽，小聲的說：「原來我以前只看到自己身邊這一點點。」', q: '比賽前小傑的想法，最適合用哪個成語形容？', opts: ['井底之蛙', '狐假虎威', '掩耳盜鈴', '亡羊補牢'], a: 0, why: '小傑只跟班上同學比，就以為自己是全世界最快的，見識太窄，就像井底之蛙。狐假虎威是借別人的威風，掩耳盜鈴是自己騙自己，亡羊補牢是出事後補救，都不符合。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈日記〉表姊去國外當了一年交換學生，回來後跟我們分享那裡的學校生活，還說世界上有好多我們沒聽過的節日和食物。她笑著說：「出國以後，我才發現以前的自己是井底之蛙。」', q: '表姊說自己以前是「井底之蛙」，用得恰當嗎？', opts: ['恰當，她是謙虛的說自己以前見識少', '不恰當，因為她家附近並沒有水井', '不恰當，這個成語只能用來罵別人', '恰當，因為她在國外常看到青蛙'], a: 0, why: '井底之蛙可以用來謙虛的說自己見識不多。成語是比喻，跟有沒有水井、青蛙無關。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「哥哥騎腳踏車環島一圈，又讀了好多遊記，見識非常廣，真是井底之蛙。」這句話的「井底之蛙」用得恰當。', a: false, why: '哥哥見識很廣，剛好跟井底之蛙相反，應該說「見多識廣」。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '河伯走出黃河，才知道大海有多大。想一想，你可以用哪些方法「走出自己的井」，讓眼界變大？請舉一個你真的想做的例子。',
        ref: '我可以多去圖書館借不同種類的書，不要只看漫畫。像我一直以為自己很懂恐龍，後來借了一本講海洋生物的書，才發現海裡也有好多我沒聽過的大型動物。我想每個月借一本我平常不會選的書。',
        rubric: ['提出一個讓眼界變大的具體方法', '說明這個方法和故事中「走出去才看得更多」的關係', '例子是自己真的做得到的'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '只待在自己的小圈圈裡，不肯聽聽別人的想法，就很容易變成＿＿＿＿。', opts: ['井底之蛙', '畫蛇添足', '愚公移山', '聞雞起舞'], a: 0, why: '只待在小圈圈、不聽別人的想法，見識就會變窄，用井底之蛙。畫蛇添足是多做多餘的事，愚公移山是堅持不懈，聞雞起舞是及時奮起，放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '校刊社的阿德覺得自己寫的文章最好，從來不讀別人的作品。這次他參加全市的小作家營，讀到各校同學的文章：有人寫家鄉的漁港，有人寫外婆的布袋戲，每一篇都好精彩。阿德紅著臉說：「原來外面有這麼多會寫文章的人，我以前都不知道。」', q: '參加作家營以前，阿德像哪一個成語？', opts: ['井底之蛙', '守株待兔', '狐假虎威', '亡羊補牢'], a: 0, why: '阿德只看自己的文章，不知道外面有很多好作品，眼光太窄，就是井底之蛙。守株待兔是只等好運，狐假虎威是借勢欺人，亡羊補牢是事後補救。' }
    ]
  },
  {
    id: 'cy007', lv: 1, word: '狐假虎威', zhuyin: 'ㄏㄨˊ ㄐㄧㄚˇ ㄏㄨˇ ㄨㄟ', src: '《尹文子》逸文',
    quote: '虎不知獸之畏己而走，以為畏狐也',
    facts: ['典出《尹文子》逸文（據《太平御覽》引）：老虎抓到狐狸，狐狸說天帝派牠當百獸之長，叫老虎跟在後面看｜教育部《成語典》典源', '《戰國策．楚策一》也有這個故事：楚國的江一說給楚宣王聽，比喻北方國家怕的是楚國的大軍，不是將軍昭奚恤｜教育部《成語典》典故說明', '「假」是「借」的意思｜教育部《成語典》釋義'],
    story: [
      '森林裡住著一隻老虎。有一天，牠肚子餓了，就到處找動物來吃。牠一撲，抓住了一隻狐狸。',
      '狐狸心裡怕得要命，臉上卻裝得很鎮定。牠抬起頭說：「你不可以吃我！天帝已經派我當百獸的首領。你要是吃了我，就是違背天帝的命令！」',
      '老虎愣了一下：「真的嗎？我怎麼沒聽說過？」狐狸說：「你不相信的話，我走在前面，你跟在我後面，看看其他動物見到我，會不會嚇得趕快逃走。」',
      '老虎想了想，覺得可以試試看，就跟在狐狸後面。狐狸抬頭挺胸，大搖大擺的走進森林。兔子、山羊、野豬一看到牠們，全都嚇得轉身就跑，一下子就不見了。',
      '老虎看傻了眼，心想：「原來大家這麼怕狐狸！」牠不知道，動物們怕的其實是走在後面的自己。狐狸就這樣借著老虎的威風，保住了性命。',
      '這個故事最早記在《尹文子》這本書裡。後來到了戰國時代，楚國有一個大臣叫江一，也說過這個故事。楚王問大臣們：「北方的國家都很怕我們的將軍昭奚恤，是真的嗎？」江一回答：「他們怕的不是昭奚恤，而是大王交給他帶領的大軍，就像百獸怕的是老虎，不是狐狸一樣。」',
      '後來，人們就用「狐假虎威」來比喻：自己沒有什麼本事，卻借著有權勢的人的威風，去嚇唬、欺負別人。'
    ],
    mean: '狐狸借老虎的威風，把其他野獸嚇跑。比喻借著有權勢的人的威風，去嚇唬、欺負別人。',
    usage: ['用在「自己沒本事，卻借別人的權勢欺負人、作威作福」的情況（貶義）。', '重點是「借別人的威風」。如果是靠自己的本領、讓人真心佩服，就不能說狐假虎威。'],
    misuse: ['「她當上班長以後做事公平又認真，大家都願意聽她的，真是狐假虎威。」✗　班長靠自己的表現讓人信服，沒有借別人的威風。'],
    eg: ['他仗著哥哥是校隊隊長，就在球場上對學弟大呼小叫，簡直是狐假虎威。', '小狗躲在大狗後面，對著路過的貓汪汪叫，一副狐假虎威的樣子。'],
    syn: ['仗勢欺人'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '狐狸用什麼方法讓老虎相信自己？', opts: ['請老虎跟在後面看動物們的反應', '送給老虎一大塊又香又好吃的肉', '帶老虎到天上去見派牠來的天帝', '和老虎比賽看誰跑得快'], a: 0, why: '第三段：狐狸說「我走在前面，你跟在我後面，看看其他動物見到我，會不會嚇得趕快逃走」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '狐狸被老虎抓住的時候，心裡其實很害怕。', a: true, why: '第二段：狐狸「心裡怕得要命，臉上卻裝得很鎮定」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '動物們一看到狐狸和老虎就逃走，真正的原因是什麼？', opts: ['牠們怕的是走在後面的老虎', '牠們相信天帝派了狐狸當首領', '狐狸平常就很會欺負別的動物', '森林裡突然颳起了一陣大風'], a: 0, why: '第五段：「動物們怕的其實是走在後面的自己」，也就是老虎。動物們並沒有聽到狐狸說天帝的事。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '江一用這個故事回答楚王，他把將軍昭奚恤比作故事裡的誰？', opts: ['借老虎威風的狐狸', '被嚇跑的小動物', '跟在後面的老虎', '派任首領的天帝'], a: 0, why: '第六段：北方國家怕的是楚王的大軍（像老虎），不是昭奚恤本人，所以昭奚恤就像走在前面的狐狸。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '有人覺得狐狸很聰明，用頭腦救了自己；也有人覺得狐狸的做法不好。你的看法是什麼？請用故事內容說明理由。',
        ref: '我覺得狐狸在危險的時候想出辦法救自己，是很聰明的。可是牠是用騙的，讓動物們以為大家怕的是牠。如果牠以後一直靠老虎的威風嚇別人，自己卻沒有真本事，總有一天會被拆穿。',
        rubric: ['清楚說出自己的看法', '用故事內容當理由（例如狐狸是借老虎的威風、動物怕的是老虎）', '想到這種做法可能帶來的問題或限制'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「狐假虎威」的「假」是什麼意思？', opts: ['借', '不真的', '放假', '如果'], a: 0, why: '這裡的「假」是借，「狐假虎威」就是狐狸借老虎的威風。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '糾察隊的阿凱負責在走廊提醒同學不要奔跑。他的表弟小宇不是糾察隊，卻常常跟在阿凱旁邊，對低年級的小朋友大聲說：「我表哥是糾察隊，你們再跑，我就叫他把你們的名字記下來！」低年級的小朋友看到小宇都很害怕，其實阿凱從來沒有這樣說過。', q: '小宇的行為，最適合用哪個成語形容？', opts: ['狐假虎威', '老馬識途', '井底之蛙', '掩耳盜鈴'], a: 0, why: '小宇自己不是糾察隊，卻借表哥的身分嚇唬別人，就是狐假虎威。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈班級日記〉這學期的班長小芸做事很公平，大家都願意聽她的安排。今天打掃時有同學在聊天，小芸好聲好氣的提醒，同學馬上就去拿掃把了。阿明說：「班長真會狐假虎威。」', q: '阿明用「狐假虎威」形容班長，用得恰當。', a: false, why: '小芸是靠自己公平、有禮貌讓大家信服，沒有借別人的威風，也沒有欺負人，不能說狐假虎威。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「那隻小貓仗著主人站在旁邊，對著門口的大狗哈氣，有點狐假虎威。」這句話的「狐假虎威」用得恰當。', a: true, why: '小貓靠主人在旁邊撐腰，才敢對大狗兇，就是借別人的威風，用得恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '如果你看到有同學借別人的勢力嚇唬人（例如「我哥哥很兇，你小心一點」），你會怎麼做？請說出你的做法和理由。',
        ref: '我會先陪在被嚇的同學旁邊，跟他說不用怕。然後告訴那個同學：「你哥哥很兇是你哥哥的事，你自己這樣說話會讓別人不舒服。」如果他還是一直這樣，我會請老師幫忙處理。',
        rubric: ['提出具體的做法（例如安慰被嚇的人、提醒對方、找大人幫忙）', '說明理由（例如借別人的威風欺負人不對）', '做法安全、合理'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '他自己沒什麼本事，只會拿老闆的名字去壓別人，真是＿＿＿＿。', opts: ['狐假虎威', '愚公移山', '聞雞起舞', '畫龍點睛'], a: 0, why: '拿老闆的名字壓人，是借別人的權勢，用狐假虎威。另外三個都是正面意思，放進句子不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'mc', ctx: '〈社區報〉某大樓的管委會請了一位新主委。主委的鄰居阿伯常常拿「這是主委說的」當理由，要其他住戶把腳踏車移到他指定的地方，大家不敢拒絕，背後都說他狐假虎威。', q: '住戶們用「狐假虎威」形容這位阿伯，恰當嗎？', opts: ['恰當，他借主委的名義讓別人聽他的', '不恰當，住戶本來就要聽主委的話', '恰當，因為阿伯說話的聲音很大', '不恰當，這個成語只能用在動物'], a: 0, why: '阿伯自己沒有權力，卻借主委的名義叫別人照做，就是狐假虎威。成語是比喻，不是只能用在動物身上。' }
    ]
  },
  {
    id: 'cy010', lv: 1, word: '掩耳盜鈴', zhuyin: 'ㄧㄢˇ ㄦˇ ㄉㄠˋ ㄌㄧㄥˊ', src: '《呂氏春秋．不苟論．自知》',
    quote: '恐人聞之而奪己也，遽揜其耳',
    facts: ['典出《呂氏春秋．不苟論．自知》：晉國的范氏滅亡時，有人想把一口大鐘背走｜教育部《成語典》典源', '典源寫的是「鍾」（同「鐘」），後來才說成「鈴」｜教育部《成語典》釋義', '《呂氏春秋》用這個故事說明：當國君的人討厭聽到自己的過錯，就像摀住耳朵偷鐘的人一樣糊塗｜《呂氏春秋．不苟論．自知》'],
    story: [
      '春秋時代，晉國有一個很有勢力的大家族，叫做范氏。後來范氏被別人打敗，整個家族垮了，大宅院也沒有人看管，有些人就趁亂跑進去拿東西。',
      '有一個人走進范家，看到院子裡掛著一口大鐘。這口鐘是用青銅做的，上面刻著漂亮的花紋，一看就很值錢。他心想：「要是能把它搬回家，我就發財了！」',
      '他彎下腰，用肩膀頂住大鐘，使出全身的力氣，可是鐘動也不動。原來這口鐘太大、太重了，他根本背不動。',
      '他又想了一個辦法：「背不動，那就把鐘敲碎，一塊一塊拿回去！」他找來一把大鐵錘，朝鐘用力一敲。「噹——」鐘發出好大好響的聲音，震得他耳朵嗡嗡叫。',
      '他嚇了一大跳：「糟了！這麼大的聲音，別人一定會聽到，跑來跟我搶！」他急忙用兩隻手緊緊摀住自己的耳朵。咦？聲音好像變小了。他高興的想：「我聽不到，別人應該也聽不到吧！」',
      '其實，他摀住的只是自己的耳朵，鐘聲還是一樣傳到很遠很遠的地方。',
      '《呂氏春秋》說：怕別人聽到鐘聲，還說得過去；以為自己聽不到就沒事了，那就太糊塗了。當國君的人如果討厭別人指出自己的錯，不就跟這個摀住耳朵的人一樣嗎？',
      '原本的故事偷的是「鐘」，後來大家說成了「鈴」，就變成今天的「掩耳盜鈴」，用來比喻自己騙自己，還以為別人也被騙了。'
    ],
    mean: '偷鐘的人怕鐘聲被聽見，就摀住自己的耳朵。比喻想要瞞騙別人，結果只是騙了自己。',
    usage: ['用在「事情明明藏不住，卻自以為別人不知道」的情況，是諷刺的意思（貶義）。', '「自欺欺人」是既騙自己、也騙別人；「掩耳盜鈴」強調其實只騙到自己，別人早就知道了。', '只是怕吵、把耳朵摀起來，不能用掩耳盜鈴。'],
    misuse: [],
    eg: ['考卷藏在抽屜裡不給爸媽看，成績還是會出現在聯絡簿上，這樣掩耳盜鈴有什麼用呢？', '把髒衣服全塞進衣櫃，以為媽媽看不到，根本是掩耳盜鈴。'],
    syn: ['自欺欺人', '掩目捕雀'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '那個人為什麼想把鐘敲碎？', opts: ['鐘太大太重，他背不動', '他不喜歡鐘上面的花紋', '鐘已經壞了，敲不出聲音', '范家的主人叫他敲碎'], a: 0, why: '第三、四段：鐘「太大、太重了，他根本背不動」，所以想敲碎了一塊一塊拿。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '他摀住耳朵以後，鐘聲就不會傳到別人那裡了。', a: false, why: '第六段：「他摀住的只是自己的耳朵，鐘聲還是一樣傳到很遠很遠的地方。」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '他摀住耳朵以後很高興，是因為他誤以為什麼？', opts: ['自己聽不到，別人也聽不到', '鐘已經被他敲成碎片了', '范家的人都已經搬走了', '鐘聲可以幫他嚇走小偷'], a: 0, why: '第五段：他想「我聽不到，別人應該也聽不到吧」。這是他自己騙自己。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '《呂氏春秋》把「討厭聽到自己錯誤的國君」比作摀耳朵的人，兩者哪裡一樣？', opts: ['都以為不去聽，問題就不存在', '都很喜歡收集值錢的大鐘', '都住在很大很大的宅院裡', '都怕別人來搶自己的東西'], a: 0, why: '第七段：摀住耳朵，鐘聲還在；不聽別人指出的錯，錯也還在。兩者都是假裝問題不存在。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '這個故事除了笑那個人很糊塗，你覺得還想提醒我們什麼？請用故事最後兩段，再加上你自己的生活經驗說明。',
        ref: '故事提醒我們，不想聽的話不代表不存在。像國君不聽別人說他的錯，錯還是在那裡。我以前不喜歡聽媽媽說我寫字太潦草，就裝作沒聽到，結果考試時老師看不懂我的答案，被扣了分。',
        rubric: ['說出故事的提醒（假裝聽不到，問題還是存在）', '用到故事最後兩段的內容（國君不聽別人指出錯誤）', '舉出一個自己的生活經驗'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「掩耳盜鈴」的「掩」是什麼意思？', opts: ['遮住', '打開', '拉長', '清洗'], a: 0, why: '「掩」是遮住，「掩耳」就是把耳朵摀起來。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小凱在客廳玩球，打破了媽媽最喜歡的花瓶。他把碎片掃進沙發底下，再拿一個顏色差不多的空瓶子擺在原來的位置，心想：「這樣媽媽就看不出來了。」沒想到媽媽一回家，就發現瓶子的形狀不一樣，地上還有一小片沒掃乾淨的碎片。', q: '小凱的做法，最適合用哪一個成語形容？', opts: ['掩耳盜鈴', '狐假虎威', '朝三暮四', '井底之蛙'], a: 0, why: '小凱以為把碎片藏起來、換個瓶子就沒人發現，其實一看就知道，只騙到自己，就是掩耳盜鈴。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈新聞短評〉某工廠把髒水偷偷排進河裡，再在河邊立了一塊「本廠重視環保」的大看板。可是河水早就變了顏色，附近的居民也都知道是怎麼回事。評論說：「這種做法無異掩耳盜鈴。」', q: '評論用「掩耳盜鈴」恰當嗎？', opts: ['恰當，工廠以為立看板就能瞞過大家', '不恰當，工廠並沒有偷任何人的鈴', '不恰當，工廠立看板代表很重視環保', '恰當，因為工廠的看板做得非常大'], a: 0, why: '河水變色、居民都知道，工廠卻以為立個看板就能瞞過去，只是騙自己，用掩耳盜鈴恰當。成語是比喻，不是真的要偷鈴。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「門口的監視器拍得一清二楚，他卻以為把帽子壓低就沒人認得出他，真是掩耳盜鈴。」這句話的「掩耳盜鈴」用得恰當。', a: true, why: '監視器拍得很清楚，他卻以為壓低帽子就能瞞過去，是自己騙自己，用得恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '有時候我們會像故事裡的人一樣，不想面對問題，就假裝它不存在（例如作業沒寫完、東西弄壞了）。請想一個例子，說說「摀住耳朵」會有什麼結果，比較好的做法又是什麼。',
        ref: '我借了同學的橡皮擦弄丟了，一開始想說不要提，他大概會忘記。可是他一定會找，到時候會更不高興。比較好的做法是直接跟他說對不起，再買一個新的還他。',
        rubric: ['舉出一個「假裝問題不存在」的具體例子', '說出逃避可能帶來的結果', '提出面對問題的做法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '明明大家都看到他把球踢進鄰居的院子，他卻躲進屋裡，以為沒人知道是他，這不是＿＿＿＿嗎？', opts: ['掩耳盜鈴', '聞雞起舞', '愚公移山', '畫龍點睛'], a: 0, why: '大家都看到了，他卻以為躲起來就沒人知道，是自己騙自己，用掩耳盜鈴。聞雞起舞、愚公移山是正面的努力，畫龍點睛是加上關鍵的一筆，放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉今天放學，一輛消防車鳴著笛從校門口開過去，聲音好大好刺耳，我趕快掩耳盜鈴，把耳朵摀起來。', q: '日記裡的「掩耳盜鈴」用得恰當。', a: false, why: '怕吵把耳朵摀起來，只是動作像「掩耳」，沒有「自己騙自己」的意思，不能用掩耳盜鈴。' }
    ]
  },
  {
    id: 'cy013', lv: 1, word: '朝三暮四', zhuyin: 'ㄓㄠ ㄙㄢ ㄇㄨˋ ㄙˋ', src: '《莊子．齊物論》',
    quote: '狙公賦芧，曰：「朝三而暮四。」眾狙皆怒',
    facts: ['典出《莊子．齊物論》：養猴人「狙公」分橡實給猴子，說早上三升、晚上四升，猴子都生氣；改成早上四升、晚上三升，猴子都高興｜教育部《成語典》典源、典故說明', '「狙」是猴子，「芧」是橡樹的果實｜教育部《成語典》典故說明', '原本比喻只改名目、不改實質；後來比喻人心意不定、反覆無常｜教育部《成語典》釋義'],
    story: [
      '從前有一個很喜歡猴子的老人，家裡養了一大群猴子，大家都叫他「狙公」。「狙」就是猴子的意思。',
      '狙公每天都餵猴子吃橡樹的果實。這種果實圓圓的、硬硬的，猴子們最愛吃了。',
      '有一天，狙公想了一個新的分配方法。他把猴子們叫過來，說：「從今天開始，早上給你們三升橡果，晚上給四升，好不好？」',
      '猴子們一聽，全都跳了起來，又叫又抓，非常生氣：「早上才三升？太少了！太少了！」',
      '狙公想了想，笑著說：「那好吧，改成早上四升、晚上三升，這樣可以嗎？」猴子們一聽，馬上安靜下來，還高興得拍手、翻跟斗。',
      '你算一算：三加四是七，四加三也是七。猴子們一天吃到的橡果，一顆也沒有變多，改變的只是早上和晚上的順序。可是猴子們卻一下生氣、一下高興。',
      '莊子說這個故事，是想告訴大家：很多人就像這群猴子，只要說法換一換，就跟著又生氣又開心，卻沒有看清楚，事情的實際內容其實根本沒變。',
      '「朝三暮四」本來的意思是「只換說法，實際內容沒有改變」。後來大家用著用著，意思慢慢變了。今天我們多用它來形容一個人心意不定，一下這樣、一下那樣，反覆無常。'
    ],
    mean: '原本是說早上三升、晚上四升，改成早上四升、晚上三升，總數一樣，猴子卻轉怒為喜。原比喻只改說法、不改實質；今天多比喻心意不定、反覆無常。',
    usage: ['今天用來批評人心意不定，想法或做法一下變一下（貶義）。', '讀古書時要知道它原本的意思：換個說法讓人高興，實際內容並沒有改變。', '形容人答應了又反悔，也可以用「出爾反爾」，兩個成語都有反覆的意思。'],
    misuse: [],
    eg: ['小明這學期換了四個才藝班，每個都只上兩堂就不去了，大家都說他朝三暮四。', '選班服顏色時你一下說藍色、一下說紅色，這樣朝三暮四，大家要怎麼決定？'],
    syn: ['反覆無常', '朝秦暮楚'], ant: ['始終如一', '堅定不移'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '狙公第一次說的分法是什麼？', opts: ['早上三升，晚上四升', '早上四升，晚上三升', '早上晚上都是三升', '早上不給，晚上七升'], a: 0, why: '第三段：「早上給你們三升橡果，晚上給四升。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '改成「早上四升、晚上三升」以後，猴子們一天吃到的橡果變多了。', a: false, why: '第六段：三加四是七，四加三也是七，「一顆也沒有變多」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '猴子們聽到第二種分法，為什麼就高興了？', opts: ['以為早上變多，就是占到便宜', '狙公又多送了牠們一些香蕉', '晚上吃得少可以早點睡覺', '牠們不用再自己去找食物'], a: 0, why: '猴子們只看到早上從三升變成四升，就以為自己占到便宜，沒想到晚上少了一升。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '莊子說這個故事，想提醒人們什麼？', opts: ['只看表面說法，會看不清實際內容', '養猴子一定要把食物平均分配', '早上一定要吃得比晚上還多', '猴子其實比養猴子的人聰明'], a: 0, why: '第七段：很多人「只要說法換一換」就跟著生氣或開心，「沒有看清楚」實際內容根本沒變。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '狙公只換了順序，猴子就從生氣變高興。你覺得狙公的做法聰明嗎？如果你是那群猴子裡的一隻，你會怎麼想？請說明理由。',
        ref: '狙公很會說話，不用多花橡果就讓猴子安靜，算是聰明。可是他其實是在騙猴子。如果我是猴子，我會先算一算總共幾升，發現都是七升，就知道換順序沒有差別，不會因為這樣就生氣或高興。',
        rubric: ['對狙公的做法提出看法並說出理由', '用故事內容當根據（總數都是七升、只換順序）', '說出自己站在猴子的立場會怎麼想'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '今天說一個人「朝三暮四」，是在說他怎麼樣？', opts: ['心意不定，一下這樣一下那樣', '每天早上很早就起床讀書', '一天要吃很多頓飯才會飽', '很會算加法和減法的題目'], a: 0, why: '今天的「朝三暮四」多用來形容心意不定、反覆無常。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '五年四班的小組要做科展。組長阿翔第一週說要研究植物，第二週又說改做磁鐵，第三週看到別組做火山爆發，又想換成火山。組員們每次都得重新找資料、重新買材料。到了截止那天，他們連題目都還沒決定，只好放棄報名。', q: '阿翔做決定的方式，最適合用哪一個成語形容？', opts: ['朝三暮四', '掩耳盜鈴', '井底之蛙', '狐假虎威'], a: 0, why: '阿翔的想法一週換一次，心意不定，就是朝三暮四。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈部落格〉巷口早餐店把價目表從「蛋餅二十五元，加蛋十元」改成「加蛋蛋餅三十五元，不加蛋減十元」，價錢其實一模一樣，客人卻覺得新寫法比較划算。網友留言：「老闆這招就像朝三暮四裡的狙公。」', q: '網友這樣說，是用了「朝三暮四」的哪一個意思？', opts: ['原本的意思：換個說法，實際內容不變', '今天的意思：老闆的心意一直在改變', '今天的意思：老闆每天賣三四種早餐', '原本的意思：老闆早上晚上都有開店'], a: 0, why: '價錢一樣，只是換個寫法讓客人高興，正是狙公「只換說法、不改實際」的原意。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '這些成語跟「朝三暮四」（今天的意思）是什麼關係？配起來。', pairs: [['反覆無常', '意思相近'], ['始終如一', '意思相反'], ['聞雞起舞', '意思無關']], why: '反覆無常是變來變去，跟朝三暮四相近；始終如一是從頭到尾都一樣，剛好相反；聞雞起舞是及時奮起，跟這件事無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '莊子笑猴子只看表面。生活中的商品折扣、集點活動，有時也會換個說法讓人覺得占便宜。請舉一個例子，說說你會怎麼算一算，看清楚實際內容。',
        ref: '有一次文具店寫「買三送一」，另一家寫「打七五折」。我算了一下，買四個只付三個的錢，也是七五折，兩家其實一樣。以後看到不同的說法，我會先算出一個要多少錢，再決定要不要買。',
        rubric: ['舉出一個生活中「換說法」的例子', '說出自己怎麼計算或比較實際內容', '連結到故事「只看表面」的提醒'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 1, type: 'tf', q: '「她從小學鋼琴，練了六年從來沒有放棄，真是朝三暮四。」這句話的「朝三暮四」用得恰當。', a: false, why: '練了六年從不放棄，是始終如一，剛好跟朝三暮四相反。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '社區合唱團選團長時，阿凱第一天說要投給小美，第二天聽說小華會帶大家去郊遊，又說要投小華；第三天小美說要辦慶功會，他又改口說投小美。到了投票那天，他還在兩個人之間換來換去，兩邊的團員都不太相信他了。', q: '阿凱在選團長時的表現，像哪一個成語？', opts: ['朝三暮四', '愚公移山', '聞雞起舞', '驚弓之鳥'], a: 0, why: '阿凱一天一個想法、反覆不定，就是朝三暮四。愚公移山、聞雞起舞是堅持和奮發，驚弓之鳥是受過驚嚇而害怕。' }
    ]
  },
  {
    id: 'cy016', lv: 1, word: '驚弓之鳥', zhuyin: 'ㄐㄧㄥ ㄍㄨㄥ ㄓ ㄋㄧㄠˇ', src: '《戰國策．楚策四》',
    quote: '其飛徐而鳴悲。飛徐者，故瘡痛也；鳴悲者，久失群也',
    facts: ['典出《戰國策．楚策四》：趙國使者魏加用更羸「虛發而下鳥」的故事，勸楚國的春申君不要派臨武君當抗秦的大將｜教育部《成語典》典源、典故說明', '更羸說那隻雁飛得慢、叫聲悲傷，是因為舊傷在痛、又離群很久｜《戰國策．楚策四》', '臨武君曾經被秦國打敗過｜教育部《成語典》典故說明'],
    story: [
      '戰國時代，好幾個國家決定聯合起來，對抗強大的秦國。趙國派了使者魏加到楚國，跟楚國的宰相春申君商量帶兵的事。',
      '魏加問：「您打算派誰當大將？」春申君說：「我想派臨武君。」魏加沒有直接說好或不好，而是說：「我年輕的時候很喜歡射箭，可以用射箭的事打個比方嗎？」春申君說：「請說。」',
      '魏加說：「從前，魏國有個射箭高手叫更羸。有一天，他陪魏王站在高臺下，抬頭看見天上有鳥飛過。更羸說：『大王，我不用箭，只要拉一下弓弦，就能讓鳥掉下來。』魏王不太相信：『射箭的本領能厲害到這種地步嗎？』」',
      '「過了一會兒，一隻大雁從東邊飛過來。更羸舉起弓，拉滿弦，手一放，『嗡』的一聲，並沒有射出箭，那隻大雁卻真的掉了下來。」',
      '「魏王驚訝極了。更羸解釋：『這是一隻受過傷的雁。牠飛得慢，是因為舊傷還在痛；叫聲悲傷，是因為牠離開雁群很久了。舊傷沒好，心裡又一直害怕，一聽到弓弦的聲音，就拚命往高處飛，一用力，傷口裂開，就掉下來了。』」',
      '說完故事，魏加對春申君說：「臨武君以前被秦國打敗過，心裡還有陰影，就像那隻受過傷的雁。讓他當對抗秦國的大將，恐怕不太合適啊！」',
      '後來，人們就用「驚弓之鳥」來比喻：曾經受過打擊或驚嚇的人，心裡還很害怕，稍微有一點動靜就緊張起來。'
    ],
    mean: '受過箭傷的鳥，一聽到弓弦的聲音就驚慌失措。比喻曾經受過打擊或驚嚇，心有餘悸，稍有動靜就害怕的人。',
    usage: ['用來形容「以前受過驚嚇或打擊，所以變得特別容易害怕」的人。', '重點是「曾經受過驚嚇」。天生膽子比較小，或是第一次遇到新環境會緊張，都不能說是驚弓之鳥。'],
    misuse: [],
    eg: ['上次被狗追過以後，弟弟就像驚弓之鳥，一聽到狗叫就躲到我身後。', '那次地震把小美嚇壞了，現在卡車經過、窗戶輕輕震動，她都像驚弓之鳥一樣跳起來。'],
    syn: ['心有餘悸', '談虎色變'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '更羸用什麼方法讓大雁掉下來？', opts: ['只拉弓弦，沒有射出箭', '射出一支又長又快的箭', '朝大雁丟出一顆石頭', '大聲喊叫把大雁嚇跑'], a: 0, why: '第四段：更羸「拉滿弦，手一放」，「並沒有射出箭」，大雁卻掉了下來。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '魏加是楚國的宰相。', a: false, why: '第一段：魏加是趙國派到楚國的使者；楚國的宰相是春申君。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '魏加為什麼不直接說臨武君不合適，而要先講射箭的故事？', opts: ['想用比喻，讓春申君自己想通', '他只會講跟射箭有關的事', '春申君規定只能用講故事的', '他想炫耀自己的射箭本領'], a: 0, why: '魏加先講受傷的雁，再說臨武君「就像那隻受過傷的雁」。用比喻說道理，比直接反對更容易讓人接受。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '魏加把臨武君比作故事裡的什麼？', opts: ['受過傷、一聽弓聲就驚慌的雁', '只拉弓不放箭的那位射箭高手', '站在高臺下看鳥的魏王', '從東邊慢慢飛過來的一群大雁'], a: 0, why: '第六段：臨武君被秦國打敗過，「心裡還有陰影，就像那隻受過傷的雁」。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '你覺得春申君應該聽魏加的建議嗎？一個曾經失敗過的人，就不能再擔任重要的工作嗎？請說說你的看法和理由。',
        ref: '我覺得魏加說得有道理，因為臨武君心裡還怕秦國，打仗時可能一緊張就做錯決定。不過失敗過的人也不是永遠不行，如果他能慢慢克服害怕、重新練習，以後還是可以擔任重要的工作。',
        rubric: ['表明自己的看法', '用故事內容當理由（例如受傷的雁一聽弓聲就驚慌）', '想到另一面（失敗過的人能不能重新站起來）'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「驚弓之鳥」形容的是哪一種人？', opts: ['受過驚嚇，一有動靜就怕', '很會射箭、總是百發百中', '喜歡養鳥、細心照顧動物', '跑得很快、反應很好'], a: 0, why: '驚弓之鳥是受過傷的鳥，一聽到弓弦聲就害怕，比喻曾受驚嚇、一點動靜就害怕的人。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小安上個月騎腳踏車時，被一台突然倒車的汽車擦撞，雖然只是擦傷，卻嚇得好幾天都睡不好。現在他走在路上，只要聽到汽車按喇叭或引擎發動的聲音，就會馬上停下來，緊緊抓住媽媽的手，連過斑馬線都要等好久才敢走。', q: '小安現在的樣子，最適合用哪個成語形容？', opts: ['驚弓之鳥', '井底之蛙', '朝三暮四', '夜郎自大'], a: 0, why: '小安被車撞過，現在一聽到車聲就害怕，正是驚弓之鳥。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉新同學阿哲今天第一天來上學，看到教室裡有好多不認識的人，有點緊張，一直低著頭不說話。我覺得他就像驚弓之鳥。', q: '用「驚弓之鳥」形容第一天上學有點緊張的阿哲，是恰當的。', a: false, why: '阿哲只是到新環境會緊張，並沒有「曾經受過驚嚇或打擊」，不能說是驚弓之鳥。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「被詐騙電話騙過一次以後，奶奶就成了驚弓之鳥，現在看到陌生的號碼都不敢接。」這句話的「驚弓之鳥」用得恰當。', a: true, why: '奶奶受過騙，所以一看到陌生號碼就害怕，用驚弓之鳥恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '如果你的朋友因為一次不好的經驗（例如上台忘詞、被狗追），變成了「驚弓之鳥」，你會怎麼幫他，讓他慢慢不再那麼害怕？',
        ref: '如果朋友上台忘詞以後不敢再上台，我會先陪他在下課時對著我一個人練習，再找三四個好朋友當觀眾，讓他一次一次習慣。他每做到一次，我就稱讚他，讓他知道上次只是意外。',
        rubric: ['說出朋友受過什麼驚嚇', '提出具體、一步一步的幫忙方法', '方法有照顧到朋友的感受'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '自從那次在遊樂園走失以後，表妹就像＿＿＿＿，一離開媽媽身邊就緊張得想哭。', opts: ['驚弓之鳥', '井底之蛙', '狐假虎威', '愚公移山'], a: 0, why: '表妹走失過，所以一離開媽媽就害怕，用驚弓之鳥。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '籃球隊的阿傑上學期比賽時被撞倒，扭傷了腳踝。傷好以後回到球場，只要有人朝他衝過來，他就趕快把球傳出去，再也不敢切入上籃。教練說他的技術一點也沒有退步，只是心裡還記得那次受傷的感覺。', q: '阿傑回到球場以後的樣子，像哪一個成語？', opts: ['驚弓之鳥', '朝三暮四', '掩耳盜鈴', '夜郎自大'], a: 0, why: '阿傑受過傷，一看到有人衝過來就害怕，像聽到弓弦聲就驚慌的雁。' }
    ]
  },
  {
    id: 'cy019', lv: 1, word: '愚公移山', zhuyin: 'ㄩˊ ㄍㄨㄥ ㄧˊ ㄕㄢ', src: '《列子．湯問》',
    quote: '子子孫孫，無窮匱也，而山不加增，何苦而不平',
    facts: ['典出《列子．湯問》：北山愚公年近九十，苦於太行、王屋兩座山擋路，帶著子孫挖山｜教育部《成語典》典源', '河曲智叟笑愚公不聰明；天帝被愚公的誠心感動，命夸蛾氏的兩個兒子把山背走｜教育部《成語典》典故說明', '「愚公移山」比喻努力不懈，終能達成目標；也可以比喻效率不佳｜教育部《成語典》釋義、用法說明'],
    story: [
      '很久以前，有兩座大山，一座叫太行山，一座叫王屋山，又高又大，方圓有七百里。',
      '山的北邊住著一位快九十歲的老人，大家叫他「北山愚公」。他家正對著這兩座大山，每次出門都要繞好遠好遠的路。',
      '有一天，愚公把全家人叫來：「我們一起把這兩座山剷平，開出一條直直的路，通到南方，好不好？」大家都說好。只有愚公的太太提出疑問：「憑你的力氣，連一座小土丘都挖不平，怎麼搬得動大山？挖出來的土石要放在哪裡？」家人說：「可以運到渤海的邊上去。」',
      '於是愚公帶著三個能挑擔子的子孫，敲石頭、挖泥土，用畚箕一擔一擔運到渤海邊。鄰居家才七八歲的小男孩，也蹦蹦跳跳的跑來幫忙。他們來回一趟，季節就換了。',
      '住在黃河轉彎處的「智叟」看了，笑著勸他：「你真是太不聰明了！年紀這麼大，連山上的一根草都動不了，還想搬走大山？」',
      '愚公長長的嘆了一口氣：「你的想法太頑固了，還比不上那個小孩子。就算我不在了，還有我的兒子；兒子又生孫子，孫子又生兒子，子子孫孫沒有窮盡。可是山不會再長高，為什麼會挖不平呢？」智叟聽了，說不出話來。',
      '山神聽說了這件事，怕愚公真的一直挖下去，趕快去報告天帝。天帝被愚公的誠心感動，派大力士夸蛾氏的兩個兒子，把兩座山背走了。從此，那裡再也沒有大山擋路。',
      '後來，「愚公移山」就用來比喻做事有恆心、努力不懈，最後一定能達成目標。'
    ],
    mean: '愚公帶著子孫挖山，決心把擋路的大山剷平。比喻做事有恆心、努力不懈，最後終能達成目標。',
    usage: ['多用來稱讚人有毅力、不怕困難，一步一步完成大目標（褒義）。', '《成語典》也收了另一個用法：比喻做事方法慢、效率不好。要看上下文判斷是稱讚還是批評。', '做到一半就放棄，要說「半途而廢」，跟愚公移山相反。'],
    misuse: [],
    eg: ['林伯伯每天清晨去撿海灘上的垃圾，十年來從沒停過，這種愚公移山的精神讓人佩服。', '整本單字書看起來很厚，但只要每天背五個，像愚公移山一樣，總有背完的一天。'],
    syn: ['精衛填海', '鐵杵磨針'], ant: ['半途而廢'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '愚公為什麼想把山剷平？', opts: ['山擋在家門前，出門要繞遠路', '他想用山上的石頭蓋新房子', '天帝下命令要他把山搬走', '他想在山的地方種稻子'], a: 0, why: '第二段：他家正對著大山，「每次出門都要繞好遠好遠的路」。' },
      { id: 'r2', p: 1, d: 1, type: 'order', q: '請依照故事發生的先後排好。', items: ['愚公召集家人商量挖山', '鄰居的小男孩跑來幫忙', '智叟笑愚公太不聰明', '天帝派人把山背走'], why: '第三段商量 → 第四段小男孩幫忙 → 第五段智叟笑他 → 第七段天帝派人背走山。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '愚公說智叟「還比不上那個小孩子」，意思是什麼？', opts: ['小孩肯動手幫忙，智叟只會笑人', '小孩挖土的速度比智叟快很多', '小孩的年紀小，所以力氣更大', '小孩早就知道山會越長越高'], a: 0, why: '小男孩蹦蹦跳跳來幫忙（第四段），智叟卻只在旁邊笑愚公（第五段）。愚公是說智叟的想法還不如願意動手的小孩。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '愚公相信山一定挖得平，他的理由是什麼？', opts: ['子孫一代接一代，山卻不會長高', '智叟答應要找全村的人一起來幫忙', '他的力氣比村裡一般人大很多', '渤海很近，運土石很方便'], a: 0, why: '第六段：「子子孫孫沒有窮盡。可是山不會再長高。」人一直挖、山不會變高，總有挖平的一天。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '智叟說愚公「不聰明」，愚公卻說智叟「頑固」。你比較同意誰？請用故事內容說明你的理由。',
        ref: '我比較同意愚公。智叟只看到愚公年紀大、山很大，就覺得不可能。愚公想到的是一代接一代一直做，山又不會長高，所以總有一天會成功。不過我也覺得智叟有一點道理，因為這樣真的要花很久，也許可以想想有沒有更好的辦法。',
        rubric: ['清楚說出比較同意誰', '用故事內容當理由（例如子孫不斷、山不會長高）', '理由前後說得通，能想到另一方的想法更好'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「愚公移山」最常用來稱讚哪一種精神？', opts: ['不怕困難、堅持到底', '力氣很大、什麼都搬得動', '年紀很大、經驗非常豐富', '喜歡爬山、親近大自然'], a: 0, why: '愚公移山比喻做事有恆心、努力不懈，最後達成目標。重點不是力氣大，也不是年紀大。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '社區旁的小溪以前堆滿垃圾，又髒又臭。五年前，林伯伯開始每個週末去撿垃圾，一開始鄰居都說：「那麼多，撿不完啦。」林伯伯還是一包一包的撿。後來里長、鄰居和附近的小學生也一起加入。今年夏天，溪水終於變清了，還有人看到小魚在游。', q: '林伯伯和大家整理小溪的過程，最適合用哪個成語形容？', opts: ['愚公移山', '掩耳盜鈴', '朝三暮四', '杯弓蛇影'], a: 0, why: '大家都說撿不完，林伯伯還是一直做，最後達成目標，就是愚公移山。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈作文〉我想學會彈吉他，可是練了三天，手指好痛，我就把吉他收進衣櫃，再也沒有拿出來過。我覺得自己很有愚公移山的精神。', q: '作文裡的「愚公移山」用得恰當嗎？', opts: ['不恰當，練三天就放棄，像是半途而廢', '恰當，因為練吉他跟挖山一樣辛苦', '恰當，因為他有想學會吉他的目標', '不恰當，這個成語只能用在搬東西'], a: 0, why: '愚公移山是堅持到底。只練三天就放棄，剛好相反，是半途而廢。成語是比喻，不是只能用在搬東西。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '下面哪一個成語，意思和「愚公移山」相反？', opts: ['半途而廢', '精衛填海', '鐵杵磨針', '持之以恆'], a: 0, why: '愚公移山是堅持到底；半途而廢是做到一半就放棄，意思相反。精衛填海、鐵杵磨針、持之以恆都是相近的意思。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '愚公的目標很大，但他用「一擔一擔慢慢運」的方法。請選一個你覺得很難的目標，像愚公一樣把它分成小步驟，說說你每天可以做什麼。',
        ref: '我想要能一口氣跑完一千公尺。我會先從每天跑兩圈操場開始，每個星期多跑半圈，再記錄每次跑的時間。就算哪一天下雨不能跑，我也可以在家做跳繩，讓自己一直保持練習。',
        rubric: ['說出一個具體的大目標', '把目標分成每天做得到的小步驟', '說明遇到困難時怎麼繼續堅持'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '這條登山步道是志工們花了十年，一鏟一鏟用手挖出來的，憑的就是一股＿＿＿＿的精神。', opts: ['愚公移山', '狐假虎威', '井底之蛙', '朝三暮四'], a: 0, why: '花十年一鏟一鏟完成，是堅持不懈，用愚公移山。其他三個都是負面意思，放進句子不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '小真想把一千片的拼圖拼完，光是天空就有好幾百片藍色碎片，看起來都一樣。她不著急，每天晚上拼二十片，先拼外框，再照顏色深淺分類。遇到怎麼也找不到的那一片，她就先跳過，隔天再找。兩個月後，一整幅星空終於掛在她房間的牆上了。', q: '小真拼拼圖的方式，像哪一個成語？', opts: ['愚公移山', '畫蛇添足', '驚弓之鳥', '夜郎自大'], a: 0, why: '目標很大，她每天做一點、不放棄，最後完成，就像愚公一擔一擔挖山。' }
    ]
  },
  {
    id: 'cy022', lv: 1, word: '聞雞起舞', zhuyin: 'ㄨㄣˊ ㄐㄧ ㄑㄧˇ ㄨˇ', src: '《晉書．祖逖列傳》',
    quote: '中夜聞荒雞鳴，蹴琨覺曰：「此非惡聲也。」因起舞',
    facts: ['典出《晉書．祖逖列傳》：祖逖和劉琨一起擔任司州主簿，半夜聽到雞叫，踢醒劉琨一起起床舞劍｜教育部《成語典》典源', '祖逖十四五歲還沒有好好讀書，後來才博覽群書｜《晉書．祖逖列傳》', '祖逖後來帶兵平定動亂，收復許多失土｜教育部《成語典》典故說明', '「聞雞起舞」比喻把握時機，及時奮起行動｜教育部《成語典》釋義'],
    story: [
      '晉朝的時候，有一個年輕人叫祖逖。他小時候個性豪爽，不愛讀書，到了十四五歲還沒有好好念過書，哥哥們都替他擔心。不過他很講義氣，常常把家裡的米和布送給窮苦的人，鄉親們都很敬重他。',
      '後來，祖逖自己明白了讀書的重要，開始發憤讀了很多書，懂得古今的大事。見過他的人都說，這個年輕人將來一定能替國家做大事。',
      '那時候國家不太平，常常有戰亂。祖逖和好朋友劉琨一起在司州做官，兩個人都想為國家出一份力。他們感情好得不得了，晚上睡在同一張床上，常常聊天下大事聊到很晚。',
      '有一天半夜，天還黑漆漆的，遠遠傳來一陣雞叫聲。半夜的雞叫，有人覺得不吉利，祖逖卻一腳把劉琨踢醒，說：「這不是壞聲音！這是在提醒我們別再睡了！」',
      '兩個人馬上爬起來，走到院子裡拔劍練武。夜裡的冷風吹在臉上，他們一點也不在乎。從那天起，他們常常一聽到雞叫就起床練劍，把身體和武藝都練得更好。',
      '後來，祖逖果然成為一位將軍，帶兵收復了許多失去的土地，實現了為國家出力的願望。',
      '「聞雞起舞」就是從這個故事來的。這裡的「舞」不是跳舞，而是舞劍、練武。這個成語比喻把握時間，及時奮發、積極行動。'
    ],
    mean: '一聽到雞叫，就起床舞劍練武。比喻把握時機，及時奮發、積極行動。',
    usage: ['用來稱讚人勤奮積極、把握時間努力（褒義）。', '「舞」是舞劍練武，不是跳舞；只是很早起床，卻沒有拿時間來努力，不算聞雞起舞。'],
    misuse: [],
    eg: ['為了準備游泳比賽，表哥每天清晨五點就到泳池練習，真有聞雞起舞的精神。', '月考前一個月，哥哥就聞雞起舞，每天早起背英文單字。'],
    syn: ['奮發圖強'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '祖逖半夜聽到什麼聲音，就把劉琨叫醒？', opts: ['遠遠傳來的雞叫聲', '敲鑼打鼓的聲音', '外面颳大風的聲音', '劉琨打呼的聲音'], a: 0, why: '第四段：半夜「遠遠傳來一陣雞叫聲」，祖逖就把劉琨踢醒。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '祖逖從小就很愛讀書，十歲就讀完了很多書。', a: false, why: '第一段：他小時候不愛讀書，「到了十四五歲還沒有好好念過書」，後來才發憤讀書。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '祖逖說「這不是壞聲音」，他的意思是什麼？', opts: ['雞叫是在提醒他們該起來努力', '半夜雞叫的聲音其實非常好聽', '天已經亮了，可以出門去玩', '雞肚子餓了，要趕快起來餵牠吃'], a: 0, why: '他接著說「這是在提醒我們別再睡了」，然後就起床練劍，可見他把雞叫當成努力的提醒。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '從整個故事看來，祖逖後來能收復失土，最主要的原因是什麼？', opts: ['立下志向，又把握時間努力', '他家裡有很多米和布可以送人', '他和劉琨睡在同一張床上', '他小時候的個性非常調皮'], a: 0, why: '把第二、三、五、六段連起來：他想為國家出力，又發憤讀書、半夜起來練劍，才有後來的成就。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '祖逖小時候不愛讀書，長大後卻成為有學問、有本事的人。你覺得一個人「開始努力」會不會太晚？請用故事說明你的想法。',
        ref: '我覺得不會太晚。祖逖十四五歲還沒好好讀書，可是他想通以後就發憤讀書、每天練劍，後來還是成了將軍。重要的是想清楚自己要做什麼，然後真的去做，而且不要停。',
        rubric: ['清楚說出自己的看法', '用故事內容當證據（十四五歲才開始讀書、後來成為將軍）', '說出努力要注意的地方（例如立定目標、持續去做）'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「聞雞起舞」的「舞」是指什麼？', opts: ['舞劍、練武', '跳舞', '揮手打招呼', '跳繩運動'], a: 0, why: '祖逖和劉琨聽到雞叫是起來「拔劍練武」，「舞」是舞劍，不是跳舞。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小琪報名了全市的作文比賽，離比賽還有三個月。她跟自己約定，每天早上提早半小時起床，先讀一篇好文章，再寫一段一百字的短文。不管是下雨天還是放假，她都準時坐在書桌前。媽媽說：「妳這麼早就開始準備，一點時間也沒浪費。」', q: '小琪準備比賽的方式，最適合用哪個成語形容？', opts: ['聞雞起舞', '守株待兔', '朝三暮四', '掩耳盜鈴'], a: 0, why: '小琪把握時間、早早開始努力，就是聞雞起舞。守株待兔是只等好運，朝三暮四是反覆不定，掩耳盜鈴是自己騙自己。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈聯絡簿〉弟弟最近每天早上五點就起床，可是起床以後都躺在沙發上看卡通，看到要出門了才去刷牙。他說自己是聞雞起舞。', q: '弟弟說自己「聞雞起舞」，用得恰當。', a: false, why: '聞雞起舞是早起把握時間努力。弟弟雖然早起，卻是在看卡通，沒有奮發做事，不能這樣說。' },
      { id: 'p4', k: 'fill', d: 2, type: 'mc', q: '想在運動會跑出好成績，就要＿＿＿＿，從現在開始每天早上練跑。', opts: ['聞雞起舞', '掩耳盜鈴', '狐假虎威', '井底之蛙'], a: 0, why: '把握時間、及早開始練習，用聞雞起舞。其他三個都是負面意思，放進句子不通。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '祖逖把半夜的雞叫聲當成「提醒自己該努力」的訊號。你想為自己設一個什麼樣的「雞叫聲」，提醒自己把握時間？請說說你要用它來做哪件事。',
        ref: '我想把放學回家聽到的「門鈴聲」當作我的雞叫聲。只要一進家門，我就先寫半小時作業，寫完才能看電視。這樣就不會一直拖到晚上才寫，還能早點睡覺。',
        rubric: ['說出一個具體的提醒訊號', '說出要用它把握時間做的事', '說明這樣做有什麼好處'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 1, type: 'tf', q: '「為了在畢業典禮上表演，他們每天清晨提早到學校排練舞台劇，可說是聞雞起舞。」這句話的「聞雞起舞」用得恰當。', a: true, why: '每天清晨提早到校排練，是把握時間努力，用得恰當。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '阿哲的志願是當消防員。他知道消防員需要很好的體力，所以從五年級開始，每天天一亮就到河堤跑兩公里，回家再做二十下伏地挺身。同學問他：「離長大還很久，幹麼現在就這麼辛苦？」阿哲說：「越早開始，身體就越好，到時候才不會來不及。」', q: '阿哲每天早起鍛鍊的做法，像哪一個成語？', opts: ['聞雞起舞', '杯弓蛇影', '狐假虎威', '朝三暮四'], a: 0, why: '阿哲為了目標，天一亮就起來鍛鍊，把握時間奮發，就是聞雞起舞。' }
    ]
  },
  {
    id: 'cy025', lv: 1, word: '夜郎自大', zhuyin: 'ㄧㄝˋ ㄌㄤˊ ㄗˋ ㄉㄚˋ', src: '《史記．西南夷列傳》',
    quote: '滇王與漢使者言曰：「漢孰與我大？」及夜郎侯亦然',
    facts: ['典出《史記．西南夷列傳》：西漢時，西南邊境的滇王和夜郎侯都問漢朝使者「漢朝和我國哪一個大」｜教育部《成語典》典源、典故說明', '滇和夜郎因為道路不通，各自以為是一州之主，不知道漢朝有多大｜《史記．西南夷列傳》', '這兩個小國的面積，大約只和漢朝的一個郡差不多｜教育部《成語典》典故說明', '「郎」讀ㄌㄤˊ，不可寫作「朗」｜教育部《成語典》辨識'],
    story: [
      '兩千多年前的漢朝，是一個土地廣大、人口眾多的國家。在漢朝的西南邊，隔著重重高山和深深的山谷，有好幾個小國家，其中兩個叫做「滇」和「夜郎」。',
      '這些小國家四周都是山，路很難走，跟外面幾乎沒有來往。國王們從小到大，只看過自己國內的山和田，從來沒有走出去過。他們都以為，自己統治的就是天底下最大的國家。',
      '有一年，漢朝的皇帝派了使者，翻山越嶺來到西南方。使者先到了滇國。滇王見到他，很好奇的問：「你們漢朝跟我的國家比起來，哪一個比較大呀？」使者聽了，一時不知道該怎麼回答才好。',
      '後來使者又到了夜郎。沒想到，夜郎的國王（史書叫他「夜郎侯」）也問了一模一樣的問題：「漢朝和我們夜郎，誰比較大？」',
      '其實，夜郎和滇的土地，大概只跟漢朝的一個郡差不多大。可是因為道路不通，他們從來沒有看過外面的世界，才會以為自己最大。',
      '這段故事被司馬遷寫進了《史記》。有趣的是，最先問這個問題的其實是滇王，後來大家卻只記住了夜郎。',
      '「夜郎自大」這個成語就這樣流傳了下來，用來比喻一個人見識短淺，卻狂妄自大，以為自己很了不起。'
    ],
    mean: '夜郎國王不知道漢朝有多大，以為自己的國家最大。比喻人見識短淺，卻狂妄自大。',
    usage: ['用來批評見識不多、卻自以為了不起的人（貶義）。', '「井底之蛙」重在見識少；「夜郎自大」除了見識少，還多了驕傲自大。', '「夜郎自大」是因為見識狹隘而自以為大；「妄自尊大」是胡亂的自高自大，不一定跟見識有關。'],
    misuse: [],
    eg: ['他只在社區比賽贏過一次，就說全國沒有人下棋比他厲害，實在太夜郎自大了。', '參觀過別的學校的科學展覽，我們才知道自己不能夜郎自大，還要繼續努力。'],
    syn: ['妄自尊大', '自高自大'], ant: ['妄自菲薄', '虛懷若谷'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '滇王問了漢朝使者什麼問題？', opts: ['漢朝和滇國哪一個比較大', '漢朝的皇帝叫什麼名字', '到漢朝的路好不好走', '漢朝有沒有很高的山'], a: 0, why: '第三段：滇王問「你們漢朝跟我的國家比起來，哪一個比較大呀？」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '夜郎的國王也問了使者同樣的問題。', a: true, why: '第四段：「夜郎的國王也問了一模一樣的問題。」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '滇王和夜郎侯為什麼都以為自己的國家最大？', opts: ['道路不通，沒看過外面的世界', '他們曾經打敗過漢朝的軍隊', '漢朝的使者是這樣告訴他們的', '他們國家的人口比漢朝還多'], a: 0, why: '第二段和第五段：四周都是山、道路不通，「從來沒有看過外面的世界，才會以為自己最大」。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '把故事前後連起來看，「夜郎自大」的「自大」是怎麼來的？', opts: ['不知道外面多大，就以為自己最大', '國家真的很大，所以國王很驕傲', '國王長得很高大，大家都怕他', '國王喜歡聽別人說他很偉大'], a: 0, why: '夜郎其實只有漢朝一個郡那麼大（第五段），因為沒見過外面，才以為自己最大，這就是「自大」的由來。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '滇王和夜郎的國王會問「誰比較大」，你覺得是因為他們很壞，還是有別的原因？一個人要怎麼做，才能避免像他們一樣？請用故事說明。',
        ref: '我覺得不是因為他們壞，而是因為四周都是山、道路不通，他們從來沒看過外面。要避免像他們一樣，就要多出去看看、多聽別人的經驗，知道外面還有更大更厲害的世界，就不會隨便以為自己最了不起。',
        rubric: ['說出他們這樣問的原因（道路不通、沒見過外面）', '提出避免夜郎自大的具體做法', '做法和故事內容連得起來'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「夜郎自大」的「夜郎」指的是什麼？', opts: ['漢朝西南邊的一個小國', '在夜晚巡邏的一位士兵', '一位很驕傲的年輕人', '晚上才會出現的野狼'], a: 0, why: '夜郎是漢代西南邊境的一個小國。「郎」不是「狼」，也不是年輕人。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '阿豪在班上打桌球從來沒輸過，就跟大家說：「我是全國最強的，什麼比賽都不用練習。」老師推薦他參加縣賽，他第一場就遇到一個三年級的小選手，被打得一分都拿不到。阿豪這才知道，外面比他厲害的人多得是。', q: '比賽前阿豪說的話，最適合用哪個成語形容？', opts: ['夜郎自大', '驚弓之鳥', '聞雞起舞', '愚公移山'], a: 0, why: '阿豪只在班上沒輸過，就說自己全國最強，是見識短又驕傲，就是夜郎自大。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈新聞短評〉某少棒隊拿下全國冠軍後，教練對球員說：「我們只是在國內贏了，到國際賽還有很多要學的，絕對不能夜郎自大。」', q: '教練用「夜郎自大」提醒球員，恰當嗎？', opts: ['恰當，提醒大家別以為自己天下第一', '不恰當，因為他們已經拿到全國冠軍', '不恰當，夜郎自大只能用在國王身上', '恰當，因為球隊常常在晚上練球'], a: 0, why: '教練是提醒球員：國內第一不代表最厲害，不要像夜郎一樣以為自己最大，用得恰當。成語是比喻，不是只能用在國王。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '這些成語跟「夜郎自大」是什麼關係？配起來。', pairs: [['妄自尊大', '意思相近'], ['虛懷若谷', '意思相反'], ['聞雞起舞', '意思無關']], why: '妄自尊大是自高自大，跟夜郎自大相近；虛懷若谷是心胸像山谷一樣能容納、非常謙虛，意思相反；聞雞起舞是及時努力，跟這件事無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '你曾經有過「以為自己很厲害，後來才發現別人更厲害」的經驗嗎？那次經驗讓你學到什麼？下次你會怎麼做？',
        ref: '我以前覺得自己畫畫是全班最好的，後來參加美術社，看到學姊畫的水彩，才發現自己還差很多。我學到要多看別人的作品。下次我會先問學姊她是怎麼練習的，而不是只想著自己最厲害。',
        rubric: ['說出一個具體的經驗', '說出從經驗中學到的事', '提出下次具體的做法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '才學了一個月的英文，他就說自己可以當翻譯了，真是＿＿＿＿。', opts: ['夜郎自大', '聞雞起舞', '愚公移山', '驚弓之鳥'], a: 0, why: '才學一個月就以為自己很厲害，是見識短又自大，用夜郎自大。聞雞起舞、愚公移山是努力，驚弓之鳥是受驚害怕，都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '姊姊：「我這次科展得了第一名，可是看到全國賽的作品，才知道還有好多東西要學。」\n弟弟：「姊姊真是夜郎自大。」', q: '弟弟用「夜郎自大」形容姊姊，用得恰當。', a: false, why: '姊姊得了第一名還知道要繼續學，是謙虛，剛好和夜郎自大相反。' }
    ]
  },
  // ==================== L2 歷史故事 ====================
  {
    id: 'cy029', lv: 2, word: '一鳴驚人', zhuyin: 'ㄧ ㄇㄧㄥˊ ㄐㄧㄥ ㄖㄣˊ', src: '《韓非子．喻老》',
    quote: '雖無飛，飛必沖天；雖無鳴，鳴必驚人',
    facts: ['典出《韓非子．喻老》：楚莊王即位三年沒有發布政令，右司馬用「三年不飛不鳴的鳥」來暗示他｜教育部《成語典》典源', '楚莊王回答這隻鳥「雖無飛，飛必沖天；雖無鳴，鳴必驚人」，半年後親自處理政事，把楚國治理得很好｜《韓非子．喻老》', '楚莊王後來成為春秋五霸之一｜教育部《成語典》典故說明', '「一」本音ㄧ，在這個成語裡口語常變調唸ㄧˋ｜教育部《成語典》注音'],
    story: [
      '春秋時代，楚國的楚莊王當上國君已經三年了。奇怪的是，這三年來，他從來沒有發布過一道命令，也沒有處理什麼國家大事。大臣們看在眼裡，心裡都很著急。',
      '有一天，大臣右司馬陪在楚莊王身邊。他不好直接批評國君，就出了一個謎語：「大王，有一隻鳥停在南方的小山上，三年來不拍翅膀、不飛也不叫，安安靜靜的一點聲音也沒有。請問這是什麼鳥呢？」',
      '楚莊王一聽，就知道右司馬在說自己。他笑了笑，回答：「這隻鳥三年不拍翅膀，是在讓羽毛長得更豐滿；不飛也不叫，是在仔細觀察百姓的生活。牠雖然還沒飛，一飛就會衝上天空；雖然還沒叫，一叫就會讓人大吃一驚。你放心吧，我明白你的意思了。」',
      '過了半年，楚莊王開始親自處理國事。他廢除了十項不好的規定，推行了九項新的做法；處罰了五個做壞事的大臣，又提拔了六位有才能的讀書人。楚國很快就變得井井有條。',
      '後來，楚莊王帶兵在徐州打敗了齊國，自己也成為春秋時代有名的霸主之一。',
      '原來，那三年楚莊王並不是什麼都不做，而是在默默觀察、準備。韓非把這個故事寫進書裡，說明做大事的人，常常要先沉得住氣。',
      '「一鳴驚人」就是從「雖然還沒叫，一叫就會讓人大吃一驚」這句話來的，比喻平時默默無聞，後來卻突然有驚人的表現。'
    ],
    mean: '一叫就讓人大吃一驚。比喻平時默默無聞，後來卻突然有驚人的表現。',
    usage: ['用在「平常不起眼，後來突然表現得非常好」的時候（褒義）。', '如果一個人一直都很出色，再表現好也不算「一鳴驚人」，因為大家早就知道他很厲害。', '不是說聲音很大、把人嚇一跳。'],
    misuse: [],
    eg: ['平常很安靜的小芸，在才藝表演上唱了一首歌，一鳴驚人，全場都拍手叫好。', '這位作家默默寫了十年，第一本小說一出版就一鳴驚人，很快就賣光了。'],
    syn: [], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '右司馬說的那隻鳥有什麼特別的地方？', opts: ['三年不拍翅膀，不飛也不叫', '羽毛五顏六色，非常漂亮', '會說人話，還會出謎語', '每天一早就在宮殿外叫'], a: 0, why: '第二段：那隻鳥「三年來不拍翅膀、不飛也不叫」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '楚莊王後來帶兵打敗了齊國。', a: true, why: '第五段：「楚莊王帶兵在徐州打敗了齊國。」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '右司馬為什麼要出謎語，而不直接跟楚莊王說？', opts: ['不好直接批評國君，就用比喻', '想考考楚莊王聰不聰明', '自己也不知道那是什麼鳥', '楚國規定只能用謎語說話'], a: 0, why: '第二段：右司馬「不好直接批評國君，就出了一個謎語」。用鳥來比喻國君，說起來比較委婉。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '楚莊王說那隻鳥「不飛也不叫，是在仔細觀察」，其實是在說自己什麼？', opts: ['那三年他在默默觀察、準備', '那三年他生病不能出門', '那三年他忙著養一隻鳥', '那三年他都在學唱歌'], a: 0, why: '把第三段和第六段連起來：楚莊王是用鳥說自己，「那三年楚莊王並不是什麼都不做，而是在默默觀察、準備」。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '楚莊王三年不做事，其實是在觀察。你覺得這種「先安靜觀察，再一次行動」的做法好不好？在什麼情況下比較適合？請說明理由。',
        ref: '我覺得在不熟悉的地方，先觀察是好方法。像楚莊王剛當國君，先看清楚哪些規定不好、哪些人有才能，後來一動手就做對了。不過如果事情很緊急，例如有人受傷，就不能一直觀察，要馬上行動。',
        rubric: ['說出自己的看法', '用故事內容當理由（觀察三年後一次改革成功）', '說出適合或不適合的情況'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「一鳴驚人」的意思是什麼？', opts: ['平常不起眼，突然有驚人表現', '說話聲音很大，把人嚇一跳', '一大早就起床，叫醒全家人', '一隻鳥的叫聲非常好聽'], a: 0, why: '一鳴驚人比喻平時默默無聞，後來突然有驚人的表現。不是說聲音大。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '阿凱平時在班上很少說話，作業也普普通通，有些同學甚至記不得他的名字。這學期學校舉辦朗讀比賽，阿凱默默報了名，每天放學在家對著鏡子練習。比賽那天，他用響亮又有感情的聲音朗讀，拿下了全校第一名，大家都驚訝得張大嘴巴。', q: '阿凱在朗讀比賽的表現，最適合用哪個成語形容？', opts: ['一鳴驚人', '驚弓之鳥', '夜郎自大', '狐假虎威'], a: 0, why: '阿凱平常不起眼，比賽時卻突然拿下第一名，讓大家很驚訝，就是一鳴驚人。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈新聞短評〉這位網球選手連續五年都是世界排名第一，今年又拿下了冠軍。主播說：「她今年真是一鳴驚人！」', q: '主播用「一鳴驚人」形容這位選手，用得恰當。', a: false, why: '她一直都是世界第一，大家早就知道她很厲害，不是「平常默默無聞、突然表現驚人」，不能用一鳴驚人。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「那隻公雞清晨突然大叫一聲，把全家人都嚇醒了，真是一鳴驚人。」這句話的「一鳴驚人」用得恰當。', a: false, why: '一鳴驚人是比喻平時不起眼的人突然有驚人的表現，不是說叫聲很大、把人嚇醒。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '楚莊王在「一鳴」之前，默默準備了很久。你有沒有一件想讓大家刮目相看的事？你打算怎麼默默準備？',
        ref: '我想在明年的跳繩比賽拿到名次。我打算每天放學跳十分鐘，先練好二迴旋，再練速度，每個星期記錄一次自己一分鐘能跳幾下。不用一直跟別人說，等比賽那天再讓大家看到我的進步。',
        rubric: ['說出一件想做好的具體事情', '提出默默準備的具體方法', '說明怎麼確認自己有在進步'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '這支默默無名的鄉下小學球隊，第一次參加全國比賽就拿下冠軍，真是＿＿＿＿。', opts: ['一鳴驚人', '完璧歸趙', '畫蛇添足', '驚弓之鳥'], a: 0, why: '默默無名、第一次參賽就奪冠，是一鳴驚人。完璧歸趙是物歸原主，畫蛇添足是多此一舉，驚弓之鳥是受驚害怕。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '社區的里民大會上，平常總是坐在角落的王阿姨很少發言。這次討論公園要怎麼改建，她拿出自己畫好的設計圖，連哪裡種樹、哪裡放溜滑梯、下雨時水要往哪裡流都想好了。大家看完都說好，里長當場決定照她的設計去做。', q: '王阿姨在這次大會上的表現，像哪一個成語？', opts: ['一鳴驚人', '夜郎自大', '老馬識途', '掩耳盜鈴'], a: 0, why: '王阿姨平常很少發言，這次卻拿出讓大家驚豔的設計，就是一鳴驚人。' }
    ]
  },
  {
    id: 'cy033', lv: 2, word: '畫龍點睛', zhuyin: 'ㄏㄨㄚˋ ㄌㄨㄥˊ ㄉㄧㄢˇ ㄐㄧㄥ', src: '晉．王嘉《拾遺記．卷四》',
    quote: '又畫為龍鳳，騫翥若飛，皆不可點睛',
    facts: ['典出晉．王嘉《拾遺記．卷四》：秦始皇元年，騫霄國獻上善於雕刻、繪畫的工匠「裔」，他畫的龍鳳都不點睛，說點了就會飛走｜教育部《成語典》典源', '秦始皇叫人用漆替兩隻玉虎各點一隻眼睛，十天後玉虎不見了；第二年西方獻來兩隻各缺一眼的白虎，胸前果然是元年刻的玉虎｜《拾遺記．卷四》', '唐．張彥遠《歷代名畫記》記載張僧繇畫龍點睛、龍乘雲飛去，是另一個常見的版本｜教育部《成語典》參考資料、典故說明', '「睛」讀ㄐㄧㄥ，是眼睛，不可寫作「晴」｜教育部《成語典》辨識'],
    story: [
      '兩千多年前，秦始皇當上國君的第一年，一個叫騫霄國的小國家，送來了一位手藝非常好的工匠，名字叫做「裔」。',
      '這位工匠什麼都會。他把顏料含在嘴裡往地上一噴，地上就出現各種奇形怪狀的動物；他用玉石雕刻百獸，連毛髮都像真的一樣，還在每隻動物的胸前刻上日期；他用手指在地上畫線，線又長又直，好像拉過繩子一樣。',
      '最神奇的是，他畫的龍和鳳，翅膀張開，好像正要飛起來。可是，他畫的龍鳳都不點上眼睛。大家問他為什麼，他說：「如果點上眼睛，牠們就會飛走了。」',
      '秦始皇不太相信：「畫出來、刻出來的東西，怎麼可能會飛走？」他就叫人用黑漆，替兩隻玉雕的老虎各點上一隻眼睛。',
      '沒想到，才過了十天，那兩隻玉老虎就不見了。後來，住在山裡的人說：「我們看見兩隻白老虎，各只有一隻眼睛，一前一後的走著，毛色跟一般的老虎很不一樣。」',
      '第二年，西方的國家獻給秦始皇兩隻白老虎，每隻都只有一隻眼睛。秦始皇仔細一看，牠們的胸前還留著刻字，正是元年刻上的日期，原來就是那兩隻玉老虎！',
      '後來，唐朝的書裡也記了一個很像的故事：畫家張僧繇在寺廟的牆上畫龍，替兩條龍點上眼睛，那兩條龍就乘著雲飛上了天。',
      '「畫龍點睛」就從這些故事而來。點上眼睛，畫就活了。這個成語比喻畫畫、寫文章時，在最重要的地方加上一筆，讓整個作品更生動；也比喻做事抓住重點，讓事情更圓滿。'
    ],
    mean: '畫好龍以後點上眼睛，龍就活了飛走。比喻畫畫、寫文章時，在最重要的地方加上關鍵的一筆，讓整個作品更生動傳神；也比喻做事抓住重點，讓事情更圓滿。',
    usage: ['用在「加上一點點，就讓整體變得更好、更有精神」的時候（褒義）。', '如果加上去的東西是多餘的，反而讓作品變差，要用「畫蛇添足」。', '「睛」是眼睛，不要寫成晴天的「晴」。'],
    misuse: ['「這篇作文已經很完整了，他又在最後加了三段跟題目無關的話，真是畫龍點睛。」✗　加了以後變差，應該說「畫蛇添足」。'],
    eg: ['作文最後一句「原來最好的禮物，是陪伴」，真是畫龍點睛，讓整篇文章更感人。', '佈置教室時，阿美在黑板上方掛了一串小燈，畫龍點睛，整間教室都亮了起來。'],
    syn: [], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '工匠為什麼不替他畫的龍鳳點上眼睛？', opts: ['他說點了眼睛，龍鳳就會飛走', '他找不到黑色的顏料可以用', '秦始皇不准他替龍鳳點眼睛', '他忘了龍和鳳也有眼睛'], a: 0, why: '第三段：工匠說「如果點上眼睛，牠們就會飛走了」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '秦始皇叫人替兩隻玉老虎各點上一隻眼睛。', a: true, why: '第四段：秦始皇「叫人用黑漆，替兩隻玉雕的老虎各點上一隻眼睛」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '第二年獻來的白老虎「每隻都只有一隻眼睛」，作者想讓讀者想到什麼？', opts: ['牠們就是那兩隻點了眼的玉虎', '牠們和別的老虎打架受了傷', '西方國家的老虎都只有一眼', '工匠又雕了兩隻新的老虎'], a: 0, why: '玉老虎各只點了一隻眼睛（第四段），白老虎也各只有一隻眼睛，胸前還有元年的刻字（第六段），表示牠們就是那兩隻玉老虎。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '工匠裔和畫家張僧繇的故事，有什麼共同點？', opts: ['點上眼睛，畫裡的動物就活了', '兩個故事都發生在秦朝', '兩位畫家都是秦始皇請來的', '他們畫的都是老虎和獅子'], a: 0, why: '第三到六段的玉虎點了眼睛就跑走，第七段的龍點了眼睛就飛上天，都是「點睛就活了」。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '故事裡「點上眼睛，畫就活了」。你覺得為什麼「眼睛」這麼重要？想一想，一篇作文或一幅畫裡的「眼睛」可能是什麼？請舉例說明。',
        ref: '眼睛能看出一個人的心情，畫上眼睛，動物就好像有了精神。作文的「眼睛」可能是最能表達心情的那一句話，像寫「我的阿嬤」，最後寫一句「她的手很粗，卻是全世界最溫暖的手」，整篇文章就有了感情。',
        rubric: ['說出眼睛重要的原因', '說出作文或畫裡的「眼睛」可能是什麼', '舉出具體的例子'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「畫龍點睛」的「睛」是什麼意思？', opts: ['眼睛', '晴天', '精神', '睡覺'], a: 0, why: '「睛」是眼睛，「點睛」就是點上眼睛。晴天的「晴」是日字旁。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '五年三班在佈置校慶的班級攤位。大家已經掛好海報、擺好桌椅，可是整個攤位看起來還是有點普通。小雯想了想，在攤位正中間放了一塊寫著「三班小食堂」的木頭招牌，旁邊再掛上幾盞小燈籠。一放上去，攤位立刻有了特色，路過的人都停下來拍照。', q: '小雯加上招牌和燈籠，最適合用哪個成語形容？', opts: ['畫龍點睛', '畫蛇添足', '掩耳盜鈴', '完璧歸趙'], a: 0, why: '只加了招牌和燈籠，攤位就變得更有特色，是畫龍點睛。畫蛇添足是加了反而變差。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈美勞課評語〉小翔的風景畫原本已經很好看了，可是他又在天空塗滿黑色的雲，在草地上畫了十幾隻顏色不同的動物，畫面變得亂七八糟。同學卻說：「你這幾筆真是畫龍點睛！」', q: '同學說的「畫龍點睛」用得恰當嗎？', opts: ['不恰當，畫變亂了，是畫蛇添足', '恰當，因為加了很多新東西', '恰當，因為畫了很多動物', '不恰當，因為畫裡沒有龍'], a: 0, why: '畫龍點睛是加上關鍵的一筆讓作品變好。小翔加了以後畫面變亂，應該說畫蛇添足。成語是比喻，不是畫裡要有龍。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「演講的最後，他用一句『謝謝每一位默默幫助我的人』作結尾，可說是畫龍點睛。」這句話的「畫龍點睛」用得恰當。', a: true, why: '最後一句讓整場演講更有感情，是關鍵的一筆，用得恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '寫作文、做海報或佈置房間時，你會怎麼找出那一個「點睛」的地方？請舉一個例子，說說你會加上什麼、為什麼。',
        ref: '做「節約用水」的海報時，我會先畫一個水龍頭，再在旁邊加一句大大的標語「關緊一點，地球少渴一點」。我覺得標語是海報的眼睛，大家一看就知道海報要說什麼。',
        rubric: ['舉出一個具體的作品', '說出要加上的「點睛」內容', '說明為什麼它能讓作品更好'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '這首歌前面都很平淡，最後一段加入了小朋友的合唱，＿＿＿＿，讓人聽了好感動。', opts: ['畫龍點睛', '驚弓之鳥', '狐假虎威', '掩耳盜鈴'], a: 0, why: '最後加入合唱，讓整首歌更感人，是畫龍點睛。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '姊姊：「我在畢業紀念冊的封面上，只加了一行全班的簽名，看起來就特別有意義。」\n妹妹：「這一行簽名真是畫龍點睛！」', q: '妹妹說的「畫龍點睛」用得恰當。', a: true, why: '只加了一行簽名，就讓封面更有意義，是關鍵的一筆，用得恰當。' }
    ]
  },
  {
    id: 'cy037', lv: 2, word: '完璧歸趙', zhuyin: 'ㄨㄢˊ ㄅㄧˋ ㄍㄨㄟ ㄓㄠˋ', src: '《史記．廉頗藺相如列傳》',
    quote: '城入趙而璧留秦；城不入，臣請完璧歸趙',
    facts: ['語本《史記．廉頗藺相如列傳》：秦王說要用十五座城換趙國的和氏璧，藺相如帶著璧出使秦國｜教育部《成語典》典源', '藺相如看出秦王不想給城，用「璧有瑕」把璧拿回來，靠著柱子說要把璧撞碎，再請秦王齋戒五天，趁機派隨從從小路把璧送回趙國｜教育部《成語典》典故說明', '「完璧歸趙」比喻物歸原主｜教育部《成語典》釋義'],
    story: [
      '戰國時代，趙國得到一塊非常珍貴的美玉，叫做「和氏璧」。秦國的國王聽說了，派人送信給趙王：「我願意用十五座城，換你的和氏璧。」',
      '趙王很煩惱：秦國又強又大，把璧送去，萬一秦王拿了璧卻不給城，怎麼辦？不送嘛，又怕秦國找藉口來攻打。這時候，有人推薦了藺相如。',
      '藺相如說：「秦國用城換璧，如果趙國不答應，是趙國理虧；如果趙國送了璧，秦國卻不給城，就是秦國理虧。我願意帶著璧去。秦國給城，璧就留下；不給城，我一定把璧完完整整的帶回趙國。」',
      '到了秦國，秦王拿到和氏璧，高興得不得了，傳給身邊的人看，大家都高喊萬歲，卻沒有人提換城的事。藺相如看出，秦王根本不打算給城。',
      '他走上前說：「這塊璧上有一個小斑點，請讓我指給大王看。」秦王把璧交給他。藺相如一拿到璧，馬上往後退，靠著柱子站好，氣得頭髮都豎了起來：「大王如果要逼我，我就把璧往柱子上撞碎！」秦王怕璧被撞壞，只好叫人拿出地圖，假裝指出要給趙國的十五座城。',
      '藺相如知道秦王在騙人，就說：「趙王送璧以前齋戒了五天，請大王也齋戒五天，再隆重的接受這塊璧。」秦王只好答應。',
      '趁著這五天，藺相如叫隨從換上平民的粗布衣服，把璧藏在懷裡，從小路偷偷帶回趙國。等秦王發現，已經來不及了。',
      '後來，「完璧歸趙」就用來比喻把東西完好的歸還原來的主人。'
    ],
    mean: '把和氏璧完完整整的帶回趙國。比喻把東西完好的歸還原來的主人。',
    usage: ['用在「借來或拿走的東西，完好無缺的還給主人」的時候。', '重點是「完好」而且「還給原主」。東西已經弄壞了才還，就不能說完璧歸趙。', '「璧」是玉器，下面是「玉」；不要寫成牆壁的「壁」。'],
    misuse: [],
    eg: ['向表哥借的漫畫，我看完包好書套，完璧歸趙，一頁都沒有折到。', '圖書館的書大家都要看，我們要好好愛惜，看完才能完璧歸趙。'],
    syn: ['物歸原主'], ant: ['據為己有'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '秦王說要用什麼換和氏璧？', opts: ['十五座城', '十五箱黃金', '十五匹好馬', '十五車白米'], a: 0, why: '第一段：秦王說「我願意用十五座城，換你的和氏璧」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '藺相如是靠著跟秦王打架，才把和氏璧搶回來的。', a: false, why: '第五段：藺相如是說璧上有斑點，讓秦王自己把璧交給他，並沒有打架。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '藺相如說「璧上有一個小斑點」，真正的目的是什麼？', opts: ['想辦法把璧拿回自己手上', '想請秦王把斑點磨乾淨', '想讓秦王少給幾座城', '想讓秦王覺得璧不值錢'], a: 0, why: '第五段：秦王一把璧交給他，他「馬上往後退」。可見說有斑點是為了把璧拿回來。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '藺相如請秦王「齋戒五天」，對他有什麼幫助？', opts: ['爭取時間，讓隨從把璧送回去', '讓秦王好好想想要給哪幾座城', '讓秦王和趙王變成好朋友', '讓自己能在秦國多玩幾天'], a: 0, why: '把第六段和第七段連起來：「趁著這五天」，隨從就從小路把璧帶回趙國。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '藺相如拿著璧靠在柱子旁，說要把璧撞碎。你覺得這個做法冒不冒險？如果是你，你會怎麼做？請說明理由。',
        ref: '我覺得很冒險，因為秦王可能會生氣，藺相如自己也會有危險。可是他算準了秦王很想要璧，不會讓璧被撞碎，所以才敢這樣做。如果是我，我也會先想辦法把璧拿回手上，再找機會偷偷送回去。',
        rubric: ['說出這個做法冒不冒險', '用故事內容說明（例如秦王怕璧被撞壞）', '說出自己會怎麼做，而且合理'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「完璧歸趙」的「璧」是什麼？', opts: ['圓形中間有孔的玉器', '房子四周圍起來的牆壁', '溪邊撿來的石頭', '磨得發亮、可以照臉的銅鏡'], a: 0, why: '「璧」是一種圓形、中間有孔的玉器，所以下面是「玉」。牆壁的「壁」下面是「土」。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '阿美要出國一個月，把心愛的小烏龜託給鄰居小真照顧。小真每天幫烏龜換水、餵飼料、曬太陽，還把牠每天吃了多少記在本子上。一個月後阿美回來，小真把活潑又健康的烏龜，連同整理好的照顧紀錄，一起交還給她。阿美開心得抱住小真。', q: '小真歸還烏龜的情形，最適合用哪個成語形容？', opts: ['完璧歸趙', '毛遂自薦', '一鳴驚人', '四面楚歌'], a: 0, why: '小真把託她照顧的烏龜好好的還給主人，就是完璧歸趙。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈日記〉今天我把向圖書館借的故事書還回去，可是書在書包裡被水壺弄溼了，好幾頁都皺皺的。我想，這也算是完璧歸趙吧。', q: '日記裡的「完璧歸趙」用得恰當嗎？', opts: ['不恰當，書已經弄溼，不算完好', '恰當，因為書最後有還給圖書館', '恰當，因為故事書的內容沒有少', '不恰當，因為圖書館不在趙國'], a: 0, why: '完璧歸趙要「完好」的歸還。書已經弄溼、皺掉，不能說完璧。成語是比喻，跟是不是趙國無關。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '哪一個成語的意思和「完璧歸趙」相反？', opts: ['據為己有', '物歸原主', '一字千金', '價值連城'], a: 0, why: '完璧歸趙是把東西還給主人；據為己有是把別人的東西占為自己的，意思相反。物歸原主意思相近。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '藺相如答應趙王「一定把璧完整帶回來」。你向別人借東西時，可以怎麼做，才能做到「完璧歸趙」？請列出至少兩個做法。',
        ref: '借東西的時候，我會先看清楚它原本的樣子，記住有沒有刮痕。用的時候小心放在安全的地方，不帶到容易弄髒的地方。用完以後擦乾淨，在約好的時間還給對方，還要說謝謝。',
        rubric: ['列出至少兩個具體做法', '做法能讓東西保持完好', '有提到按時歸還或尊重主人'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '這本相簿是奶奶最珍貴的回憶，你看完一定要＿＿＿＿，千萬不能弄丟或弄髒。', opts: ['完璧歸趙', '一鳴驚人', '畫蛇添足', '驚弓之鳥'], a: 0, why: '把相簿完好的還給奶奶，用完璧歸趙。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '校外教學前，班長向體育室借了十顆排球。活動結束時，有一顆球滾進了草叢。大家都說：「少一顆應該沒關係吧。」班長卻帶著兩個同學把草叢翻了一遍，終於找到那顆球，擦乾淨以後，十顆球一顆不少的送回體育室。', q: '班長歸還排球的做法，像哪一個成語？', opts: ['完璧歸趙', '夜郎自大', '狐假虎威', '朝三暮四'], a: 0, why: '班長把借來的球完好、不少一顆的還回去，就是完璧歸趙。' }
    ]
  },
  {
    id: 'cy040', lv: 2, word: '毛遂自薦', zhuyin: 'ㄇㄠˊ ㄙㄨㄟˋ ㄗˋ ㄐㄧㄢˋ', src: '《史記．平原君虞卿列傳》',
    quote: '夫賢士之處世也，譬若錐之處囊中，其末立見',
    facts: ['典出《史記．平原君虞卿列傳》：秦國包圍趙國都城邯鄲，平原君要挑二十位門客去楚國求救，只選到十九位，毛遂主動推薦自己｜教育部《成語典》典源', '平原君用「錐子放在布袋裡，尖端立刻露出來」比喻有才能的人｜《史記．平原君虞卿列傳》', '到了楚國，毛遂向楚王說明趙、楚聯合抗秦的利害，楚王答應出兵，平原君從此待毛遂為上賓｜教育部《成語典》典故說明', '「遂」讀ㄙㄨㄟˋ，不可寫作「逐」｜教育部《成語典》辨識'],
    story: [
      '戰國時代，秦國派大軍包圍了趙國的都城邯鄲，情況非常危急。趙王派平原君到楚國，請楚國出兵幫忙。',
      '平原君家裡住著好幾千位門客。他想從門客裡挑出二十個文武雙全的人，跟他一起去楚國。可是挑來挑去，只選出了十九個，還差一個。',
      '這時候，一個叫毛遂的門客走上前，說：「聽說您還少一個人，請讓我跟您一起去吧！」',
      '平原君看了看他：「先生在我這裡多久了？」毛遂說：「三年了。」平原君說：「真正有才能的人，就像放在布袋裡的錐子，尖尖的錐頭馬上就會露出來。你在我這裡三年，我從來沒聽人稱讚過你，可見你沒有什麼本事。你還是留下吧！」',
      '毛遂不慌不忙的回答：「我今天就是在請您把我放進布袋裡呀！如果您早一點讓我進到布袋，我早就整個冒出來了，哪裡只會露出一個尖頭呢？」平原君覺得他說得有道理，就帶他一起去了。',
      '到了楚國，平原君和楚王從早上談到中午，楚王還是不肯答應。毛遂握著劍走上台階，站到楚王面前，把趙楚兩國聯合起來對抗秦國的道理，一條一條說得清清楚楚。楚王終於被說動了，當場和趙國訂下盟約，答應出兵。',
      '這一趟，毛遂幫平原君完成了任務。平原君非常佩服他，從此把他當成貴賓看待。',
      '後來，「毛遂自薦」就用來比喻自告奮勇，主動推薦自己。'
    ],
    mean: '毛遂自己推薦自己，跟著平原君去楚國。比喻自告奮勇，主動推薦自己。',
    usage: ['用在「主動站出來，推薦自己去做某件事」的時候。', '「自薦」是推薦「自己」；推薦別人去做，不能說毛遂自薦。', '「毛遂自薦」側重覺得自己有能力而推薦自己；「自告奮勇」側重勇敢擔當、挺身而出。'],
    misuse: ['「我推薦小明當班長，因為他做事很負責，這就是毛遂自薦。」✗　推薦的是別人，不是自己。'],
    eg: ['班上要選人參加說故事比賽，小芸毛遂自薦，說她很會模仿各種角色的聲音。', '社區要找志工教小朋友摺紙，學過摺紙的表姊馬上毛遂自薦。'],
    syn: ['自告奮勇'], ant: ['裹足不前'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '平原君原本要挑幾位門客一起去楚國？', opts: ['二十位', '十九位', '三位', '一位'], a: 0, why: '第二段：他想挑出「二十個文武雙全的人」，可是只選出十九個。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '毛遂在平原君家已經待了三年。', a: true, why: '第四段：平原君問他多久了，毛遂說「三年了」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '平原君一開始為什麼覺得毛遂沒有本事？', opts: ['三年來沒聽人稱讚過他', '毛遂的年紀實在太大了', '毛遂從來沒有拿過劍', '毛遂說話的聲音太小'], a: 0, why: '第四段：平原君說「你在我這裡三年，我從來沒聽人稱讚過你」。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '毛遂說「請您把我放進布袋裡」，「放進布袋」是比喻什麼？', opts: ['給他一個表現才能的機會', '送給他一個新的布袋', '讓他躲起來不被秦國發現', '請他幫忙搬運行李'], a: 0, why: '平原君用「錐子在布袋裡會露出尖頭」比喻有才能的人會被看見（第四段）。毛遂說請把他放進布袋，就是請平原君給他表現的機會（第五段）。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '有人覺得毛遂很勇敢，也有人覺得自己推薦自己有點愛現。你的看法是什麼？主動爭取機會時，要注意什麼？請用故事說明。',
        ref: '我覺得毛遂很勇敢，因為如果他不說，平原君永遠不會知道他的本事。不過他不是只會說大話，到了楚國真的說服了楚王。所以主動爭取機會時，要先確定自己做得到，而且真的去做好，才不會變成愛現。',
        rubric: ['清楚說出自己的看法', '用故事內容當理由（例如毛遂真的說服了楚王）', '說出主動爭取機會時要注意的事'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「毛遂自薦」的「薦」是什麼意思？', opts: ['推薦', '拒絕', '原諒', '送禮'], a: 0, why: '「薦」是推薦，「自薦」就是推薦自己。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校要找一位同學在開學典禮上，用英文向外國來賓說歡迎詞。老師問誰願意，教室裡安靜了好久。這時，小安舉起手說：「我願意試試看！我暑假在英語營當過小主持人，而且我會把稿子背熟。」老師點點頭，把這個任務交給了他。', q: '小安的做法，最適合用哪個成語形容？', opts: ['毛遂自薦', '狐假虎威', '掩耳盜鈴', '四面楚歌'], a: 0, why: '大家都不敢舉手時，小安主動推薦自己，還說出自己的能力，就是毛遂自薦。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈班會紀錄〉討論誰來當這次校外教學的小隊長時，阿翔說：「我毛遂自薦，推薦小真當小隊長，因為她做事最細心。」', q: '阿翔說自己「毛遂自薦」，用得恰當。', a: false, why: '「自薦」是推薦自己。阿翔推薦的是小真，應該說「我推薦小真」。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '這些成語跟「毛遂自薦」是什麼關係？配起來。', pairs: [['自告奮勇', '意思相近'], ['裹足不前', '意思相反'], ['完璧歸趙', '意思無關']], why: '自告奮勇是主動要求承擔任務，跟毛遂自薦相近；裹足不前是停下腳步不敢向前，相反；完璧歸趙是物歸原主，跟這件事無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '毛遂抓住機會推薦自己。想一想，你有什麼專長可以替班級或家人做點事？如果要「毛遂自薦」，你會怎麼說，才能讓別人放心把事情交給你？',
        ref: '我很會整理東西。班上的圖書角很亂，我想跟老師說：「我可以負責整理圖書角，我在家都會把書按照種類排好。我每個星期五會檢查一次，如果有書不見，我會登記下來。」',
        rubric: ['說出自己的一項專長', '說出要替大家做的具體事情', '說法能讓人放心（例如說明做法或會怎麼負責）'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '社團要選一位同學設計社團的標誌，喜歡畫畫的小芳立刻＿＿＿＿，說她願意試試看。', opts: ['毛遂自薦', '完璧歸趙', '驚弓之鳥', '夜郎自大'], a: 0, why: '主動說自己願意試試看，是毛遂自薦。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'mc', ctx: '〈社區報〉颱風過後要清理公園，里長在群組問誰能幫忙。退休的木工陳伯伯毛遂自薦，說他可以修理被吹壞的長椅，第二天一早就帶著工具準時出現。', q: '社區報用「毛遂自薦」形容陳伯伯，恰當嗎？', opts: ['恰當，他主動推薦自己做擅長的事', '不恰當，因為陳伯伯已經退休了', '恰當，因為陳伯伯很會使用工具', '不恰當，毛遂自薦只能用在古代'], a: 0, why: '陳伯伯主動說自己能修長椅，是推薦自己去做擅長的事，用得恰當。' }
    ]
  },
  {
    id: 'cy043', lv: 2, word: '四面楚歌', zhuyin: 'ㄙˋ ㄇㄧㄢˋ ㄔㄨˇ ㄍㄜ', src: '《史記．項羽本紀》',
    quote: '夜聞漢軍四面皆楚歌，項王乃大驚',
    facts: ['典出《史記．項羽本紀》：項羽的軍隊在垓下被漢軍和諸侯的軍隊重重包圍，兵少糧盡｜教育部《成語典》典源', '夜裡聽到漢軍四面都唱楚歌，項羽大驚：「漢軍已經得到楚地了嗎？怎麼楚人這麼多！」｜《史記．項羽本紀》', '楚軍士兵聽到家鄉的歌謠，想起很久沒回去的故鄉｜教育部《成語典》典故說明', '《史記》原文只寫項羽夜裡聽到四面楚歌而大驚，沒有寫漢軍是故意唱歌來瓦解楚軍鬥志；那是後人的解讀｜《史記．項羽本紀》', '「四面楚歌」比喻四面受敵，孤立無援｜教育部《成語典》釋義'],
    story: [
      '秦朝滅亡以後，楚國的項羽和漢王劉邦爭奪天下，打了好幾年的仗。項羽力氣很大，打仗非常勇猛，一開始幾乎每一戰都贏。',
      '後來兩個人約定，以一條叫鴻溝的河為界，東邊歸項羽，西邊歸劉邦。可是項羽帶兵往東撤退時，劉邦卻聯合其他將領的軍隊追了上去。',
      '項羽的軍隊退到一個叫垓下的地方，被漢軍一層又一層的包圍。楚軍的士兵越來越少，糧食也快吃完了。',
      '一天晚上，四周靜悄悄的，忽然從漢軍的營地傳來歌聲。仔細一聽，唱的竟然都是楚地的歌謠！東邊是楚歌，西邊是楚歌，南邊、北邊，也都是楚歌。',
      '楚軍的士兵聽到家鄉的歌，想起很久沒回去的故鄉和家人。項羽聽了也大吃一驚：「難道漢軍已經把楚地都占領了？不然漢軍裡怎麼會有這麼多楚國人！」',
      '《史記》只記下項羽聽到歌聲時的驚訝，並沒有說這些歌是誰安排的。後來很多人猜想，這是漢軍故意唱的，要讓楚軍想家、失去打仗的鬥志。這是後人的解讀，不是《史記》的原文。',
      '那天夜裡，項羽睡不著，坐在帳篷裡喝酒。陪在身邊的是他最喜歡的虞姬，帳外還有他最愛的駿馬「騅」。項羽唱起悲傷的歌：「我的力氣能拔起高山，氣勢壓倒天下，可是時機對我不利，連我的騅都不肯往前跑了……」虞姬跟著唱和，身邊的人都低著頭流淚。',
      '項羽覺得局勢已經沒有辦法挽回，當天夜裡就帶著士兵突圍而去。',
      '後來，「四面楚歌」就用來比喻四面都是敵人，孤立無援，陷入了困境。'
    ],
    mean: '四面八方都傳來楚國的歌謠。比喻四面受敵、孤立無援，陷入困境。',
    usage: ['用在「四周都是反對、為難自己的人，沒有人能幫忙」的困境。', '重點是「孤立無援」：只是對手很強或事情很難，身邊卻有很多人支持、幫忙，就不能說四面楚歌。', '只說前後兩邊同時受到攻擊，可以用「腹背受敵」。'],
    misuse: ['「拔河比賽遇到很強的對手，可是全班都在旁邊幫我們加油，真是四面楚歌！」✗　四面楚歌要「孤立無援」。大家都在支持你，只是對手強，不能這樣用。'],
    eg: ['他一個人反對大家的決定，又說不出理由，在班會上陷入四面楚歌的處境。', '這家小店被四周新開的大賣場包圍，生意越來越差，老闆說自己四面楚歌。'],
    syn: ['四面受敵', '腹背受敵'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '項羽的軍隊在垓下遇到什麼困難？', opts: ['被層層包圍，糧食快吃完', '突然下大雪，走不出山谷', '馬匹都生病了，不能再跑', '和漢軍約好了暫時休息'], a: 0, why: '第三段：項羽的軍隊「被漢軍一層又一層的包圍」，士兵越來越少，糧食也快吃完了。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '漢軍營地裡傳來的，是楚國家鄉的歌謠。', a: true, why: '第四段：「唱的竟然都是楚地的歌謠！」' },
      { id: 'r6', p: 2, d: 2, type: 'mc', q: '楚軍士兵聽到漢營傳來的楚歌，心裡最可能是什麼感覺？', opts: ['想念很久沒回去的故鄉和家人', '覺得漢軍的歌唱得太難聽了', '以為戰爭已經結束可以回家了', '很想跑過去跟著漢軍一起唱'], a: 0, why: '第五段：士兵聽到家鄉的歌，「想起很久沒回去的故鄉和家人」。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '項羽說「漢軍裡怎麼會有這麼多楚國人」，可以推想，四面楚歌讓他覺得怎麼樣？', opts: ['家鄉好像也被占了，沒人能幫他', '漢軍的歌唱得比楚軍還要好聽', '漢軍想要用唱歌和楚軍交朋友', '楚國人天生都很愛唱歌'], a: 0, why: '項羽以為楚地已經被占領，連家鄉都不再支持他，覺得自己被包圍、孤立無援（第五段），所以決定突圍（第八段）。' },
      { id: 'r7', p: 4, d: 3, type: 'open', q: '《史記》沒有說楚歌是誰安排的，後人卻常說是漢軍故意唱的。如果真是這樣，你覺得這一招為什麼可能有效？這個故事讓你對「心情」和「做事的力量」有什麼想法？',
        ref: '如果是故意的，這一招可能有效，因為楚軍已經被包圍、糧食又快吃完，聽到家鄉的歌就會想家，連項羽都以為楚地被占領了。我覺得心情會影響一個人的力量，心情低落的時候，再有力氣也使不出來。所以遇到困難時，要先照顧好自己的心情。',
        rubric: ['說出這一招可能有效的原因（被包圍、想家、以為家鄉被占）', '用到故事內容當證據，並分得出哪些是《史記》寫的、哪些是後人說的', '說出對「心情影響做事」的想法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「四面楚歌」比喻什麼樣的處境？', opts: ['四面受敵，孤立無援', '四周熱鬧，大家唱歌', '到處旅行，交到朋友', '回到家鄉，聽到老歌'], a: 0, why: '四面楚歌比喻四面都是敵人，沒有人能幫忙，不是到處都在唱歌。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '五年一班的班會上，阿哲提議把每節下課縮短五分鐘，好讓大家早點放學。他一說完，班長說會影響大家休息，風紀股長說會來不及上廁所，連平常最支持他的好朋友也搖頭反對。阿哲站在台上，看著四周反對的表情，一句話也說不出來。', q: '阿哲在班會上的處境，最適合用哪個成語形容？', opts: ['四面楚歌', '世外桃源', '雞鳴狗盜', '一鳴驚人'], a: 0, why: '阿哲的提議遭到所有人反對，連好朋友也不支持他，孤立無援，就是四面楚歌。' },
      { id: 'p6', k: 'use', d: 2, type: 'mc', ctx: '〈運動會日記〉今天拔河比賽，我們班遇到去年的冠軍隊。對方的同學又高又壯，可是全班都在旁邊大聲幫我們加油，老師也一直幫我們喊口令。我覺得我們真是四面楚歌！', q: '日記裡的「四面楚歌」用得恰當嗎？', opts: ['不恰當，大家都在支持他們，不是孤立無援', '恰當，因為對手又高又壯，他們真的很難打敗', '恰當，因為四周都有人在大聲喊叫', '不恰當，因為拔河比賽不是真的在打仗'], a: 0, why: '四面楚歌要「四面受敵、孤立無援」。日記裡全班和老師都在幫忙，只是對手很強，不能用四面楚歌。成語是比喻，跟是不是真的打仗無關。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「這支球隊連輸五場，球迷罵、記者批評，連贊助的廠商也說要退出，真是四面楚歌。」這句話的「四面楚歌」用得恰當。', a: true, why: '球隊被各方批評、連支持的人都要離開，孤立無援，用四面楚歌恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '如果班上有同學陷入「四面楚歌」，大家都反對他、不理他，你會怎麼做？請說說你的想法和做法。',
        ref: '我會先私下問他發生了什麼事，聽聽他的想法。如果他真的做錯了，我會陪他去跟大家道歉；如果他只是被誤會，我會幫他跟大家說明。被大家孤立的感覺很難受，至少要有一個人願意聽他說話。',
        rubric: ['提出具體的做法', '做法有考慮到那位同學的感受', '能分辨不同情況（做錯了或被誤會）會更好'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '老闆的新規定讓員工、客人和合作的廠商都不滿意，公司一下子陷入了＿＿＿＿的局面。', opts: ['四面楚歌', '完璧歸趙', '聞雞起舞', '畫龍點睛'], a: 0, why: '各方都不滿意，孤立無援，用四面楚歌。完璧歸趙、聞雞起舞、畫龍點睛都是正面意思，放進句子不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '小鎮上的老書店本來生意很好。後來附近開了兩間大型書店，網路書店又常常打折，房東還說明年要漲房租。老闆看著越來越少的客人，嘆氣說：「現在前後左右都是難題，沒有一個人能幫我，真不知道該怎麼辦。」', q: '老書店老闆的處境，像哪一個成語？', opts: ['四面楚歌', '世外桃源', '毛遂自薦', '老馬識途'], a: 0, why: '老書店被各方面的困難包圍，又沒有人能幫忙，就是四面楚歌。' }
    ]
  },
  {
    id: 'cy046', lv: 2, word: '世外桃源', zhuyin: 'ㄕˋ ㄨㄞˋ ㄊㄠˊ ㄩㄢˊ', src: '晉．陶潛〈桃花源記〉',
    quote: '自云先世避秦時亂，率妻子邑人來此絕境',
    facts: ['典出晉．陶潛〈桃花源記〉：東晉太元年間，武陵漁夫沿著溪水走，遇到桃花林，從山洞進入一個與世隔絕的村子｜教育部《成語典》典源', '村民的祖先為了躲避秦朝的戰亂來到這裡，不知道有漢朝，更不用說魏、晉｜〈桃花源記〉', '漁夫出來時沿路做記號，太守派人跟他去找，卻再也找不到路｜教育部《成語典》典故說明', '「源」讀ㄩㄢˊ，指水流的出處，不可寫作「園」｜教育部《成語典》辨識'],
    story: [
      '東晉的時候，武陵有一個以捕魚為生的漁夫。有一天，他划著小船沿著溪水往上走，划著划著，忘了自己走了多遠。',
      '忽然，溪的兩岸出現一大片桃花林，林子裡沒有別的樹，青草又香又嫩，粉紅的花瓣紛紛飄落。漁夫覺得很奇怪，就繼續往前划，想看看桃花林的盡頭是什麼。',
      '桃花林在溪水的源頭結束了，那裡有一座山，山腳有個小洞，洞裡好像透出一點光。漁夫下了船，從洞口走進去。洞一開始很窄，只容得下一個人；走了幾十步，眼前忽然變得又開闊又明亮。',
      '洞的另一邊是一個村子：土地平坦，房屋整齊，有肥沃的田地、美麗的池塘，還有桑樹和竹子。田間小路四通八達，到處聽得到雞叫狗吠，老人和小孩都悠閒快樂。',
      '村民看見漁夫，嚇了一大跳，熱情的請他到家裡吃飯。原來，他們的祖先為了躲避秦朝的戰亂，帶著家人來到這個與外界隔絕的地方，從此再也沒有出去過。他們不知道有漢朝，更不用說後來的魏和晉了。',
      '漁夫住了幾天，要回家時，村民對他說：「這裡的事，不用跟外面的人說喔。」',
      '漁夫出了洞，一路上做了記號。回到武陵後，他去報告太守。太守馬上派人跟他去找，可是沿著記號找來找去，卻再也找不到那條路了。',
      '這個故事出自陶淵明的〈桃花源記〉。後來，「世外桃源」就用來比喻風景優美、很少人去的地方，也比喻心中理想的世界。'
    ],
    mean: '與外界隔絕、開滿桃花的安樂地方。比喻風景優美而人跡罕至的地方，也比喻心中理想的世界。',
    usage: ['用來形容風景優美、安安靜靜，很少人去的地方。', '也可以比喻心中理想、沒有煩惱的世界。', '人山人海、熱鬧吵雜的地方，不能說是世外桃源。', '「源」是水的源頭，不要寫成「園」。'],
    misuse: [],
    eg: ['爺爺家在山裡，四周都是茶園和竹林，晚上只聽得到蟲叫，簡直是世外桃源。', '對愛看書的小芸來說，安靜的圖書館就是她的世外桃源。'],
    syn: ['人間仙境', '洞天福地'], ant: ['人間地獄'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '漁夫是怎麼走進那個村子的？', opts: ['從山腳的小洞走進去', '翻過一座很高的山', '坐小船一直划進去', '跟著一隻小狗走進去'], a: 0, why: '第三段：漁夫「下了船，從洞口走進去」，走了幾十步就到了村子。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '村子裡的人知道外面已經是晉朝了。', a: false, why: '第五段：「他們不知道有漢朝，更不用說後來的魏和晉了。」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '村民說「這裡的事，不用跟外面的人說」，他們心裡最可能怎麼想？', opts: ['希望村子保持安靜，不被打擾', '覺得漁夫說的話都是騙人的', '擔心漁夫會帶走村裡的雞', '覺得村子太小，不好意思說'], a: 0, why: '村民的祖先就是為了躲避戰亂才來這裡（第五段），他們過著安樂的日子，所以希望不要被外面的人打擾。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '太守派人去找，卻找不到路。這個結尾讓「桃花源」變得怎麼樣？', opts: ['更像一個難以找到的理想地方', '變成大家都去過的觀光景點', '證明漁夫說的全部是謊話', '說明武陵的路一直在修'], a: 0, why: '漁夫明明做了記號，卻再也找不到（第七段），讓桃花源像一個只存在心中、難以到達的理想地方，所以後來也用來比喻理想世界。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '如果你是那位漁夫，離開桃花源以後，你會不會把這個地方告訴太守？為什麼？',
        ref: '我不會告訴太守。村民對我很好，又請我不要說出去，如果我說了，很多人會跑去，村子就不再安靜了。我會把這段經驗放在心裡，回家後學村民的生活方式，跟鄰居好好相處。',
        rubric: ['清楚說出會或不會', '用故事內容當理由（例如村民的請求、想保持安靜）', '想到說或不說可能帶來的結果'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「世外桃源」的「源」是什麼意思？', opts: ['水流開始的地方', '種果樹的園子', '遙遠的國家', '很高的山峰'], a: 0, why: '桃花林在「溪水的源頭」結束，「源」是水流開始的地方，所以不能寫成「園」。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '暑假時，小宇跟家人到山裡露營。營地旁邊有一條清澈的小溪，四周都是綠油油的大樹，晚上抬頭就能看到滿天星星。那裡沒有網路，也聽不到車子的聲音，只有蟲鳴和水聲。小宇躺在帳篷外說：「我真想一直住在這裡。」', q: '小宇露營的地方，最適合用哪個成語形容？', opts: ['世外桃源', '四面楚歌', '門庭若市', '井底之蛙'], a: 0, why: '風景優美、安靜，很少人去，就是世外桃源。門庭若市是形容來的人很多、很熱鬧，剛好相反。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈遊記〉過年時我們去逛夜市，人擠人，走一步就要停三步，到處都是叫賣聲和音樂聲，真是一個世外桃源。', q: '遊記裡的「世外桃源」用得恰當嗎？', opts: ['不恰當，人擠人又吵，不是少人的地方', '恰當，因為夜市裡有很多好吃的東西', '恰當，因為過年時大家心情都很好', '不恰當，因為夜市裡沒有種桃花'], a: 0, why: '世外桃源是安靜、很少人去的地方。夜市人擠人又吵，剛好相反。成語是比喻，跟有沒有桃花無關。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '哪一個成語的意思和「世外桃源」最接近？', opts: ['人間仙境', '四面楚歌', '門庭若市', '雞鳴狗盜'], a: 0, why: '人間仙境是人間像仙境一樣美好的地方，和世外桃源相近。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '陶淵明寫了一個人人都悠閒快樂的桃花源。如果要讓你的教室或社區更像「桃花源」，你覺得可以改變哪一件事？請說說你的做法。',
        ref: '我覺得可以讓教室更安靜、更乾淨。我們可以在窗台種幾盆小植物，訂一個「午休不吵鬧」的約定，下課時大家一起把垃圾撿乾淨。這樣大家待在教室裡會更舒服，心情也會比較好。',
        rubric: ['說出一個想改變的地方', '提出具體做法', '說明這樣做為什麼能讓大家更快樂'] }
    ],
    xq: [
      { id: 'x1', k: 'judge', d: 1, type: 'tf', q: '「這座小島很少有遊客，海水清澈、沙灘潔白，就像一座世外桃源。」這句話的「世外桃源」用得恰當。', a: true, why: '小島風景優美又很少人去，用世外桃源恰當。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '阿嬤住在山上的一個小村子，村裡只有十幾戶人家。每天早上，雲霧慢慢飄過山谷，大家種菜、餵雞，傍晚就坐在門口聊天。村子裡沒有便利商店，也沒有紅綠燈，可是每個人看起來都悠悠閒閒、很快樂，表弟去了一次就捨不得回家。', q: '阿嬤住的村子，最適合用哪一個成語形容？', opts: ['世外桃源', '四面楚歌', '完璧歸趙', '毛遂自薦'], a: 0, why: '村子風景優美、人少安靜，大家生活悠閒快樂，就像世外桃源。' }
    ]
  },
  {
    id: 'cy049', lv: 2, word: '雞鳴狗盜', zhuyin: 'ㄐㄧ ㄇㄧㄥˊ ㄍㄡˇ ㄉㄠˋ', src: '《史記．孟嘗君列傳》',
    quote: '始孟嘗君列此二人於賓客，賓客盡羞之',
    facts: ['典出《史記．孟嘗君列傳》：秦昭王囚禁孟嘗君，門客「狗盜」偷出狐白裘送給昭王的寵姬求情，「雞鳴」學雞叫騙開函谷關｜教育部《成語典》典源、典故說明', '函谷關的規定是雞叫了才開門讓人出關｜《史記．孟嘗君列傳》', '其他門客原本覺得和這兩人同列很羞恥，這件事以後都服氣了｜《史記．孟嘗君列傳》', '「雞鳴狗盜」比喻有某種卑下技能的人，或指卑微的技能；也形容卑劣低下的人或事｜教育部《成語典》釋義'],
    story: [
      '戰國時代，齊國有一位貴族叫孟嘗君。他很喜歡結交各種有本領的人，家裡住了好幾千位門客。',
      '門客當中，有一個人很會學狗的樣子，在夜裡溜進別人家偷東西；還有一個人很會學雞叫。其他門客都覺得，跟這兩個人排在一起很丟臉。',
      '有一次，孟嘗君到秦國去。秦昭王本來想請他當宰相，可是有人說：「孟嘗君是齊國人，一定會先替齊國著想。」秦昭王就改變主意，把孟嘗君關了起來，打算加害他。',
      '孟嘗君派人去拜託秦昭王最寵愛的妃子說情。妃子說：「我想要孟嘗君那件白狐皮大衣。」可是那件天下獨一無二的狐白裘，孟嘗君一到秦國就送給秦昭王了，哪裡還有第二件？',
      '這時，那位會學狗的門客說：「我能拿到狐白裘。」當天夜裡，他裝成狗溜進秦宮的倉庫，把狐白裘拿了出來。妃子收到大衣，就替孟嘗君說好話，秦昭王便放了他。',
      '孟嘗君連夜往東逃，半夜趕到函谷關。關口規定要等雞叫了，才能開門讓人通過。這時，秦昭王已經後悔，派人騎馬追來了。',
      '那位會學雞叫的門客，立刻「喔喔喔」叫了幾聲。附近的雞聽到了，也跟著叫起來。守關的士兵以為天亮了，就打開關門。等追兵趕到，孟嘗君一行人早就走遠了。',
      '從此，其他門客再也不敢看不起這兩個人。後來，「雞鳴狗盜」就用來比喻有某種卑微技能的人，或指卑微的小技能；也用來形容低下、不光彩的人或事。'
    ],
    mean: '會學雞叫、會裝狗偷東西的門客，幫孟嘗君逃出秦國。比喻有某種卑微技能的人，或指卑微的小技能；也用來形容低下、不光彩的人或事。',
    usage: ['原本是指不起眼、被人看不起的小本領，或有這種本領的人。', '也常用來批評偷偷摸摸、不光彩的手段（貶義）。', '它不是稱讚人「本領高強、多才多藝」的話，不能用來誇獎別人的才藝。'],
    misuse: [],
    eg: ['這些雞鳴狗盜的把戲，騙得了一時，騙不了一輩子。', '別小看雞鳴狗盜的小本領，孟嘗君就是靠它們才逃出秦國的。'],
    syn: ['鼠竊狗偷'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '秦昭王最寵愛的妃子，要孟嘗君送她什麼？', opts: ['一件白狐皮大衣', '一隻會學雞叫的雞', '一匹跑得很快的馬', '一塊珍貴的美玉'], a: 0, why: '第四段：妃子說「我想要孟嘗君那件白狐皮大衣」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '函谷關要等到雞叫了，才會開門讓人通過。', a: true, why: '第六段：「關口規定要等雞叫了，才能開門讓人通過。」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '一開始，其他門客為什麼覺得跟那兩個人排在一起很丟臉？', opts: ['覺得他們的本領不光彩', '那兩個人長得很難看', '他們不肯分享食物', '他們從來都不說話'], a: 0, why: '第二段：一個人會學狗去偷東西，一個人會學雞叫，大家覺得這種本領上不了檯面，所以覺得丟臉。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '孟嘗君能逃出秦國，靠的是哪兩件事？', opts: ['狗盜拿出大衣、雞鳴騙開關門', '秦王後悔了、妃子派兵保護', '門客打敗守關士兵、搶到馬', '齊國派大軍到秦國來救他'], a: 0, why: '第五段：狗盜拿出狐白裘，讓妃子替他說情；第七段：雞鳴學雞叫騙開函谷關。兩件事合起來，他才逃得出去。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '孟嘗君收留了大家看不起的人，後來卻靠他們救了自己。你覺得這個故事想告訴我們什麼？你同意「每一種本領都有它的用處」嗎？請說明理由。',
        ref: '我覺得故事告訴我們，不要隨便看不起別人的本領。學雞叫看起來沒什麼用，卻幫孟嘗君騙開了關門。我同意每種本領都可能有用處，不過偷東西這種本領用錯地方就會害人，所以本領也要用在對的地方。',
        rubric: ['說出故事想告訴我們的道理', '用故事內容當例子（學雞叫、學狗偷東西的用處）', '對「每一種本領都有用」提出看法，最好能想到本領要用在對的地方'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「雞鳴狗盜」原本指的是什麼樣的本領？', opts: ['不起眼的小本領', '打敗敵人的大本領', '養雞養狗的本領', '讀很多書的學問'], a: 0, why: '雞鳴狗盜原本是學雞叫、學狗偷東西這種被人看不起的小本領。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '園遊會上，阿明的攤位賣得不太好。他偷偷把隔壁攤的價目表改高，又跑到別人的攤位前小聲說：「他們的東西不新鮮喔。」這些事後來被同學發現，告訴了老師。老師說：「做生意要靠好東西和好服務，不能用這種偷偷摸摸、不光彩的小手段。」', q: '阿明的做法，最適合用哪個成語形容？', opts: ['雞鳴狗盜', '世外桃源', '完璧歸趙', '畫龍點睛'], a: 0, why: '「雞鳴狗盜」也用來形容低下、不光彩的手段。阿明偷改價目表、說別人壞話，就是這種小手段。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈頒獎典禮〉主持人介紹得到全國鋼琴比賽冠軍的小芸：「小芸從小認真練琴，琴藝高超，真是雞鳴狗盜！」', q: '主持人用「雞鳴狗盜」稱讚小芸，恰當嗎？', opts: ['不恰當，它指卑微的本領，不能用來稱讚', '恰當，因為小芸擁有一項很特別的本領', '恰當，因為小芸每天很早起床練琴', '不恰當，因為才藝比賽和雞、狗都無關'], a: 0, why: '雞鳴狗盜是指卑微、不光彩的本領，不能用來稱讚高超的琴藝。成語是比喻，跟真的雞、狗無關。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「他總是用偷看別人答案、假冒家長簽名這些雞鳴狗盜的手段，最後還是被發現了。」這句話的「雞鳴狗盜」用得恰當。', a: true, why: '偷看答案、假冒簽名都是不光彩的小手段，用雞鳴狗盜形容恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '孟嘗君沒有看不起任何一種本領。想一想，你身邊有沒有人有一項「看起來不起眼」的本領，其實在某個時候很有用？請舉例說明。',
        ref: '我的表弟很會記路，大家都覺得這沒什麼。有一次全家去一個不熟的城市，手機沒電了，大家都不知道怎麼回旅館，結果表弟記得每一個轉角，帶我們走了回去。',
        rubric: ['舉出一個看起來不起眼的本領', '說出它在什麼情況下派上用場', '說明自己從這件事想到什麼（例如不要看不起別人）'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '想要贏得別人的信任，就要靠真本事，靠那些＿＿＿＿的小手段，大家遲早會離開你。', opts: ['雞鳴狗盜', '畫龍點睛', '完璧歸趙', '聞雞起舞'], a: 0, why: '「小手段」是不光彩的做法，用雞鳴狗盜。另外三個都是正面意思，放進句子不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '〈讀書心得〉孟嘗君平常就收留各種本領的人。後來他在秦國遇到危險，就是靠著那兩位雞鳴狗盜的門客幫忙，才順利逃回齊國。', q: '心得裡的「雞鳴狗盜」用得恰當。', a: true, why: '這裡指的就是會學雞叫、會學狗偷東西的那兩位門客，用法和典故一樣，恰當。' }
    ]
  },

  // ==================== L3 寓意加深 ====================
  {
    id: 'cy052', lv: 3, word: '捲土重來', zhuyin: 'ㄐㄩㄢˇ ㄊㄨˇ ㄔㄨㄥˊ ㄌㄞˊ', src: '唐．杜牧〈題烏江亭〉',
    quote: '江東子弟多才俊，卷土重來未可知',
    facts: ['語出唐．杜牧〈題烏江亭〉詩：「勝敗兵家事不期，包羞忍恥是男兒。江東子弟多才俊，卷土重來未可知。」｜教育部《成語典》典源', '烏江亭相傳是項羽兵敗後不肯渡江的地方；杜牧認為項羽應該忍住羞愧回江東，重新整頓再來｜教育部《成語典》典故說明', '典源寫作「卷」，「卷」同「捲」；「捲土」是人馬奔跑時掀起塵土｜教育部《成語典》釋義', '項羽不肯渡江時說：「縱江東父兄憐而王我，我何面目見之？」｜《史記．項羽本紀》'],
    story: [
      '唐朝有一位詩人叫杜牧。有一天，他經過烏江邊的一座亭子，想起了一千多年前發生在這裡的事。',
      '秦朝滅亡以後，項羽和劉邦爭奪天下。項羽自稱「西楚霸王」，打仗幾乎沒有輸過。可是在垓下一戰，他的軍隊被打散了，只剩下少數人跟著他突圍，一路逃到烏江邊。',
      '烏江的對岸就是江東，那是項羽起兵的地方。當年，他帶著八千名江東子弟出來打天下。守亭子的亭長已經準備好一條船，勸他：「江東雖然不大，也足夠讓您重新稱王，請趕快渡江吧！」',
      '項羽卻搖搖頭：「當年八千子弟跟著我渡江，現在沒有一個能跟我回去。就算江東的父老可憐我，我又有什麼臉去見他們？」他不肯上船，最後再也沒有回到江東。',
      '很多人佩服項羽有骨氣，杜牧卻不這麼想。他寫下一首詩：「勝敗兵家事不期，包羞忍恥是男兒。江東子弟多才俊，卷土重來未可知。」',
      '意思是：打仗有勝有敗，誰也說不準；能忍住一時的羞愧，才是真正的男子漢。江東有很多優秀的年輕人，如果項羽回去重新整頓，再帶兵打回來，誰輸誰贏還不知道呢！',
      '「捲土」是說軍隊奔跑時掀起滿天的塵土。後來，「捲土重來」就用來比喻失敗以後，重新整頓，再來一次；也可以用來說某種情況又恢復、又回來了。'
    ],
    mean: '軍隊奔跑時捲起塵土，再一次打回來。比喻失敗以後重新整頓，再來一次；也比喻原來的局面、情況又恢復了。',
    usage: ['用在「失敗以後不放棄，重新整頓、再試一次」的時候。', '也可以用在某種情況又回來了，例如：「寒流捲土重來」「流感捲土重來」。', '和「東山再起」很像：東山再起側重「重新崛起」；捲土重來側重「重新整頓再來」。'],
    misuse: [],
    eg: ['去年在決賽只輸了一分，今年球隊捲土重來，終於抱回冠軍。', '才剛放晴兩天，寒流又捲土重來，大家趕快把外套拿出來。'],
    syn: ['重整旗鼓', '東山再起'], ant: ['一蹶不振', '偃旗息鼓'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '杜牧是在什麼地方，想起了項羽的故事？', opts: ['烏江邊的一座亭子', '垓下的戰場上', '項羽的家鄉江東', '劉邦的皇宮裡'], a: 0, why: '第一段：杜牧「經過烏江邊的一座亭子」，想起了以前發生在這裡的事。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '亭長準備好了船，勸項羽渡江回江東。', a: true, why: '第三段：亭長「已經準備好一條船」，勸他「請趕快渡江吧」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '項羽為什麼不肯上船渡江？', opts: ['覺得沒臉見江東的父老', '擔心船太小坐不下', '江東已經被劉邦占領', '想留下來看江邊風景'], a: 0, why: '第四段：八千子弟沒有一個能跟他回去，他說「我又有什麼臉去見他們」。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '很多人佩服項羽不肯渡江，杜牧卻不這麼想。杜牧的看法是什麼？', opts: ['項羽應該忍住羞愧，回去重來', '項羽很有骨氣，值得大家學習', '項羽應該向劉邦投降才對', '項羽一開始就不應該打仗'], a: 0, why: '第五、六段：杜牧認為「能忍住一時的羞愧，才是真正的男子漢」，回江東重新整頓，誰輸誰贏還不知道。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '你比較同意「項羽很有骨氣」的說法，還是杜牧「應該忍住羞愧、捲土重來」的看法？請用故事內容說明理由。',
        ref: '我比較同意杜牧。打仗有輸有贏，輸了一次不代表永遠輸。江東還有很多人才，項羽如果回去重新整頓，說不定可以打回來。覺得丟臉就放棄，反而把所有機會都放掉了。',
        rubric: ['清楚說出同意哪一種看法', '用故事內容當理由（例如江東多才俊、勝敗難料）', '理由前後說得通'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「捲土重來」的「捲土」原本是指什麼？', opts: ['人馬奔跑時掀起的塵土', '把泥土捲起來帶回家', '打掃時掃起的灰塵', '颳大風吹起的沙子'], a: 0, why: '「捲土」是軍隊人馬奔跑時掀起的滿天塵土。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小宇去年參加全市的機器人比賽，因為程式出錯，第一輪就被淘汰。他沒有放棄，回家把錯誤一個一個記下來，每個週末都和隊友重新設計、反覆測試。今年他們又報名參加，一路過關，最後拿到了第二名。', q: '小宇的隊伍今年的表現，最適合用哪個成語形容？', opts: ['捲土重來', '望洋興嘆', '杯水車薪', '四面楚歌'], a: 0, why: '去年失敗，今年重新整頓再來一次，就是捲土重來。望洋興嘆是能力不夠而無可奈何，杯水車薪是力量太小沒有用，四面楚歌是孤立無援。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈氣象報導〉前幾天的梅雨鋒面離開後，天氣晴朗了兩天。氣象局說，明天起另一波鋒面捲土重來，各地又會開始下雨。', q: '氣象報導用「捲土重來」，恰當嗎？', opts: ['恰當，可以用來說某種情況又回來了', '不恰當，捲土重來只能說打仗的軍隊', '不恰當，因為鋒面不會捲起塵土', '恰當，因為下雨時地上會有泥土'], a: 0, why: '《成語典》說捲土重來也可以比喻恢復舊有的局面、局勢。晴了兩天又回到下雨的天氣，就是原來的局面又回來了，可以這樣用。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '這些成語跟「捲土重來」是什麼關係？配起來。', pairs: [['重整旗鼓', '意思相近'], ['一蹶不振', '意思相反'], ['望洋興嘆', '意思無關']], why: '重整旗鼓是失敗後重新整頓，跟捲土重來相近；一蹶不振是跌倒一次就再也站不起來，相反；望洋興嘆是能力不夠的感嘆，跟這件事無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '失敗以後，要怎麼「捲土重來」？請想一次你失敗或沒做好的經驗，說說你可以怎麼重新整頓，再試一次。',
        ref: '上學期我的數學考試考得不好，因為分數的題目都錯了。我想先把錯的題目抄在本子上，每天練習兩題，不會的就去問老師。下次考試前，再把本子從頭看一遍，這次一定要把分數的題目做對。',
        rubric: ['說出一次失敗的經驗', '找出失敗的原因', '提出重新整頓、再試一次的具體做法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '這次歌唱比賽沒有晉級，她並不灰心，打算再練習一年，明年＿＿＿＿。', opts: ['捲土重來', '望洋興嘆', '杯水車薪', '螳螂捕蟬'], a: 0, why: '這次失敗、明年再來，用捲土重來。望洋興嘆是無可奈何，杯水車薪是力量太小，螳螂捕蟬是只顧眼前利益，放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '兩年前，學校附近的河堤長滿了外來種的藤蔓，志工們花了好幾個月才清理乾淨。今年春天，有人發現河堤上又冒出一片一片的藤蔓，而且長得比以前還快，把好多小樹都蓋住了，志工隊只好再次集合，準備清除。', q: '河堤上藤蔓的情形，可以用哪一個成語形容？', opts: ['捲土重來', '未雨綢繆', '高山流水', '洛陽紙貴'], a: 0, why: '清除過的藤蔓又長回來，是原來的情況又恢復了，可以用捲土重來。未雨綢繆是事先準備，高山流水形容樂曲高妙，洛陽紙貴形容作品暢銷。' }
    ]
  },
  {
    id: 'cy055', lv: 3, word: '高山流水', zhuyin: 'ㄍㄠ ㄕㄢ ㄌㄧㄡˊ ㄕㄨㄟˇ', src: '《列子．湯問》',
    quote: '伯牙所念，鍾子期必得之',
    facts: ['語本《列子．湯問》：伯牙善於彈琴，鍾子期善於聽琴；伯牙心裡想著高山、流水，鍾子期都能聽出來｜教育部《成語典》典源', '伯牙在泰山北邊遇到暴雨，彈了下雨的曲子、山崩的聲音，鍾子期都聽得懂｜《列子．湯問》', '鍾子期死後，伯牙認為再也沒有人懂他的音樂，把琴摔壞，終生不再彈琴；「知音」一詞也從這個故事來｜教育部《成語典》典故說明（另見《呂氏春秋．本味》）', '「高山流水」形容樂曲高妙，也比喻知音才懂的樂曲｜教育部《成語典》釋義'],
    story: [
      '春秋時代，楚國有一位很會彈琴的人，叫做伯牙。他有一位好朋友叫鍾子期，最懂得聽琴。',
      '伯牙彈琴的時候，心裡想著什麼，琴聲就會帶著什麼樣的感覺。有一次，他一邊彈，一邊想著登上高山。鍾子期閉著眼睛聽，忽然說：「彈得真好！琴聲又高又雄偉，好像泰山就在眼前！」',
      '伯牙換了一首曲子，心裡想著奔流的河水。鍾子期又說：「太好了！琴聲浩浩蕩蕩，就像長江和黃河在奔流！」不管伯牙心裡想什麼，鍾子期都能從琴聲裡聽出來。',
      '有一天，兩人到泰山北邊遊玩，突然下起大雨，只好躲在大岩石下面。伯牙心裡有些難過，就拿起琴來彈。他先彈出綿綿細雨的聲音，又彈出山崩石落的聲音。每一首曲子，鍾子期都能說出其中的意思。',
      '伯牙放下琴，感動的說：「你真會聽啊！你心裡想的，就跟我心裡想的一樣。在你面前，我的琴聲什麼都藏不住。」',
      '《列子》的故事寫到這裡為止。另一本古書《呂氏春秋》還記了後來的事：鍾子期過世了，伯牙非常傷心，他覺得世界上再也沒有人能像鍾子期那樣懂他的琴聲，就把琴摔壞，一輩子不再彈琴。',
      '伯牙和鍾子期的故事流傳得很廣。後來，「志在高山」「志在流水」就濃縮成「高山流水」，用來形容樂曲非常高妙，也比喻只有知音才懂的音樂。「知音」這個詞也是從這裡來的，用來比喻真正了解自己的朋友。'
    ],
    mean: '伯牙彈琴時心想高山、流水，只有鍾子期聽得出來。形容樂曲非常高妙；也比喻只有知音才懂的音樂，常用來說知音難得。',
    usage: ['用來形容音樂非常高妙、動人。', '也可以比喻只有知音才聽得懂的音樂，或用來說真正懂自己的朋友很難得。', '它不是在說風景裡有高山和流水，描寫風景不能用這個成語。'],
    misuse: ['「我們去爬山，沿途都是高山流水，風景好漂亮！」✗　高山流水是形容音樂高妙、知音難得，不是描寫山和水的風景。'],
    eg: ['那位老師傅拉的二胡有如高山流水，聽得大家都入迷了。', '鋼琴家說，能遇到一位真正聽得懂她音樂的人，就像伯牙遇到鍾子期，是高山流水的知音。'],
    syn: ['陽春白雪'], ant: ['下里巴人'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '伯牙心裡想著登高山時，鍾子期說琴聲像什麼？', opts: ['高大雄偉的泰山', '奔流的長江黃河', '綿綿的細雨', '山崩石落'], a: 0, why: '第二段：鍾子期說「琴聲又高又雄偉，好像泰山就在眼前」。長江黃河是伯牙想著流水的時候。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '鍾子期過世以後，伯牙還是每天彈琴給別人聽。', a: false, why: '第六段：伯牙「把琴摔壞，一輩子不再彈琴」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '伯牙說「在你面前，我的琴聲什麼都藏不住」，意思是什麼？', opts: ['鍾子期完全聽得懂他的心意', '鍾子期會偷偷把他的琴藏起來', '他的琴聲太大，藏也藏不住', '他不想再彈琴給鍾子期聽'], a: 0, why: '前一句是「你心裡想的，就跟我心裡想的一樣」，意思是他用琴聲表達的心情，鍾子期全都聽得出來。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '伯牙在鍾子期過世後把琴摔壞，最能看出什麼？', opts: ['對他來說，知音比琴聲更重要', '他覺得那把琴已經太舊了', '他想要換一把更好的琴', '他從此討厭所有的音樂'], a: 0, why: '把第五、六段連起來：伯牙最珍惜的是有人懂他的琴聲。失去了知音，他覺得彈琴再也沒有人懂，才不再彈。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '伯牙因為失去知音，就一輩子不再彈琴。你覺得他這樣做值得嗎？如果你是伯牙的朋友，你會對他說什麼？',
        ref: '我覺得可以理解，但有點可惜。鍾子期懂他，所以他很傷心。可是如果他繼續彈，也許還會遇到新的知音，而且鍾子期應該也希望他繼續彈琴。我會跟他說：「你的琴聲那麼美，鍾子期一定不希望它消失。」',
        rubric: ['清楚說出值得或不值得，並說理由', '用到故事內容（鍾子期是唯一懂他琴聲的人）', '說出一句具體想對伯牙說的話'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「高山流水」最常用來形容什麼？', opts: ['樂曲高妙、知音難得', '高山聳立、溪水奔流', '爬山流汗、口渴喝水', '夏天出遊、溪邊玩水'], a: 0, why: '高山流水形容樂曲高妙，也比喻知音才懂的音樂，不是在說山和水。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '音樂課上，老師播放一段古琴演奏。同學們有的聊天，有的打瞌睡，只有小芸聽得眼眶紅紅的。下課後她跟老師說：「這首曲子好像在描寫山上的雲和溪水，我聽了心裡好平靜。」老師驚訝的說：「作曲家寫的就是山水，妳真的聽懂了！」', q: '小芸和這首曲子之間，最適合用哪個成語形容？', opts: ['高山流水', '望洋興嘆', '杯水車薪', '螳螂捕蟬'], a: 0, why: '別人都沒在聽，只有小芸聽懂了曲子要表達的意思，就像鍾子期聽懂伯牙，是高山流水、知音難得。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈遊記〉這次我們去花蓮的峽谷，一邊是高聳的山壁，一邊是嘩啦啦的溪水，真是高山流水，美得讓人說不出話來。', q: '遊記用「高山流水」形容峽谷的風景，恰當嗎？', opts: ['不恰當，它形容音樂，不是風景', '恰當，因為峽谷真的有高山和溪水', '恰當，因為風景美得像一首歌', '不恰當，因為那裡的山不夠高'], a: 0, why: '高山流水是形容樂曲高妙、知音難得，不能從字面拿來描寫山水風景。' },
      { id: 'p4', k: 'pair', d: 3, type: 'mc', q: '「下里巴人」是指通俗、大家都會唱的歌。它和「高山流水」是什麼關係？', opts: ['意思相反', '意思相近', '意思完全一樣', '兩個都是地名'], a: 0, why: '高山流水是高妙、只有知音才懂的音樂；下里巴人是通俗的音樂，意思相反。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '鍾子期能從琴聲裡聽出伯牙的心意。在你的生活中，誰最能「聽懂」你？你又可以怎麼做，成為別人的「知音」？',
        ref: '我的好朋友小安最懂我，我不開心的時候，他看我的表情就知道，還會陪我去操場走一走。我也想當別人的知音，所以同學跟我說話時，我會認真聽完，不急著插嘴，再問問他心裡真正的想法。',
        rubric: ['說出一個懂自己的人，並舉出例子', '提出成為別人知音的具體做法', '做法和「用心聽懂對方」有關'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '這首古琴曲意境深遠，有如＿＿＿＿，不是隨便聽一聽就能懂的。', opts: ['高山流水', '捲土重來', '杯水車薪', '未雨綢繆'], a: 0, why: '形容樂曲高妙、要用心才懂，用高山流水。捲土重來是失敗再來，杯水車薪是力量太小，未雨綢繆是事先準備，放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉今天去看哥哥的吉他表演。他彈完以後，全場只有他的好朋友阿凱，說得出他想用這首歌表達的心情。哥哥說，阿凱就是他高山流水的知音。', q: '日記裡的「高山流水」用得恰當。', a: true, why: '阿凱聽得懂哥哥的音樂想表達什麼，就像鍾子期懂伯牙，用「高山流水的知音」恰當。' }
    ]
  },
  {
    id: 'cy059', lv: 3, word: '望洋興嘆', zhuyin: 'ㄨㄤˋ ㄧㄤˊ ㄒㄧㄥ ㄊㄢˋ', src: '《莊子．秋水》',
    quote: '於是焉河伯始旋其面目，望洋向若而歎',
    facts: ['語本《莊子．秋水》：河伯以為天下之美盡在自己，到了北海看不見水的盡頭，才「望洋向若而歎」｜教育部《成語典》典源', '「望洋」是抬頭仰視的意思，「若」是北海的海神｜教育部《成語典》釋義、典故說明', '有人把「望洋興嘆」解釋成「對著大洋興嘆」，這是望文生義，不可取｜教育部《成語典》典故說明', '「望洋興嘆」比喻因力量不夠而感到無可奈何｜教育部《成語典》用法說明'],
    story: [
      '《莊子．秋水》裡有一位河神，叫做河伯，他管的是黃河。',
      '某一年秋天，雨水特別多，大大小小的河流都把水灌進黃河。黃河的水漲得又高又寬，站在這一岸，連對岸是牛還是馬都看不清楚。',
      '河伯高興極了，以為天下所有的美景，都集中在自己身上了。他順著河水往東走，想去看看別的地方有沒有比他更了不起的。',
      '一路走到北海，河伯朝東邊望去：浪花一波接著一波，一直連到天邊，根本看不到水的盡頭。他這才發現，原來自己最得意的黃河，跟大海比起來實在太小了。',
      '河伯收起得意的臉，抬起頭，仰望著北海的海神，長長的嘆了一口氣：「俗話說：『懂了一點道理，就以為誰都比不上自己。』說的就是我啊！要不是今天親眼看見您，我就要被真正有見識的人笑話一輩子了。」',
      '這一段的原文是「望洋向若而歎」。「望洋」是抬起頭往上看的樣子，「若」是北海海神的名字，意思是河伯「抬頭仰望著海神而嘆氣」。很多人以為「望洋」是「看著海洋」，那是從字面猜的，並不正確。',
      '河伯嘆氣，是因為他發現自己遠遠比不上大海。後來，「望洋興嘆」就用來比喻：因為自己的能力、力量不夠，面對一件事只能感嘆，覺得無可奈何。'
    ],
    mean: '河伯抬頭仰望海神而嘆氣。比喻因為能力、力量不夠，只能感嘆，覺得無可奈何。',
    usage: ['用在「想做一件事，可是能力或條件不夠，只能嘆氣」的時候。', '「望洋」是抬頭仰望，不是「看著海洋」；站在海邊讚嘆海景，不是這個成語的意思。', '「望洋興嘆」側重能力不足；「無可奈何」側重想不出辦法。'],
    misuse: ['「我們站在澎湖的沙灘上，看著藍藍的大海，望洋興嘆：好美啊！」✗　這是從字面猜成「看著海洋讚嘆」。望洋興嘆是因為能力不夠而無可奈何。'],
    eg: ['這道數學題超出我們學過的範圍，全班同學只能望洋興嘆。', '那套精裝百科全書要好幾千元，我存的零用錢不夠，只好望洋興嘆。'],
    syn: ['無可奈何', '無能為力'], ant: ['唾手可得'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '秋天黃河的水漲得多大？', opts: ['河面寬到看不清對岸是牛是馬', '河水漲到淹過了附近的山頂', '河水多到把大海都填滿了', '河面窄到一步就能跳過去'], a: 0, why: '第二段：「站在這一岸，連對岸是牛還是馬都看不清楚。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '原文「望洋向若而歎」的「若」，是北海海神的名字。', a: true, why: '第六段：「『若』是北海海神的名字。」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '河伯說「我就要被真正有見識的人笑話一輩子了」，表示他明白了什麼？', opts: ['自己以前太驕傲、見識太少', '大海的海神很喜歡笑別人', '黃河其實比大海還要大', '自己應該留在北海不回去'], a: 0, why: '河伯前面說「懂了一點道理，就以為誰都比不上自己，說的就是我」，表示他發現自己以前太驕傲了。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '根據文章，「望洋興嘆」的「望洋」應該怎麼解釋才對？', opts: ['抬起頭往上看的樣子', '看著一大片的海洋', '希望有一片海洋', '往海洋的方向走'], a: 0, why: '第六段：「『望洋』是抬起頭往上看的樣子」，以為是「看著海洋」是從字面猜的。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '河伯一開始很驕傲，看到大海後卻願意承認自己不足。你覺得「承認自己不夠好」容易嗎？這對一個人有什麼好處？請用故事和你的經驗說明。',
        ref: '我覺得不容易，因為大家都希望自己很厲害。可是河伯承認了，北海的海神才願意跟他談更大的道理。我以前不肯承認自己英文發音不好，後來願意請同學糾正，才慢慢念得比較標準。',
        rubric: ['說出承認不足容不容易', '用故事內容說明承認不足的好處', '連結自己的經驗'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「望洋興嘆」比喻什麼？', opts: ['能力不夠，只能無可奈何', '看到大海，覺得很開心', '喜歡旅行，到處去看海', '很會游泳，不怕大浪'], a: 0, why: '望洋興嘆比喻因為能力、力量不夠，只能感嘆、無可奈何。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校要組一支管樂隊去參加比賽，需要會吹薩克斯風的人。阿凱很想參加，可是他連樂譜都看不懂，家裡也沒有樂器，比賽卻下個月就要舉行。他看著報名表，嘆了一口氣說：「我真的很想去，可是現在的我根本做不到。」', q: '阿凱這時候的心情，最適合用哪個成語形容？', opts: ['望洋興嘆', '捲土重來', '未雨綢繆', '洛陽紙貴'], a: 0, why: '阿凱很想參加，卻因為能力不夠只能嘆氣，就是望洋興嘆。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈日記〉今天我們去墾丁，站在海邊看著一望無際的大海，海水藍得好漂亮，我忍不住望洋興嘆：「哇，好美啊！」', q: '日記裡的「望洋興嘆」用得恰當嗎？', opts: ['不恰當，它是能力不夠的感嘆，不是讚嘆海景', '恰當，因為作者真的站在海邊看著海洋讚嘆', '恰當，因為墾丁的海非常漂亮', '不恰當，因為墾丁的海不夠大，不算汪洋'], a: 0, why: '望洋興嘆的「望洋」是抬頭仰望，意思是能力不夠而無可奈何，不是看著海洋讚嘆。這是《成語典》特別提醒的望文生義。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '這些成語跟「望洋興嘆」是什麼關係？配起來。', pairs: [['無能為力', '意思相近'], ['唾手可得', '意思相反'], ['未雨綢繆', '意思無關']], why: '無能為力是沒有能力做到，跟望洋興嘆相近；唾手可得是很容易就得到，相反；未雨綢繆是事先準備，跟這件事無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '遇到自己能力還做不到的事，除了「望洋興嘆」，還可以怎麼做？請舉一個例子，說說你的計畫。',
        ref: '我很想參加學校的游泳比賽，可是我只能游二十公尺。與其在旁邊嘆氣，我可以每個週末去游泳池練習，請教練教我換氣，每個月多游五公尺。今年來不及，明年就有機會報名了。',
        rubric: ['舉出一件自己還做不到的事', '提出具體、一步一步的計畫', '說明計畫怎麼讓自己慢慢做到'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '這座城堡模型有三千個零件，才八歲的弟弟看了說明書，也只能＿＿＿＿。', opts: ['望洋興嘆', '捲土重來', '高山流水', '洛陽紙貴'], a: 0, why: '零件太多，弟弟能力還做不到，只能嘆氣，用望洋興嘆。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '社區游泳池要舉辦橫渡比賽，選手要一口氣游完五十公尺。小美才剛學會換氣，最多只能游十公尺。她站在池邊，看著大哥哥大姊姊一個個躍入水中，嘆了一口氣：「我現在還游不到那麼遠，只能在旁邊幫大家加油了。」', q: '小美在池邊的心情，像哪一個成語？', opts: ['望洋興嘆', '高山流水', '東山再起', '杯水車薪'], a: 0, why: '小美很想參加，卻因為能力還不夠，只能在旁邊嘆氣，就是望洋興嘆。' }
    ]
  },
  {
    id: 'cy063', lv: 3, word: '未雨綢繆', zhuyin: 'ㄨㄟˋ ㄩˇ ㄔㄡˊ ㄇㄡˊ', src: '《詩經．豳風．鴟鴞》',
    quote: '迨天之未陰雨，徹彼桑土，綢繆牖戶',
    facts: ['語本《詩經．豳風．鴟鴞》：鳥兒趁著天還沒陰雨，剝取桑根的皮，纏緊、修補巢的門窗｜教育部《成語典》典源、典故說明', '〈鴟鴞〉是詩人藉鳥兒築巢養雛的辛苦，抒發自己經歷的憂患｜教育部《成語典》典故說明', '「綢繆」是緊密纏繞；「繆」讀ㄇㄡˊ，不可寫作「謬」｜教育部《成語典》辨識', '《詩經》是最早的詩歌總集，「豳風」是古豳國的歌謠｜教育部《成語典》典故說明'],
    story: [
      '《詩經》是中國最早的詩歌總集，收了三百多首從周朝到春秋時候的歌謠。其中的「豳風」，是古代豳地的民歌。',
      '豳風裡有一首詩叫〈鴟鴞〉。鴟鴞就是貓頭鷹。這首詩用一隻小鳥的口吻來唱歌。',
      '小鳥唱著：「貓頭鷹啊貓頭鷹，你已經抓走了我的孩子，請不要再毀掉我的家！我辛辛苦苦、一心一意的養育孩子，真是太勞累了。」',
      '接著，小鳥又唱：「趁著天還沒變陰、還沒下雨，我要趕快去剝桑樹根的皮，把窩的門和窗一圈一圈纏緊、補好。這樣，樹下的人們，誰還敢欺負我呢？」',
      '小鳥知道，等到風雨來了再修窩，就來不及了。所以牠在天氣還好的時候，就一趟又一趟的飛來飛去，啣回樹皮，把窩纏得牢牢的。',
      '詩人借小鳥築巢養育孩子的辛苦，唱出自己遇到的憂患。後來，人們從「迨天之未陰雨，徹彼桑土，綢繆牖戶」這幾句詩，濃縮出「未雨綢繆」這個成語。',
      '「綢繆」是緊緊纏繞的意思，「繆」不能寫成錯誤的「謬」。「未雨綢繆」就是還沒下雨，先把門窗纏緊、修好，比喻事先做好準備，預防可能發生的困難。'
    ],
    mean: '天還沒下雨，就先把門窗纏緊、修好。比喻事先做好準備，預防可能發生的困難。',
    usage: ['用在「事情還沒發生，就先做好準備」的時候（褒義）。', '事情已經發生了才補救，要說「亡羊補牢」；事到臨頭才匆忙準備，是「臨渴掘井」「臨陣磨槍」，都和未雨綢繆相反。', '「未雨綢繆」側重做好準備，用得比較廣；「防患未然」側重防範災禍。'],
    misuse: ['「颱風把屋頂吹壞以後，叔叔馬上請人來修，真是未雨綢繆。」✗　屋頂已經壞了才修，是事後補救，不是事先準備。'],
    eg: ['颱風季節快到了，媽媽未雨綢繆，先把手電筒和乾糧準備好。', '開學前，哥哥未雨綢繆，把每一科的課本都先預習了一遍。'],
    syn: ['曲突徙薪', '有備無患', '防患未然'], ant: ['臨渴掘井', '臨陣磨槍'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '小鳥打算在什麼時候修補自己的窩？', opts: ['天還沒下雨的時候', '下大雨的那天晚上', '貓頭鷹飛走的冬天', '孩子長大離開以後'], a: 0, why: '第四段：「趁著天還沒變陰、還沒下雨，我要趕快去剝桑樹根的皮。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '「鴟鴞」就是貓頭鷹。', a: true, why: '第二段：「鴟鴞就是貓頭鷹。」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '小鳥為什麼要趁天氣好的時候修窩？', opts: ['等風雨來了再修就來不及了', '天氣好的時候樹皮比較好吃', '貓頭鷹規定牠一定要修窩', '下雨天的時候小鳥不會飛'], a: 0, why: '第五段：「小鳥知道，等到風雨來了再修窩，就來不及了。」' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '詩人為什麼要用「小鳥修窩」來寫這首詩？', opts: ['借小鳥的辛苦，說出自己的憂患', '因為詩人小時候養過一隻小鳥', '因為豳地只有小鳥和貓頭鷹', '因為詩人想教大家怎麼築巢'], a: 0, why: '第六段：「詩人借小鳥築巢養育孩子的辛苦，唱出自己遇到的憂患。」' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '小鳥說：「這樣，樹下的人們，誰還敢欺負我呢？」你覺得事先做好準備，為什麼能讓人比較不怕困難？請用故事和你的生活經驗說明。',
        ref: '因為準備好了，困難來的時候就知道怎麼辦，不會手忙腳亂。小鳥把窩纏牢了，風雨來也不怕。像我上台報告前先練習三次，上台時就算緊張，也記得要講什麼，比較不會害怕。',
        rubric: ['說出事先準備讓人不怕困難的原因', '用故事內容當證據（小鳥把窩纏牢）', '舉出自己的生活經驗'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「未雨綢繆」的「綢繆」是什麼意思？', opts: ['緊緊纏繞、修補好', '下了很大的雨', '說錯了話、做錯事', '布料又軟又滑'], a: 0, why: '「綢繆」是緊密纏繞，詩裡是把窩的門窗纏緊、修補好。「謬」才是錯誤的意思。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '下個月班上要去校外教學。小隊長小真上星期就先查好天氣預報，提醒組員帶雨衣，又把集合地點和老師的電話寫在小卡片上發給每個人，還準備了一個裝著OK繃和衛生紙的小包包。出發那天果然下起毛毛雨，大家一點也不慌。', q: '小真的做法，最適合用哪個成語形容？', opts: ['未雨綢繆', '臨渴掘井', '杯水車薪', '望洋興嘆'], a: 0, why: '小真在事情發生前就把可能需要的東西準備好，是未雨綢繆。臨渴掘井是事到臨頭才準備，剛好相反。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈聯絡簿〉明天就要月考了，哥哥今天晚上十點才開始翻課本，一直讀到半夜。他說自己是在未雨綢繆。', q: '哥哥說自己「未雨綢繆」，用得恰當。', a: false, why: '考試前一晚才開始讀，是事到臨頭才準備，比較像「臨陣磨槍」，不是事先準備。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '哪一個成語的意思和「未雨綢繆」相反？', opts: ['臨渴掘井', '有備無患', '防患未然', '曲突徙薪'], a: 0, why: '臨渴掘井是口渴了才挖井，事到臨頭才準備，和未雨綢繆相反。其他三個都是事先準備的意思。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '颱風、地震、考試、比賽……生活中有很多需要事先準備的事。請選一件，說說你會怎麼「未雨綢繆」，列出至少兩個準備步驟。',
        ref: '我選地震。我會跟家人一起準備一個緊急包，放手電筒、水、餅乾和急救用品，放在門口容易拿的地方。我們也會約好地震時要躲在哪裡、震完要去哪個公園集合。',
        rubric: ['選出一件需要事先準備的事', '列出至少兩個具體準備步驟', '說明這些準備可以預防什麼問題'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '雖然現在還是晴天，但上山要＿＿＿＿，雨衣和保暖的外套一定要帶著。', opts: ['未雨綢繆', '望洋興嘆', '捲土重來', '螳螂捕蟬'], a: 0, why: '天氣還好就先準備雨衣、外套，是事先準備，用未雨綢繆。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'mc', ctx: '〈新聞〉某國小在還沒有發生地震以前，就請消防隊來教全校師生避難演練，還在每間教室準備了緊急包。記者稱讚這所學校未雨綢繆。', q: '記者用「未雨綢繆」稱讚學校，恰當嗎？', opts: ['恰當，地震還沒發生就先做好準備', '不恰當，因為那一天並沒有下雨', '不恰當，應該說亡羊補牢才對', '恰當，因為學校有請消防隊來'], a: 0, why: '學校在災害發生前就先演練、準備，是未雨綢繆。成語是比喻，跟有沒有下雨無關；亡羊補牢是出事以後才補救。' }
    ]
  },
  {
    id: 'cy066', lv: 3, word: '洛陽紙貴', zhuyin: 'ㄌㄨㄛˋ ㄧㄤˊ ㄓˇ ㄍㄨㄟˋ', src: '《晉書．文苑列傳．左思》',
    quote: '於是豪貴之家競相傳寫，洛陽為之紙貴',
    facts: ['典出《晉書．文苑列傳．左思》：左思構思〈三都賦〉十年，家中門庭、籬笆、廁所都放著紙筆，想到一句就寫下來｜教育部《成語典》典源', '〈三都賦〉完成後起初不受重視，經皇甫謐作序、張載等人作注，司空張華讚嘆，豪貴之家競相傳寫，洛陽紙價因此上漲｜教育部《成語典》典故說明', '左思沒去過成都，向張載請教蜀地的事；又覺得自己見聞不廣，請求擔任祕書郎｜《晉書．文苑列傳．左思》', '「洛陽紙貴」形容作品風行一時，流傳甚廣（褒義）｜教育部《成語典》用法說明'],
    story: [
      '西晉的時候，有一位文學家叫左思。他長得不好看，說話也不太流利，朋友不多，寫的文章一開始也沒什麼人注意。',
      '可是左思寫文章非常用心。他花了一整年，寫成一篇描寫齊國都城的〈齊都賦〉。接著，他想寫一篇更大的作品，描寫三國時代魏、蜀、吳三個國家的都城，叫做〈三都賦〉。',
      '剛好他的妹妹左芬被選進宮裡，左思一家就搬到了都城洛陽。左思從來沒去過蜀國的成都，就跑去請教熟悉那裡的張載，打聽當地的風土民情。',
      '為了寫好〈三都賦〉，左思構思了整整十年。他在家裡到處放著紙和筆，門邊、籬笆旁，連廁所都不例外，只要一想到好句子，就馬上寫下來。他還覺得自己讀的書不夠多，特地請求擔任管理圖書的祕書郎，好讀更多資料。',
      '〈三都賦〉寫好以後，一開始並沒有受到重視。後來，幾位有名的學者讀了都非常欣賞，有人替它寫序，有人替它作注解。大文學家張華讀完更是讚嘆：「這篇文章讀完了還意猶未盡，越讀越有新意！」',
      '這下子，洛陽有錢有地位的人家，都搶著抄寫〈三都賦〉。那時候還沒有印刷機，要讀一篇文章，只能一個字一個字抄在紙上。大家搶著買紙，洛陽的紙價竟然因此漲了起來。',
      '後來，「洛陽紙貴」就用來形容作品寫得好，風行一時，大家搶著閱讀，流傳得很廣。'
    ],
    mean: '大家搶著抄寫左思的〈三都賦〉，洛陽的紙因此變貴。形容作品寫得好，風行一時，流傳很廣。',
    usage: ['用來稱讚文章、書籍等作品受到歡迎，大家搶著讀（褒義）。', '它說的是「作品」暢銷，不是說紙或其他東西的價錢變貴。', '作品沒有人想看，可以說「乏人問津」，跟洛陽紙貴相反。'],
    misuse: ['「颱風過後菜價大漲，一顆高麗菜要一百多元，真是洛陽紙貴。」✗　洛陽紙貴是形容作品暢銷，不是說東西的價錢變貴。'],
    eg: ['這本描寫臺灣老街的繪本一出版就洛陽紙貴，書店都補不到貨。', '學姊寫的校園小說在網路上連載，同學們搶著看，一時洛陽紙貴。'],
    syn: [], ant: ['乏人問津'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '左思為了寫〈三都賦〉，在家裡做了什麼特別的事？', opts: ['到處放紙筆，想到好句子就寫', '把房子漆成魏蜀吳三種顏色', '請張華住進家裡幫他寫', '每天去洛陽的市場買紙'], a: 0, why: '第四段：他在家裡到處放著紙和筆，「只要一想到好句子，就馬上寫下來」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '〈三都賦〉一寫好，馬上就受到大家的重視。', a: false, why: '第五段：「〈三都賦〉寫好以後，一開始並沒有受到重視。」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '左思為什麼要去請教張載？', opts: ['他沒去過成都，想了解當地', '張載是管理圖書的祕書郎', '張載想要買下他的文章', '他想請張載替他抄文章'], a: 0, why: '第三段：左思「從來沒去過蜀國的成都」，所以去請教熟悉那裡的張載。當祕書郎的是左思自己。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '洛陽的紙為什麼會變貴？', opts: ['大家搶著抄文章，買紙的人變多', '左思寫文章時把洛陽的紙都買光了', '皇帝下令把洛陽紙的價錢提高', '造紙的工人都去讀文章了'], a: 0, why: '把第五、六段連起來：學者讚賞以後，大家搶著抄寫；那時候只能用手抄在紙上，買紙的人一多，紙價就漲了。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '左思長得不好看、說話不流利，文章一開始也沒人重視，最後卻讓洛陽紙貴。你覺得他成功的原因有哪些？這給你什麼啟發？',
        ref: '我覺得他成功的原因，是他非常用心，花了十年構思，隨時記下好句子，不懂的地方還去請教別人、多讀資料。這讓我知道，外表或口才不是最重要的，只要認真把一件事做好，總會有人看見。',
        rubric: ['說出至少兩個成功的原因', '原因都有故事內容當根據（構思十年、請教別人、多讀書）', '說出自己得到的啟發'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「洛陽紙貴」形容的是什麼？', opts: ['作品受歡迎，大家搶著看', '洛陽的紙品質特別好', '東西的價錢一直上漲', '洛陽有很多賣紙的店'], a: 0, why: '洛陽紙貴形容作品風行一時，大家搶著讀，不是說紙的品質或物價。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校的校刊社推出一本《校園怪談》小冊子，故事寫得又好笑又有點可怕。第一天放在圖書館，一百本就被借光了，還有同學排隊等著借，各班也來問能不能多印一些。校刊社只好趕快加印，下課時大家都在討論裡面的故事。', q: '《校園怪談》受歡迎的情形，最適合用哪個成語形容？', opts: ['洛陽紙貴', '杯水車薪', '望洋興嘆', '螳螂捕蟬'], a: 0, why: '作品一推出就被搶著借、搶著讀，還要加印，就是洛陽紙貴。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈新聞〉最近紙的成本上漲，文具店影印一張從一元漲到兩元，學生們抱怨：「真是洛陽紙貴啊！」', q: '學生們用「洛陽紙貴」抱怨影印變貴，恰當嗎？', opts: ['不恰當，它是說作品暢銷，不是紙價上漲', '恰當，因為影印一張的價錢真的變貴了', '恰當，因為影印講義要用到很多紙', '不恰當，因為他們的學校不在洛陽'], a: 0, why: '洛陽紙貴是形容作品受歡迎、流傳很廣，不能用來說東西的價錢變貴。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「這本書出版好幾年了，書店裡還是堆得滿滿的，沒什麼人買，真是洛陽紙貴。」這句話的「洛陽紙貴」用得恰當。', a: false, why: '書沒人買，應該說「乏人問津」，剛好和洛陽紙貴相反。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '左思為了寫好文章，構思了十年，還到處請教別人。如果你要寫一篇讓同學「搶著看」的文章，你會怎麼準備？請說出至少兩個做法。',
        ref: '我想寫一篇介紹學校後山昆蟲的文章。我會先去後山觀察、拍照，把看到的昆蟲記下來；再去圖書館查資料，請教自然老師。寫完以後先給兩個同學看，問他們哪裡看不懂，再修改。',
        rubric: ['說出想寫的主題', '提出至少兩個具體的準備做法', '做法和故事中左思的用心有呼應（例如觀察、請教、修改）'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '這位作家的新書一推出就＿＿＿＿，不到一個星期就再印了三次。', opts: ['洛陽紙貴', '杯水車薪', '未雨綢繆', '螳螂捕蟬'], a: 0, why: '新書大受歡迎、一直加印，用洛陽紙貴。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '五年級的小安把自己養蠶寶寶的觀察日記，做成一本有照片、有圖畫的小書，放在班級書櫃。沒想到同學們一個接一個借回家看，隔壁班也跑來借，最後老師只好幫他多印十本，讓全年級輪流傳閱，大家都說下次還想看。', q: '小安的觀察日記受歡迎的情形，像哪一個成語？', opts: ['洛陽紙貴', '望洋興嘆', '捲土重來', '高山流水'], a: 0, why: '作品被大家搶著借、還要多印才夠看，就是洛陽紙貴。' }
    ]
  },
  {
    id: 'cy069', lv: 3, word: '杯水車薪', zhuyin: 'ㄅㄟ ㄕㄨㄟˇ ㄐㄩ ㄒㄧㄣ', src: '《孟子．告子上》',
    quote: '猶以一杯水救一車薪之火也',
    facts: ['語本《孟子．告子上》：孟子說「仁之勝不仁也，猶水之勝火」，但現在行仁的人，就像用一杯水去救一車柴火燒起的火｜教育部《成語典》典源', '孟子認為：火沒熄，就說水不能勝火，這反而是在幫助不仁｜《孟子．告子上》', '《文子．上德》也有「水之勢勝火，一酌不能救一車之薪」的說法｜教育部《成語典》參考資料', '「車」在這個成語裡讀ㄐㄩ｜教育部《成語典》注音'],
    story: [
      '戰國時代的思想家孟子，一輩子都在勸國君和讀書人要行「仁」，也就是用愛心和善意對待別人。',
      '有一天，孟子對學生說：「仁能夠勝過不仁，就像水能夠勝過火一樣。」學生點點頭：水可以澆熄火，善良也可以打敗邪惡，這很好懂。',
      '孟子接著說：「可是現在行仁的人，就好像拿著一杯水，去救一整車柴火燒起來的大火。」',
      '想想看：一整車的木柴燒得劈哩啪啦，火焰比人還高。你端著一個小杯子跑過去，「嘩」的一聲潑上去，火連小一點都沒有，還是熊熊的燒著。',
      '這時候，有人就搖搖頭說：「你看，水根本贏不了火嘛！」',
      '孟子說，這種說法是錯的。不是水贏不了火，而是水太少了。同樣的，不是仁贏不了不仁，而是有些人只做了一點點好事，就說「我已經盡力了，做好事沒有用」。這樣反而是在幫助不仁的一方，到最後，連原本那一點點仁也會失去。',
      '孟子的意思是：做好事要真心誠意、用足力氣，不能只做表面。後來，「杯水車薪」就用來比喻力量太小，對事情一點幫助也沒有。'
    ],
    mean: '用一杯水去撲滅一整車木柴燒起來的火。比喻力量太小，對事情沒有幫助（無濟於事）。',
    usage: ['用在「付出的力量和要解決的問題差太多，根本沒有用」的時候。', '它強調力量太小沒有用；如果很多小力量累積起來，最後真的成功了，要說「積少成多」，不能說杯水車薪。', '「無濟於事」也是沒有用，但不一定是因為力量太小，用的範圍比較廣。'],
    misuse: ['「全班每人捐十元，杯水車薪，最後湊到了買新球的錢。」✗　最後真的成功了，是積少成多，不是杯水車薪。'],
    eg: ['水庫的水位已經見底，昨晚那場小雨對缺水的情況來說，只是杯水車薪。', '倉庫的火越燒越大，鄰居們提著水桶潑水也只是杯水車薪，還是要靠消防車來滅火。'],
    syn: ['無濟於事', '於事無補'], ant: ['大有助益'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '孟子說，仁勝過不仁，就像什麼？', opts: ['水勝過火', '火勝過水', '車勝過馬', '人勝過天'], a: 0, why: '第二段：「仁能夠勝過不仁，就像水能夠勝過火一樣。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '孟子認為，一杯水澆不熄大火，就證明水贏不了火。', a: false, why: '第六段：孟子說這種說法是錯的，「不是水贏不了火，而是水太少了」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '一杯水澆不熄一車柴火，真正的原因是什麼？', opts: ['水太少，不是水贏不了火', '柴火天生就比水強大', '那杯水被太陽曬熱了', '車上的柴火太溼了'], a: 0, why: '第六段：「不是水贏不了火，而是水太少了。」' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '孟子用「一杯水救一車柴火」，想批評當時的什麼人？', opts: ['做一點好事就說沒用的人', '根本不知道怎麼救火的人', '把柴火堆在車上的人', '喜歡喝水勝過喝酒的人'], a: 0, why: '把第三段和第六段連起來：孟子批評的是「只做了一點點好事，就說做好事沒有用」的人。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '孟子說，只做一點點好事就放棄，反而是在幫助不仁的一方。你同意嗎？請用故事和一個生活中的例子說明你的看法。',
        ref: '我同意。只潑一杯水就說救不了火，然後走開，火只會越燒越大。像班上有人被欺負，如果我只安慰一次就說「沒用」，欺負的人會更大膽。應該找更多同學和老師一起幫忙，力量夠大才有用。',
        rubric: ['清楚說出同不同意', '用故事內容當理由（水太少不是水沒用）', '舉出一個生活中的例子'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「杯水車薪」比喻什麼？', opts: ['力量太小，沒有幫助', '水很少，要省著用', '車子太重，跑不動', '慢慢做，總會完成'], a: 0, why: '杯水車薪比喻力量太小，對事情沒有幫助。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校的游泳池漏水了，修理要花五十萬元。小美的班級辦了一次義賣，賺了八百元，大家很開心的把錢交給校長。校長謝謝大家的心意，也老實的說：「這筆錢很珍貴，不過離修好游泳池還差得很遠，學校還要另外想辦法。」', q: '從修游泳池的費用來看，這八百元可以用哪個成語形容？', opts: ['杯水車薪', '洛陽紙貴', '高山流水', '捲土重來'], a: 0, why: '五十萬元的修理費，只有八百元，力量太小，對修好游泳池幫助不大，就是杯水車薪。這是說金額太少，不是說大家的心意不好。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈班會紀錄〉班費不夠買新的掃具。大家決定每人每週存五元，一個學期下來，竟然存到了三千元，買齊了所有掃具。班長說：「雖然每次都是杯水車薪，但我們做到了！」', q: '班長用「杯水車薪」恰當嗎？', opts: ['不恰當，小錢累積後有用，是積少成多', '恰當，因為每次只存五元，金額很小', '恰當，因為班費原本就不夠用', '不恰當，因為班費和水、柴火無關'], a: 0, why: '杯水車薪是力量太小、沒有幫助。大家存的小錢最後真的買齊了掃具，是積少成多，剛好相反。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '這些成語跟「杯水車薪」是什麼關係？配起來。', pairs: [['無濟於事', '意思相近'], ['大有助益', '意思相反'], ['高山流水', '意思無關']], why: '無濟於事是對事情沒有幫助，跟杯水車薪相近；大有助益是很有幫助，相反；高山流水是形容音樂高妙，跟這件事無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '有時候一個人的力量很小，就像一杯水。你覺得怎麼做，才能讓「一杯水」變得有用？請舉一個生活中的例子說明。',
        ref: '一個人撿社區公園的垃圾，可能撿不完，是杯水車薪。可是如果我邀請同學、鄰居一起來，每人撿一袋，再請里長放更多垃圾桶，大家的力量合起來，公園就能變乾淨。',
        rubric: ['舉出一個力量太小的生活例子', '提出讓力量變大的具體做法（例如找人合作、持續去做）', '說明這樣做為什麼有效'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '全村的稻田都乾得裂開了，只靠我們家這一桶井水，簡直是＿＿＿＿。', opts: ['杯水車薪', '未雨綢繆', '洛陽紙貴', '東山再起'], a: 0, why: '一桶水對全村的稻田沒有用，力量太小，用杯水車薪。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '期末考只剩一天，阿哲的數學課本有六個單元都還沒複習。他打開課本，只看了第一單元的兩頁，就說：「好了，我有讀了。」第二天考試，大部分的題目他都不會寫。他這才明白，這麼一點點準備，對一整本的考試範圍來說，根本沒有幫助。', q: '阿哲考前讀的那兩頁，像哪一個成語？', opts: ['杯水車薪', '未雨綢繆', '螳螂捕蟬', '洛陽紙貴'], a: 0, why: '六個單元只讀兩頁，力量太小，對考試沒有幫助，就是杯水車薪。' }
    ]
  },
  {
    id: 'cy072', lv: 3, word: '螳螂捕蟬', zhuyin: 'ㄊㄤˊ ㄌㄤˊ ㄅㄨˇ ㄔㄢˊ', src: '《莊子．山木》',
    quote: '螳蜋執翳而搏之，見得而忘其形',
    facts: ['典出《莊子．山木》：莊子在雕陵的栗林裡，看見蟬貪涼蔭、螳螂躲在葉子後面捕蟬、異鵲又要吃螳螂，自己也正拿彈弓瞄準異鵲｜教育部《成語典》典源、典故說明', '莊子驚覺「物固相累，二類相召也」，丟下彈弓離開，卻被守園的人追著責罵｜《莊子．山木》', '漢．劉向《說苑．正諫》有吳王的侍從用「螳螂捕蟬，黃雀在後」勸吳王不要攻打楚國的故事｜教育部《成語典》參考資料', '「螳螂捕蟬」比喻眼光短淺，只貪圖眼前利益而不顧後患｜教育部《成語典》用法說明'],
    story: [
      '有一天，莊子到一個叫雕陵的地方散步，走進了一片圍著籬笆的栗子樹林。',
      '忽然，一隻奇怪的大鵲鳥從南方飛來。牠的翅膀張開有七尺寬，眼睛大大的。大鵲鳥從莊子的額頭旁邊擦過去，停在栗子樹上。',
      '莊子覺得很奇怪：「這是什麼鳥？翅膀那麼大卻飛不遠，眼睛那麼大卻看不清楚。」他提起衣服，輕手輕腳的走過去，舉起彈弓，想把大鵲鳥射下來。',
      '就在這時候，他看見樹上有一隻蟬，躲在涼爽的樹蔭下，舒服得忘了要小心。蟬的後面，一隻螳螂用葉子把自己遮起來，正準備撲上去抓蟬。螳螂眼裡只有蟬，完全忘了自己的危險。而那隻大鵲鳥，就停在螳螂後面，伸長脖子要吃螳螂。大鵲鳥一心想著螳螂，也沒發現樹下的莊子正拿彈弓瞄準牠。',
      '莊子看到這一幕，心裡一驚：「唉！萬物原來都是這樣互相牽連，一個在算計另一個！」他想到自己也正一心盯著大鵲鳥，說不定也有危險在背後，就趕緊丟下彈弓，轉身往外走。',
      '沒想到，看守栗子林的人以為他是來偷栗子的，追在後面大聲罵他。莊子回家以後，悶悶不樂了好幾天。',
      '後來，漢朝劉向的《說苑》也記了一個很像的故事，還多了一句「黃雀在後」。「螳螂捕蟬」就用來比喻眼光短淺，只貪圖眼前的利益，卻沒注意到背後的危險。'
    ],
    mean: '螳螂只顧著捕蟬，不知道後面有鳥要吃牠。比喻眼光短淺，只貪圖眼前的利益，忽略了背後的危險。',
    usage: ['用在「只想著眼前的好處，沒注意到後面的危險」的時候（貶義）。', '常和「黃雀在後」連在一起說：「螳螂捕蟬，黃雀在後」，意思一樣。', '重點是「貪圖眼前、忽略後患」；只是很專心做一件事，不能用這個成語來稱讚。'],
    misuse: [],
    eg: ['他只顧著搶特價品，錢包從口袋掉出來都不知道，真是螳螂捕蟬。', '球隊拚命進攻、不管防守，結果被對手快攻得分，正是螳螂捕蟬，黃雀在後。'],
    syn: [], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '莊子舉起彈弓，原本想射什麼？', opts: ['一隻奇怪的大鵲鳥', '一隻躲在樹蔭的蟬', '一隻準備抓蟬的螳螂', '看守栗子林的人'], a: 0, why: '第三段：莊子「舉起彈弓，想把大鵲鳥射下來」。' },
      { id: 'r2', p: 1, d: 1, type: 'order', q: '依照故事，從「被盯上的」排到「在最後面瞄準的」。', items: ['蟬', '螳螂', '大鵲鳥', '莊子'], why: '第四段：螳螂要抓蟬，大鵲鳥要吃螳螂，莊子拿彈弓瞄準大鵲鳥。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '莊子為什麼丟下彈弓，轉身就走？', opts: ['想到自己背後也可能有危險', '他的彈弓壞掉了，射不出彈丸', '那隻大鵲鳥已經飛得很遠了', '守林人叫他馬上離開'], a: 0, why: '第五段：他想到「自己也正一心盯著大鵲鳥，說不定也有危險在背後」。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '守林人追著罵莊子，這件事和故事中的哪個道理最相合？', opts: ['莊子盯著鳥，自己也被人盯著', '栗子林裡的栗子又大又好吃', '守林人很喜歡那隻奇怪的鵲鳥', '莊子散步時走錯了路'], a: 0, why: '把第四、五、六段連起來：莊子一心想射鳥時，自己也成了守林人眼中的「小偷」，正好跟蟬、螳螂、大鵲鳥一樣，前面有目標，後面有人盯著。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '蟬、螳螂、大鵲鳥都「只看到前面」。你覺得在生活中，要怎麼提醒自己「也看看後面」？請用故事和一個例子說明。',
        ref: '故事裡每一隻動物都只盯著眼前的獵物，結果自己也有危險。我在玩躲避球時，常常只想著接球、丟人，忘了看後面，結果被從後面丟過來的球打到。我可以提醒自己每接一次球就轉頭看一下四周。',
        rubric: ['說出故事中的動物犯了什麼錯', '舉出生活中「只看前面」的例子', '提出具體提醒自己的方法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「螳螂捕蟬」比喻什麼？', opts: ['貪圖眼前利益，忽略背後危險', '螳螂很會抓蟲，是農夫的好幫手', '做事要專心，一次只做好一件', '夏天到了，樹上很熱鬧'], a: 0, why: '螳螂只顧捕蟬，不知道後面有鳥要吃牠，比喻只貪圖眼前利益，忽略背後的危險。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小傑在夜市玩撈金魚，一心想撈到那隻最大的紅金魚，蹲在攤位前整整半小時。他把書包放在腳邊，完全沒注意它。等他終於撈到金魚，開心的站起來，才發現書包不見了，裡面還有他的悠遊卡和家裡的鑰匙。', q: '小傑的遭遇，最適合用哪個成語形容？', opts: ['螳螂捕蟬', '洛陽紙貴', '高山流水', '未雨綢繆'], a: 0, why: '小傑只顧著眼前的金魚，忽略了身邊書包的危險，就像只顧捕蟬的螳螂。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈作文〉我的好朋友小安做事很專心。畫畫的時候，就算旁邊很吵，他也能一筆一筆把畫完成。我覺得他就像螳螂捕蟬一樣，值得大家學習。', q: '作文用「螳螂捕蟬」稱讚小安專心，用得恰當。', a: false, why: '螳螂捕蟬是批評人只顧眼前、忽略後面的危險，不是稱讚專心。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「那家店為了多賺一點錢，偷偷用便宜的壞材料，結果被客人發現，再也沒有人上門，真是螳螂捕蟬，黃雀在後。」這句話的「螳螂捕蟬，黃雀在後」用得恰當。', a: true, why: '店家只貪眼前多賺一點，沒想到後面的大麻煩，用得恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '故事裡的每一隻動物都只看到眼前的好處。想一想，你有沒有「只顧眼前、忘了後果」的經驗？下次你會怎麼提醒自己？',
        ref: '有一次我為了先玩電動，把作業拖到很晚才寫，結果太累寫錯很多題，第二天還被老師要求訂正。下次我會先想一想：「現在先玩，等一下會發生什麼事？」再決定先做哪一件。',
        rubric: ['說出一個只顧眼前的具體經驗', '說出後來發生的後果', '提出下次提醒自己的方法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '他只想著把對手的球擋下來，卻沒發現自己的球門空了，結果被對方射門得分，真是＿＿＿＿，黃雀在後。', opts: ['螳螂捕蟬', '杯水車薪', '高山流水', '洛陽紙貴'], a: 0, why: '「＿＿，黃雀在後」是螳螂捕蟬的固定說法：只顧眼前的球，忽略了背後的危險。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '遊戲課玩搶旗子，阿明看見對方的旗子沒人守，興奮的衝過去拔旗。他一心只看著旗子，沒注意到對方兩個人早就躲在旁邊。阿明剛拿到旗子，就被他們一左一右拍到肩膀，被判出局，旗子也被搶了回去。', q: '阿明在搶旗子遊戲裡的情形，像哪一個成語？', opts: ['螳螂捕蟬', '東山再起', '未雨綢繆', '望洋興嘆'], a: 0, why: '阿明只看到眼前的旗子，忽略了旁邊埋伏的人，就像只顧捕蟬、不知道背後有鳥的螳螂。' }
    ]
  },
  {
    id: 'cy075', lv: 3, word: '東山再起', zhuyin: 'ㄉㄨㄥ ㄕㄢ ㄗㄞˋ ㄑㄧˇ', src: '南朝宋．劉義慶《世說新語．排調》',
    quote: '安石不肯出，將如蒼生何',
    facts: ['典出南朝宋．劉義慶《世說新語．排調》：謝安隱居東山，朝廷屢次徵召都不出來，後來出任桓溫的司馬｜教育部《成語典》典源', '謝安出發時，官員在新亭送行，中丞高靈開玩笑說：「安石不肯出，將如蒼生何？今亦蒼生將如卿何？」謝安笑而不答｜《世說新語．排調》', '謝安再度任職後為朝廷立了不少功勞，官至宰相｜教育部《成語典》典故說明', '「東山再起」比喻官員退隱後再度出任官職，也比喻失敗後重新崛起｜教育部《成語典》釋義'],
    story: [
      '東晉的時候，有一位很有才華的人叫謝安，字安石。他個性悠閒，不喜歡當官，就帶著家人住在東山，每天讀書、彈琴，和朋友遊山玩水。',
      '朝廷知道謝安有本事，好幾次派人請他出來做官，他都婉拒了。大家常常私下說：「安石不肯出來做官，天下的百姓該怎麼辦呢？」',
      '過了很多年，謝安終於答應將軍桓溫的邀請，出來擔任司馬，幫忙管理軍隊的事務。',
      '謝安要出發上任時，許多官員都到新亭來替他送行。有一位叫高靈的官員，先喝了幾杯酒，假裝有點醉了，開玩笑的對謝安說：「你以前一再不聽朝廷的命令，在東山高高的躺著。大家都說：『安石不肯出來，天下百姓怎麼辦？』現在你出來了，天下百姓又要拿你怎麼辦呢？」',
      '謝安聽了，只是笑一笑，什麼話也沒說。',
      '謝安這次出來做官，替朝廷立了很多功勞，後來還當上了宰相。',
      '因為謝安是從東山再一次出來做官，後來的人就用「東山再起」比喻退隱的人再度出來擔任職務；也用來比喻失敗或低潮以後，重新振作、再度崛起。'
    ],
    mean: '謝安退隱東山以後，又再度出來做官。比喻官員退隱後再度出任職務；也比喻失敗以後重新崛起。',
    usage: ['原本用在退隱的官員，又再一次出來擔任職務。', '今天也常用在失敗或低潮以後，重新振作、再度成功。', '要先有「退下來」或「失敗」，才說得上「再起」；第一次就成功，不能說東山再起。', '和「捲土重來」很像：東山再起側重「重新崛起」，捲土重來側重「重新整頓再來」。'],
    misuse: [],
    eg: ['那位老闆的公司倒閉後，他從擺地攤重新做起，五年後東山再起。', '那家麵店去年因為火災停業，今年在原地重新開張，東山再起，生意比以前還好。'],
    syn: ['捲土重來', '重整旗鼓'], ant: ['一蹶不振'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '謝安隱居在哪裡？', opts: ['東山', '新亭', '洛陽', '烏江'], a: 0, why: '第一段：謝安「帶著家人住在東山」。新亭是大家替他送行的地方。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '朝廷第一次派人請謝安，他就馬上答應出來做官。', a: false, why: '第二段：朝廷「好幾次派人請他出來做官，他都婉拒了」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '大家說「安石不肯出來做官，天下的百姓該怎麼辦」，表示大家怎麼看謝安？', opts: ['覺得他很有本事，國家需要他', '覺得他很懶惰，一直不想工作', '覺得他住的東山太遠了', '覺得他常常喝醉酒，不肯做事'], a: 0, why: '大家擔心「天下的百姓該怎麼辦」，表示大家認為謝安很有本事，國家需要他出來幫忙。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '高靈把話改成「天下百姓又要拿你怎麼辦呢」，是在開什麼玩笑？', opts: ['以前大家盼你，現在換你給交代', '百姓們其實一點都不喜歡謝安', '謝安出來做官就會變窮', '謝安應該回到東山繼續睡大覺'], a: 0, why: '以前是大家盼望謝安出來；現在謝安出來了，換他要做出成績，給百姓一個交代。高靈用倒過來的說法開玩笑。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '謝安聽了高靈的玩笑，只是笑一笑，沒有回答。你覺得謝安心裡可能在想什麼？如果是你，你會怎麼回答？',
        ref: '我覺得謝安心裡可能在想：「說再多也沒用，做出成績來大家就知道了。」所以他只是笑一笑。如果是我，我會說：「謝謝大家的期待，我會努力不讓百姓失望。」後來謝安真的立了很多功勞，用行動回答了大家。',
        rubric: ['推想謝安心裡的想法，並說出根據', '說出自己會怎麼回答', '能連結到故事後來的發展（立功、當宰相）'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「東山再起」的「東山」是指什麼？', opts: ['謝安隱居的地方', '太陽升起的方向', '一座很高的山', '謝安當官的城市'], a: 0, why: '東山是謝安隱居的地方。他從東山再一次出來做官，所以叫東山再起。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '王阿姨的早餐店開了三年，因為口味普通，客人越來越少，只好關門。她沒有放棄，跑去跟老師傅學了一年做蘿蔔糕和蛋餅，又在原來的街口重新開店。這次她做的早餐又香又好吃，開幕沒多久，門口每天早上都排著長長的隊伍。', q: '王阿姨重新開店成功，最適合用哪個成語形容？', opts: ['東山再起', '螳螂捕蟬', '望洋興嘆', '杯水車薪'], a: 0, why: '早餐店關門是失敗，王阿姨重新學習、再開店成功，就是東山再起。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈新聞短評〉這位歌手今年第一次出唱片，就拿下了年度最佳新人獎。報導說她「東山再起，表現亮眼」。', q: '報導用「東山再起」形容這位歌手，用得恰當。', a: false, why: '她是第一次出唱片就成功，之前並沒有退下來或失敗，不能說「再起」。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '「東山再起」和「捲土重來」都有失敗後再出發的意思。根據《成語典》，兩者的差別是什麼？', opts: ['東山再起重在崛起，捲土重來重在整頓再來', '東山再起重在整頓再來，捲土重來重在崛起', '東山再起多用在打仗，捲土重來多用在做官', '兩個成語的意思完全相反'], a: 0, why: '《成語典》辨識：「東山再起」側重於重新崛起；「捲土重來」側重於重新整頓再來。不能說反。東山再起出自謝安再出來做官，不是打仗。兩個意思相近，不是相反。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '謝安在東山休息了很多年，後來又出來做大事。你有沒有因為失敗或累了先停下來，後來又重新開始的經驗？說說是什麼讓你「再起」。',
        ref: '我學直排輪時摔得很痛，有好幾個月都不想再碰。後來看到表哥溜得好開心，又請他教我怎麼戴好護具、怎麼練習煞車。重新開始以後，我現在已經可以溜完整個公園了。',
        rubric: ['說出一個停下來的經驗和原因', '說出讓自己重新開始的人或事', '說明重新開始後的結果或收穫'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '這支球隊去年降到乙組，今年苦練了一整年，終於重回甲組，＿＿＿＿。', opts: ['東山再起', '螳螂捕蟬', '杯水車薪', '高山流水'], a: 0, why: '先降級（失敗），再重回甲組，是東山再起。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'mc', ctx: '〈新聞〉某家玩具工廠十年前因為經營不善倒閉。老闆沒有放棄，從小小的手工坊重新做起，今年工廠又開張了，產品還賣到國外。記者說他東山再起。', q: '記者用「東山再起」形容這位老闆，恰當嗎？', opts: ['恰當，他失敗以後又重新振作起來', '不恰當，因為工廠不在東山上', '不恰當，因為老闆不是古代官員', '恰當，因為他的產品賣到了國外'], a: 0, why: '東山再起也比喻失敗後重新崛起。老闆工廠倒閉後重新做起、再度成功，用得恰當。' }
    ]
  },

  // ==================== L4 分辨用法 ====================
  {
    id: 'cy079', lv: 4, word: '約法三章', zhuyin: 'ㄩㄝ ㄈㄚˇ ㄙㄢ ㄓㄤ', src: '《史記．高祖本紀》',
    quote: '與父老約，法三章耳：殺人者死，傷人及盜抵罪',
    facts: ['語出《史記．高祖本紀》：漢元年十月，劉邦先到霸上、進入咸陽，召集各縣父老豪傑，約定「法三章」，廢除秦朝的其他法律｜教育部《成語典》典源', '三條法律是：殺人者死，傷人及盜抵罪｜《史記．高祖本紀》', '秦地百姓非常高興，爭著拿牛羊酒食慰勞軍士，劉邦推辭不受｜《史記．高祖本紀》', '今天「約法三章」泛指事先約好或規定的事｜教育部《成語典》釋義'],
    story: [
      '秦朝末年，秦朝的法律非常嚴苛。百姓說錯一句話、幾個人聚在一起聊天，都可能受到很重的處罰。大家怨聲載道，各地紛紛起兵反抗。',
      '起兵的人裡，最有名的是劉邦和項羽。楚懷王和大家約定：誰先打進關中，誰就在關中稱王。',
      '西元前206年，劉邦的軍隊最先到達咸陽附近的霸上。秦王子嬰坐著白馬拉的車，捧著皇帝的玉印出來投降。有些將領說要殺了秦王，劉邦說：「人家已經投降了，再殺他不吉利。」就把秦王交給官員看管。',
      '劉邦進了咸陽，看到秦宮裡堆滿了金銀財寶，本來想住下來。樊噲和張良勸他不要這樣做，劉邦就把秦朝的寶庫封起來，帶兵退回霸上。',
      '接著，劉邦把各縣的長老和地方上有聲望的人請來，對他們說：「各位被秦朝嚴苛的法律折磨很久了。現在我跟大家約定，法律只有三條：殺人的要判死罪；傷人和偷盜的，依照罪行輕重處罰。其他秦朝的法律，全部廢除！官員和百姓都照常生活，不用害怕。」',
      '劉邦又派人和秦朝原來的官員，到各地去宣布這件事。百姓聽了高興極了，紛紛牽著牛羊、帶著酒菜來慰勞士兵。劉邦卻婉拒說：「我們的糧食還夠，不想讓大家破費。」百姓更加高興，只怕劉邦不能留在關中當王。',
      '「約法三章」原本是指劉邦和百姓約定的這三條法律。今天我們用它來泛指事先約好、規定好的事情，常用在家人、同學、團體之間訂下的規矩，例如：「出門前，我們先約法三章。」',
      '要注意：今天的約法三章不一定剛好三條，重點是「事先」訂好、大家一起遵守的規矩。如果只是約好時間、地點見面，並沒有訂下要遵守的規矩，就說「約好」就可以了，不必用約法三章。'
    ],
    mean: '劉邦進入咸陽後，和百姓約定只有三條法律。今天泛指事先約好、規定好的事。',
    usage: ['今天用在「事前先說好規矩或條件」的時候，例如家人、同學、團體之間的約定。', '「約」是約定，「三章」是三條約定；今天不一定剛好三條，重點是「事先約好」。', '《成語典》說它用在「制定規約」的時候；只是約好見面、一起出去玩，沒有訂下要遵守的規矩，不要用約法三章。'],
    misuse: ['「我和小美約法三章，星期六下午兩點在圖書館門口見面。」✗　約法三章是事先訂好要大家遵守的規矩；只是約好時間地點見面，說「約好」就可以了。'],
    eg: ['去夜市之前，爸爸跟我們約法三章：不能亂跑、不能亂買、九點以前要回家。', '班上養了一隻小倉鼠，大家先約法三章，輪流餵食、換水、清籠子。'],
    syn: [], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '劉邦和百姓約定的三條法律，是哪三條？', opts: ['殺人判死罪，傷人和偷盜依罪處罰', '不准說話、不准聚會、不准晚上出門', '要按時交稅、要去當兵、要種田', '要尊敬劉邦、項羽和秦王'], a: 0, why: '第五段：「殺人的要判死罪；傷人和偷盜的，依照罪行輕重處罰。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '劉邦進了咸陽以後，就一直住在秦朝的宮殿裡。', a: false, why: '第四段：樊噲和張良勸他，劉邦就「把秦朝的寶庫封起來，帶兵退回霸上」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '百姓帶牛羊酒菜來慰勞士兵，劉邦為什麼不肯接受？', opts: ['糧食還夠，不想讓百姓破費', '他不喜歡吃牛肉和羊肉', '軍隊裡規定不能喝酒', '他擔心食物不夠新鮮'], a: 0, why: '第六段：劉邦說「我們的糧食還夠，不想讓大家破費」，百姓因此更喜歡他。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '劉邦把秦朝的法律改成只剩三條，最主要的目的是什麼？', opts: ['讓受苦已久的百姓安心、支持他', '讓手下的官員可以少做一點事情', '讓自己可以早一點回家', '讓項羽覺得他非常厲害，不敢來打'], a: 0, why: '把第一段和第五、六段連起來：百姓被嚴苛的法律折磨很久，劉邦廢除苛法，讓大家安心，百姓「只怕劉邦不能留在關中當王」。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '秦朝的法律很多很嚴，劉邦卻只留下三條。你覺得規矩是「越多越好」還是「越簡單越好」？請用故事內容和你在學校或家裡的經驗說明。',
        ref: '我覺得規矩要簡單清楚，但重要的事一定要有。秦朝規定太多太嚴，百姓都很怕；劉邦只留三條最重要的，大家都記得住，也願意遵守。我們班的班規以前有二十條，大家記不住，後來改成五條，反而大家都做到了。',
        rubric: ['清楚說出自己的看法', '用故事內容當理由（秦法嚴苛、三條法律讓百姓安心）', '舉出學校或家裡的經驗'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '今天說「約法三章」，最主要是指什麼？', opts: ['事先約好的規定', '一本書的三個章節', '三個朋友的約會', '法律課的第三章'], a: 0, why: '約法三章今天泛指事先約好、規定好的事。「三章」是三條約定，不是書的章節。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '暑假到了，小宇想多玩一點電動。媽媽沒有直接說不行，而是和他坐下來，一起把規定寫在紙上：每天先寫完作業才能玩、一次最多玩四十分鐘、晚上九點以後不玩。兩個人都簽了名，把紙貼在冰箱上。整個暑假，小宇都照著紙上的規定做。', q: '小宇和媽媽的做法，最適合用哪個成語形容？', opts: ['約法三章', '螳螂捕蟬', '東山再起', '杯水車薪'], a: 0, why: '兩人在暑假開始前先說好規定，就是約法三章。' },
      { id: 'p7', k: 'use', d: 2, type: 'mc', ctx: '〈聯絡簿〉表哥打電話來，說星期天早上九點要帶我去河濱公園騎腳踏車。我們約法三章，九點整在公園門口集合，不見不散。', q: '聯絡簿裡的「約法三章」用得恰當嗎？', opts: ['不恰當，只是約見面，沒有訂規矩', '恰當，因為兩人事先約好了時間', '恰當，因為約好的事剛好有三件', '不恰當，騎車不需要約定'], a: 0, why: '約法三章用在「制定規約」，是事先訂好要大家遵守的規矩。這裡只是約好時間地點見面，說「約好」就可以了。「三章」的重點在訂規矩，不是約了幾件事。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「出發露營前，老師先和全班約法三章：不能單獨離開營地、要跟緊小隊長、垃圾要自己帶走。」這句話的「約法三章」用得恰當。', a: true, why: '在活動開始前先說好規定，用約法三章恰當。' },
      { id: 'p5', k: 'fill', d: 3, type: 'mc', q: '為了不讓分組報告吵架，我們在開始做之前，就先＿＿＿＿，說好誰查資料、誰畫海報、誰上台。', opts: ['約法三章', '東山再起', '捲土重來', '望洋興嘆'], a: 0, why: '開始前先說好分工，用約法三章。東山再起、捲土重來是失敗後再起，望洋興嘆是能力不夠的感嘆，放進句子都不通。' },
      { id: 'p6', k: 'xfer', d: 3, type: 'open', q: '劉邦用簡單清楚的三條規定，讓百姓安心。請替你的家人或班級想一個「約法三章」，寫出三條規定，並說明為什麼要這樣定。',
        ref: '我想替我們家訂「吃飯約法三章」：第一，吃飯時不看手機；第二，每個人說一件今天發生的事；第三，吃完自己把碗拿去洗碗槽。這樣大家會多聊天，媽媽也不用一個人收拾。',
        rubric: ['寫出三條具體、做得到的規定', '說明訂這些規定的原因', '規定簡單清楚，大家容易遵守'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '去游泳池玩以前，教練先和小朋友＿＿＿＿：不能在池邊奔跑、不能推人、聽到哨音就要集合。', opts: ['約法三章', '螳螂捕蟬', '東山再起', '杯水車薪'], a: 0, why: '下水前先說好規定，用約法三章。其他三個放進句子都不通。' },
      { id: 'x3', k: 'use', d: 3, type: 'tf', ctx: '姊姊：「我跟同學約法三章，明天放學一起去書店，四點在校門口等。」\n妹妹：「那妳要記得帶錢包喔！」', q: '姊姊說的「約法三章」用得恰當。', a: false, why: '約法三章是事先訂下要大家遵守的規矩。姊姊只是跟同學約好時間地點一起去書店，說「約好」就可以了。' }
    ]
  },
  {
    id: 'cy083', lv: 4, word: '每況愈下', zhuyin: 'ㄇㄟˇ ㄎㄨㄤˋ ㄩˋ ㄒㄧㄚˋ', src: '《莊子．知北遊》（《成語典》見「每下愈況」條）',
    quote: '正獲之問於監市履狶也，每下愈況',
    facts: ['《成語典》正文收錄「每下愈況」，語出《莊子．知北遊》：東郭子問「道」在哪裡，莊子說在螻蟻、稊稗、瓦甓、屎溺｜教育部《成語典》典源、典故說明', '莊子用市場管理員踩豬小腿估量肥瘦作比喻：越往下部細微處，肥瘦的差別越明顯｜教育部《成語典》釋義', '後來有人從字面推測，改說成「每況愈下」，雖屬訛用，但已成俗；今天都用來比喻情況越來越壞｜教育部《成語典》典故說明', '《成語典》的正文條目是「每下愈況」；「每況愈下」列在這一條的「參考詞語」裡，注音ㄇㄟˇ ㄎㄨㄤˋ ㄩˋ ㄒㄧㄚˋ，釋義是「猶『每下愈況』」，書證有宋．胡仔《苕溪漁隱叢話》｜教育部《成語典》參考詞語','「況」原本是「因比擬而明顯」的意思｜教育部《成語典》釋義'],
    story: [
      '戰國時代，有一位叫東郭子的人，去請教思想家莊子：「你常說的『道』，到底在哪裡？」',
      '莊子說：「道無所不在。」東郭子不滿意：「請你說得具體一點，指出一個地方來。」',
      '莊子說：「在螞蟻身上。」東郭子皺起眉頭：「怎麼這麼低下？」莊子說：「在雜草裡。」「怎麼更低下了？」「在磚頭瓦片裡。」「怎麼越來越過分了？」莊子說：「在大小便裡。」東郭子聽了，再也不說話了。',
      '莊子這才解釋：「你的問題，本來就沒有問到重點。你知道市場上的人怎麼檢查一頭豬肥不肥嗎？市場管理員會用腳去踩豬的小腿。小腿是豬身上最不容易長肉的地方，如果連小腿都有肉，全身一定更肥。所以啊，越往下面、越細小的地方去看，就越看得清楚。」',
      '「每下愈況」就是莊子說的這句話。「每下」是越往下面，「況」是比一比就看得明顯。意思是：越從低下、細微的地方去推求，越能看清真實的情況。莊子想告訴東郭子，道不只在高高的天上，連最不起眼的東西裡都有。',
      '後來，「每下愈況」被用來比喻情況越來越壞。可是《莊子》的原文不好懂，很多人從字面猜意思，就把它說成了「每況愈下」：「況」是情況，「愈下」是越來越差。',
      '教育部《成語典》把「每下愈況」當作正式的條目，「每況愈下」則放在這一條後面的參考詞語裡。《成語典》說明：「每況愈下」原本是說錯了，但是大家已經用習慣了，宋朝的書裡就有人這樣寫。所以今天兩種說法都看得到，意思都是情況越來越糟。',
      '學這個成語，可以發現語言也會「旅行」：一句話從古代傳到今天，可能換了樣子、換了意思，卻還是被大家使用著。'
    ],
    mean: '原作「每下愈況」，指越往下、越細微的地方去看，越看得明顯。今天多說「每況愈下」，比喻情況越來越壞。',
    usage: ['今天用在「情況一天比一天差、越來越糟」的時候。', '它只能說變壞；越來越好要用「蒸蒸日上」，剛好相反。', '《成語典》正文寫作「每下愈況」，「每況愈下」列在它的參考詞語裡，說它「雖屬訛用，但已成俗」；兩種寫法今天都通行，寫「每況愈下」不要被當成錯字。'],
    misuse: ['「自從開始每天練琴，他的琴藝每況愈下，進步得好快！」✗　每況愈下是越來越糟；越來越好要說「蒸蒸日上」或「突飛猛進」。'],
    eg: ['這條老街的生意每況愈下，很多店都拉下了鐵門。', '他熬夜打電動好幾個星期，精神每況愈下，上課常常打瞌睡。'],
    syn: ['江河日下'], ant: ['蒸蒸日上'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '東郭子去問莊子什麼問題？', opts: ['「道」到底在哪裡', '豬要怎麼養才會肥', '市場開在什麼地方', '螞蟻喜歡吃什麼'], a: 0, why: '第一段：東郭子問「你常說的『道』，到底在哪裡？」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '莊子的回答越說越「低下」，東郭子最後為什麼不說話了？', opts: ['覺得莊子的回答越來越不像話', '他終於完全懂了莊子的意思', '他急著要去市場買豬', '他覺得螞蟻非常可愛'], a: 0, why: '第三段：東郭子一直問「怎麼這麼低下」「怎麼越來越過分了」，聽到「在大小便裡」就不想再說了，可見他覺得很不像話，還沒有懂。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '莊子舉「踩豬小腿」的例子，想說明什麼？', opts: ['越從細小的地方看，越看得清楚', '豬的小腿是全身最好吃的部位', '市場管理員每天的工作很辛苦', '東郭子應該去市場工作'], a: 0, why: '第四、五段：小腿最不容易長肉，連小腿都有肉就知道豬很肥；同樣的，越從細微的地方推求，越能看清「道」。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '「每下愈況」後來為什麼會變成「每況愈下」？', opts: ['原文不好懂，大家照字面猜意思', '莊子後來自己把這句話改掉了', '皇帝下令要大家改說法', '印書的人不小心把順序印錯了'], a: 0, why: '第六段：「《莊子》的原文不好懂，很多人從字面猜意思，就把它說成了『每況愈下』。」' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '《成語典》說「每況愈下」原本是說錯的，但大家已經用習慣了。你覺得「大家都這樣說」，原本錯的說法就可以變成對的嗎？請說出你的看法和理由。',
        ref: '我覺得可以，但要有條件。語言是用來溝通的，大家都聽得懂、都這樣用，就變成習慣了，像「每況愈下」現在大家都懂。不過我們還是要知道它原本的樣子，讀古書時才不會看不懂，也不能因為這樣就隨便亂寫字。',
        rubric: ['清楚說出可以、不可以或部分可以', '用文章內容當根據（原文難懂、已經成俗）', '想到另一面（例如要知道原本的說法、不能隨便亂寫）'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '今天說「每況愈下」，是什麼意思？', opts: ['情況越來越壞', '情況越來越好', '每天往下走樓梯', '每次都比別人慢'], a: 0, why: '每況愈下比喻情況越來越壞。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '社區的老公園十幾年沒有整修。一開始只是溜滑梯掉了一點漆，後來盪鞦韆的鐵鍊生鏽、步道的磚塊翹起來，路燈也壞了好幾盞。到了今年，晚上幾乎沒有人敢去散步，連白天來玩的小朋友也越來越少。', q: '這座公園這幾年的情形，最適合用哪個成語形容？', opts: ['每況愈下', '奇貨可居', '望塵莫及', '投鼠忌器'], a: 0, why: '公園一年比一年破舊，情況越來越糟，就是每況愈下。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈運動日記〉自從我每天早上去跑步，體力每況愈下，從一開始跑一圈就喘，到現在可以輕鬆跑完五圈了！', q: '日記裡的「每況愈下」用得恰當嗎？', opts: ['不恰當，體力變好了，每況愈下是越來越差', '恰當，因為作者每天早上都會下樓去操場跑步', '恰當，因為跑步讓作者的體重一直下降', '不恰當，應該寫成每下愈況才對'], a: 0, why: '作者的體力越來越好，每況愈下卻是越來越差，意思相反。至於「每況愈下」和「每下愈況」，今天兩種寫法都看得到，問題不在寫法。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「這家餐廳換了新廚師以後，菜越來越難吃，客人也越來越少，生意每況愈下。」這句話的「每況愈下」用得恰當。', a: true, why: '菜變難吃、客人變少，情況越來越糟，用每況愈下恰當。' },
      { id: 'p5', k: 'pair', d: 3, type: 'match', q: '這些成語跟「每況愈下」是什麼關係？配起來。', pairs: [['江河日下', '意思相近'], ['蒸蒸日上', '意思相反'], ['奇貨可居', '意思無關']], why: '江河日下是像江河的水一天天往下流，比喻情況越來越壞，跟每況愈下相近；蒸蒸日上是一天比一天好，相反；奇貨可居是囤積有價值的東西來謀利，無關。' },
      { id: 'p6', k: 'xfer', d: 3, type: 'open', q: '當你發現某件事「每況愈下」（例如成績、身體、房間整潔），可以怎麼及早發現、及早改善？請舉一個例子說明。',
        ref: '我發現房間越來越亂，一開始只是書桌上多了幾本書，後來地上也堆滿衣服。我可以每天睡前花五分鐘，把東西放回原位；每個星期六再大整理一次。發現開始變亂就馬上收，才不會越來越糟。',
        rubric: ['舉出一件「越來越糟」的生活例子', '說出怎麼及早發現（例如注意小變化）', '提出具體的改善方法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '他上課常常不專心，回家也不複習，成績＿＿＿＿，從前十名掉到了二十名以後。', opts: ['每況愈下', '奇貨可居', '投鼠忌器', '罄竹難書'], a: 0, why: '成績一直往下掉，用每況愈下。奇貨可居是囤積謀利，投鼠忌器是有顧忌不敢下手，罄竹難書是罪狀多，放進句子都不通。' },
      { id: 'x2', k: 'use', d: 3, type: 'mc', ctx: '〈部落格〉這間小書店剛開幕時沒什麼客人，老闆辦了說故事活動以後，客人越來越多，生意每況愈下，週末還要排隊呢！', q: '部落格裡的「每況愈下」用得恰當嗎？', opts: ['不恰當，生意變好了，應該說蒸蒸日上', '恰當，因為客人一個接一個往下走', '恰當，因為書店開在地下一樓', '不恰當，應該說成每下愈況才對'], a: 0, why: '生意越來越好，要說蒸蒸日上；每況愈下是越來越糟。「每況愈下」和「每下愈況」今天都看得到，換成每下愈況意思也一樣是變壞，還是不對。' }
    ]
  },
  {
    id: 'cy086', lv: 4, word: '奇貨可居', zhuyin: 'ㄑㄧˊ ㄏㄨㄛˋ ㄎㄜˇ ㄐㄩ', src: '《史記．呂不韋列傳》',
    quote: '呂不韋賈邯鄲，見而憐之，曰：「此奇貨可居。」',
    facts: ['語出《史記．呂不韋列傳》：呂不韋在趙國邯鄲做生意，看見在趙國當人質、生活困窘的秦國王孫子楚，說「此奇貨可居」｜教育部《成語典》典源', '呂不韋對子楚說「吾能大子之門」，又說「吾門待子門而大」｜《史記．呂不韋列傳》', '後來子楚被立為太子、繼位為國君，拜呂不韋為丞相，呂不韋因此得到數不盡的名與利｜教育部《成語典》典故說明', '「奇貨可居」比喻利用某種專長或有價值的東西以謀利｜教育部《成語典》釋義'],
    story: [
      '戰國時代，有一位很會做生意的大商人，叫呂不韋。他在各地來來往往，用便宜的價錢買進貨物，再用高價賣出去，賺了很多錢。',
      '那時候，秦國和趙國常常打仗。秦國太子安國君有二十幾個兒子，其中一個叫子楚。子楚的母親不受寵愛，他就被送到趙國當「人質」。古時候兩個國家為了表示和好，常常會把王族的孩子送到對方國家去住。',
      '可是秦國一直攻打趙國，趙國人對子楚很不客氣。子楚沒有像樣的車子坐，錢也不夠用，日子過得很不如意。',
      '有一天，呂不韋到趙國的都城邯鄲做生意，遇見了子楚。他心想：「這個人就像一件稀奇的貨物，可以先收藏起來，等以後賣個好價錢！」這句話，原文就是「此奇貨可居」。',
      '呂不韋去見子楚，說：「我可以讓你的家門變得光大。」子楚笑著說：「你還是先光大你自己的家門吧！」呂不韋說：「你不懂，我的家門，要等你的家門光大了，才會跟著光大。」子楚聽懂了，就請他坐下來好好談。',
      '原來，呂不韋打算拿出錢財，替子楚在秦國結交朋友，想辦法讓子楚成為安國君的繼承人。後來計畫真的成功了，子楚當上了秦國的國君，也讓呂不韋當了丞相，呂不韋因此得到了數不盡的名和利。',
      '商人常常把稀少的好貨物囤積起來，等價錢高的時候再賣，這就是「居」，也就是收藏、囤積。後來大家說「奇貨可居」，是指看準了某種本領，或某個稀少、有價值的人、事、物，想拿它來替自己賺取好處。',
      '要注意，這個成語帶著「想從中得到好處」的意思，不是單純稱讚東西很稀奇、很珍貴。'
    ],
    mean: '把稀有的貨物收藏起來，等待高價出售。比喻利用某種專長或有價值的人、事、物，來謀取利益。',
    usage: ['用在「看準某樣稀少、有價值的東西或本領，想藉它得到好處」的時候。', '「居」是收藏、囤積，不是居住。', '它帶有「想從中謀利」的意思，常有一點負面的味道；只是要稱讚東西珍貴、稀有，應該說「珍貴」「獨一無二」。'],
    misuse: ['「這棟樹屋蓋在大樹上，造型好特別，住起來真舒服，真是奇貨可居。」✗　「居」是收藏、囤積，不是居住；奇貨可居是指把稀有的東西當成謀利的本錢。', '「阿公送我的那支老鋼筆是獨一無二的紀念品，真是奇貨可居。」✗　只是珍貴，沒有要拿來謀利，不能用奇貨可居。'],
    eg: ['口罩缺貨的時候，有些人大量搶購，奇貨可居，想用高價轉賣。', '他知道自己是全鎮唯一會修老收音機的人，就奇貨可居，修一次要收很高的費用。'],
    syn: ['囤積居奇'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '呂不韋原本是做什麼的？', opts: ['做生意的大商人', '秦國的大將軍', '趙國的國王', '教書的老師'], a: 0, why: '第一段：呂不韋是「很會做生意的大商人」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '子楚在趙國生活得很舒服，大家都很尊敬他。', a: false, why: '第三段：趙國人對子楚很不客氣，他「日子過得很不如意」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '呂不韋說「我的家門，要等你的家門光大了，才會跟著光大」，意思是什麼？', opts: ['子楚成功了，他也能得到好處', '他想要搬進子楚的家裡住', '他想借子楚的錢做生意', '他嫌子楚家的大門太小'], a: 0, why: '呂不韋打算幫子楚成為繼承人（第六段），子楚成功了，他自己也會跟著得到名和利。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '呂不韋為什麼把子楚看成「奇貨」？', opts: ['子楚是王孫，將來可能很有用', '子楚很會做生意、可以賺大錢', '子楚家裡藏著很多值錢的寶物', '子楚長得非常英俊好看'], a: 0, why: '把第二段和第六段連起來：子楚是秦國太子的兒子，現在雖然落魄，將來卻可能當上國君，所以呂不韋覺得他很有「價值」。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '呂不韋把一個人當成「貨物」來投資，最後得到了名和利。你覺得他的做法聰明嗎？有沒有讓你覺得不太對的地方？請說明理由。',
        ref: '我覺得他很聰明，因為他看得很遠，知道子楚將來可能當國君。可是他幫子楚，不是因為同情，而是想得到好處，把人當成貨物好像不太對。如果我要幫助別人，我希望是因為真心想幫忙，而不是先算好能拿到什麼。',
        rubric: ['說出覺得聰明或不聰明的理由', '用故事內容當根據（看準子楚的身分、想得到名利）', '能說出這種做法讓人覺得不太對的地方'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「奇貨可居」的「居」是什麼意思？', opts: ['收藏、囤積', '住在裡面', '坐下休息', '隔壁鄰居'], a: 0, why: '「居」在這裡是收藏、囤積，等價錢高再賣，不是居住。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '某個歌唱團體宣布要舉辦演唱會，門票一開賣就被搶光。阿德的表哥搶到了十張票，他自己只看一場，其他九張都放到網路上，用好幾倍的價錢賣，還說：「越晚賣越貴，再等幾天。」很多真正想去的歌迷都買不到票。', q: '表哥的做法，最適合用哪個成語形容？', opts: ['奇貨可居', '望塵莫及', '每況愈下', '不學無術'], a: 0, why: '表哥把大家搶不到的票囤起來，等著高價賣出謀利，就是奇貨可居。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈遊記〉這間民宿蓋在山頂，造型像一座小城堡，房間裡還看得到雲海。我們在這裡住了兩晚，真是奇貨可居！', q: '遊記裡的「奇貨可居」用得恰當嗎？', opts: ['不恰當，居是收藏，不是居住', '恰當，因為民宿很稀奇，可以居住', '恰當，因為民宿的價錢很貴', '不恰當，因為民宿不是貨物'], a: 0, why: '奇貨可居的「居」是收藏、囤積，意思是把稀有的東西當成謀利的本錢，不能拿來形容很特別、可以住的地方。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「阿嬤親手織的圍巾是獨一無二的，我會好好珍藏，真是奇貨可居。」這句話的「奇貨可居」用得恰當。', a: false, why: '圍巾只是珍貴，作者沒有要拿它來謀利，不能用奇貨可居。' },
      { id: 'p5', k: 'pair', d: 3, type: 'mc', q: '哪一個成語的意思和「奇貨可居」最接近？', opts: ['囤積居奇', '安居樂業', '奇形怪狀', '完璧歸趙'], a: 0, why: '囤積居奇是把稀少的貨物囤起來，等高價再賣，和奇貨可居相近。安居樂業的「居」是居住，奇形怪狀只是樣子奇怪，都不一樣。' },
      { id: 'p6', k: 'xfer', d: 3, type: 'open', q: '呂不韋看到別人的困境，想到的是「我可以從中得到什麼好處」。如果你發現同學有困難，你會怎麼想、怎麼做？請比較你和呂不韋的想法。',
        ref: '如果同學忘了帶午餐錢，我會先想他會不會餓肚子，然後分他一些麵包，或陪他去找老師。我不會先想「幫他可以得到什麼」。呂不韋是先算好處才幫忙，我覺得幫助別人應該先想對方需要什麼。',
        rubric: ['說出自己遇到同學有困難時的想法和做法', '和呂不韋的想法做比較', '說明自己為什麼選擇這樣做'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '颱風過後菜價大漲，有些商人把青菜藏在倉庫裡不賣，＿＿＿＿，想等價錢更高再拿出來。', opts: ['奇貨可居', '望塵莫及', '不學無術', '每況愈下'], a: 0, why: '把青菜囤起來等高價再賣，是奇貨可居。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 3, type: 'mc', ctx: '學校的跳蚤市場上，小宇發現大家都想要一種限量的卡牌。他把同學手上的這種卡牌一張一張低價收購，再放在自己的攤位上，標了三倍的價錢，還對大家說：「全校只剩我這裡有，現在不買，等一下就沒有了喔！」', q: '小宇在跳蚤市場賣卡牌的方式，像哪一個成語？', opts: ['奇貨可居', '投鼠忌器', '罄竹難書', '望塵莫及'], a: 0, why: '小宇先把稀少的卡牌收進來，再用高價賣出謀利，就是奇貨可居。' }
    ]
  },
  {
    id: 'cy089', lv: 4, word: '望塵莫及', zhuyin: 'ㄨㄤˋ ㄔㄣˊ ㄇㄛˋ ㄐㄧˊ', src: '《莊子．田子方》',
    quote: '夫子奔逸絕塵，而回瞠若乎後矣',
    facts: ['語本《莊子．田子方》：顏淵對孔子說，老師走他也走、老師快步他也快步，但老師「奔逸絕塵」時，他只能瞪著眼落在後面｜教育部《成語典》典源、典故說明', '顏淵說自己學不來的是：孔子不說話就讓人相信，不刻意親近卻周到，沒有官位百姓卻自然歸向｜《莊子．田子方》', '另可參考《尸子》：「鹿馳走無顧，六馬不能望其塵」｜教育部《成語典》參考資料', '「望塵莫及」比喻遠遠落在他人之後｜教育部《成語典》釋義'],
    story: [
      '孔子有很多學生，其中最被孔子稱讚的，是一個叫顏淵的年輕人。顏淵非常好學，老師說的話，他都認真聽、認真學。',
      '《莊子．田子方》裡，寫了一段顏淵和孔子的對話。',
      '有一天，顏淵對孔子說：「老師，您慢慢走，我也慢慢走；您快步走，我也快步走；您跑起來，我也跟著跑。可是，當您像飛一樣往前奔，一下子就把塵土遠遠拋在後面時，我就只能在後面瞪大眼睛看著，怎麼追也追不上了！」',
      '孔子問：「顏回，你這是什麼意思呢？」',
      '顏淵解釋：「老師說話，我也學著說話；老師辯論，我也學著辯論；老師講道理，我也學著講道理。這些我都跟得上。可是有些地方，我怎麼學也學不來：老師不用多說，大家就自然相信您；您不刻意去親近誰，大家卻覺得您對每個人都很周到；您沒有很高的官位，百姓卻自然的願意靠近您。我不知道您是怎麼做到的，只覺得您在前面越跑越遠，我只能在後面乾瞪眼。」',
      '顏淵這段「老師跑得太快，我只能落在後面看」的話，後來就演變成「望塵莫及」這個成語：只能遠遠望著前面揚起的塵土，卻怎麼也趕不上。比喻遠遠落在別人後面。',
      '要注意，「望塵莫及」是落後的人說自己趕不上前面的人。說的是「我比不上你」，或「別人都比不上他」，站在落後的那一邊說話。跑在前面的人，不能說自己對後面的人望塵莫及。'
    ],
    mean: '只能遠遠望著前面車馬揚起的塵土，卻怎麼也追不上。比喻遠遠落在別人後面，趕不上。',
    usage: ['用來說自己（或某些人）遠遠比不上別人，常帶著佩服或謙虛的口氣。', '說話的角度是「落後的一方」：「我對他望塵莫及」是我比不上他；領先的人不能說自己對後面的人望塵莫及。', '和「瞠乎其後」「難望項背」意思相近；「並駕齊驅」「後來居上」則相反。'],
    misuse: ['「我的成績全班第一，我對其他同學真是望塵莫及。」✗　望塵莫及是落後的人趕不上前面的人。自己領先，不能說自己對別人望塵莫及。'],
    eg: ['表姊的鋼琴已經檢定到八級了，剛學半年的我只能望塵莫及。', '那位選手的游泳速度快得驚人，其他選手都望塵莫及。'],
    syn: ['瞠乎其後', '難望項背'], ant: ['並駕齊驅', '後來居上'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '顏淵說，孔子快步走的時候，他會怎麼做？', opts: ['也跟著快步走', '停下來休息', '回頭往家裡走', '坐上馬車追'], a: 0, why: '第三段：「您快步走，我也快步走。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '顏淵說自己「只能在後面乾瞪眼」，他真正追不上的是什麼？', opts: ['孔子讓人自然信服的品德', '孔子在操場跑步的速度', '孔子大聲講話的聲音', '孔子騎的那匹快馬'], a: 0, why: '第五段：說話、辯論他都跟得上，追不上的是孔子「不用多說，大家就自然相信」、讓人願意靠近的品德。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '顏淵用「跟著老師走、跑」，是在比喻什麼？', opts: ['跟著老師學習，想追上老師', '和老師比賽誰的體力好', '每天早上和老師散步', '老師很喜歡運動'], a: 0, why: '第五段：老師說話他學說話、老師講道理他學講道理，「走、跑」是比喻他一路跟著老師學習。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '根據文章最後一段，「望塵莫及」應該站在誰的角度說？', opts: ['落在後面、追不上的人', '跑在最前面的人', '在旁邊看比賽的人', '負責吹哨子的裁判'], a: 0, why: '最後一段：「望塵莫及是落後的人說自己趕不上前面的人。」' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '顏淵是很優秀的學生，卻說自己追不上老師。你覺得他說這些話，是灰心，還是佩服？如果你也有一個讓你「望塵莫及」的榜樣，你會怎麼看待他？',
        ref: '我覺得顏淵是佩服，因為他把老師的優點說得很清楚，而且一直在跟著學。如果我有一個望塵莫及的榜樣，例如很會畫畫的學姊，我不會因為追不上就放棄，而是先學她一個優點，像是每天畫一張速寫。',
        rubric: ['判斷顏淵是灰心還是佩服，並說出根據', '說出一個自己的榜樣', '說出看待榜樣的態度或做法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「望塵莫及」的意思是什麼？', opts: ['遠遠落在別人後面，趕不上', '站在路邊看揚起的灰塵', '希望灰塵不要飛起來', '走路太快，揚起很多灰塵'], a: 0, why: '望塵莫及是只能看著前面的塵土卻追不上，比喻遠遠落在別人後面。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校舉辦英文拼字比賽。轉學生小琪從小在國外長大，每個單字都拼得又快又正確，最難的題目也難不倒她。輪到阿凱上台時，他看著小琪的分數，苦笑著說：「她的程度比我高太多了，我再練好幾年也追不上。」', q: '阿凱對小琪的感覺，最適合用哪個成語形容？', opts: ['望塵莫及', '奇貨可居', '每況愈下', '投鼠忌器'], a: 0, why: '阿凱覺得自己遠遠落在小琪後面，怎麼追也追不上，就是望塵莫及。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈日記〉今天的賽跑我得了第一名，其他同學都遠遠落在我後面。我回頭看看他們，心想：「我對他們真是望塵莫及啊！」', q: '日記裡的「望塵莫及」用得恰當嗎？', opts: ['不恰當，作者領先，不能說自己望塵莫及', '恰當，因為作者真的從頭到尾都跑在最前面', '恰當，因為跑步時腳下會揚起灰塵', '不恰當，因為學校的操場上沒有灰塵'], a: 0, why: '望塵莫及是落後的人說自己趕不上。作者是第一名，應該說「其他同學對我望塵莫及」，角度弄反了。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「哥哥的圍棋已經下到五段，剛學一個月的我，對他只能望塵莫及。」這句話的「望塵莫及」用得恰當。', a: true, why: '落後的「我」說自己趕不上哥哥，角度正確，用得恰當。' },
      { id: 'p5', k: 'pair', d: 3, type: 'match', q: '這些成語跟「望塵莫及」是什麼關係？配起來。', pairs: [['瞠乎其後', '意思相近'], ['並駕齊驅', '意思相反'], ['奇貨可居', '意思無關']], why: '瞠乎其後是在後面瞪眼追不上，跟望塵莫及相近；並駕齊驅是並排一起跑、不分高下，相反；奇貨可居是囤積謀利，無關。' },
      { id: 'p6', k: 'xfer', d: 3, type: 'open', q: '遇到讓你「望塵莫及」的人，你會覺得灰心，還是把他當成目標？請想一個真實的例子，說說你可以向他學習什麼、怎麼一步一步追上去。',
        ref: '我們班的小安心算很快，我一題還沒算完，他已經寫完三題了。我覺得望塵莫及，但我想把他當目標。我可以問他用什麼方法算，每天練習十題心算，記錄自己花幾分鐘，看自己有沒有越來越快。',
        rubric: ['舉出一個讓自己望塵莫及的真實例子', '說出要向他學習的地方', '提出一步一步的具體做法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '這位老師傅做的木工又快又精細，剛當學徒的小王只能＿＿＿＿。', opts: ['望塵莫及', '奇貨可居', '投鼠忌器', '罄竹難書'], a: 0, why: '學徒遠遠比不上老師傅，用望塵莫及。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 3, type: 'tf', ctx: '姊姊：「我這次數學考了一百分，全班第一喔！」\n妹妹：「那姊姊一定對同學們望塵莫及吧！」', q: '妹妹說的「望塵莫及」用得恰當。', a: false, why: '姊姊是第一名，是同學們對姊姊望塵莫及才對。妹妹把角度說反了。' }
    ]
  },
  {
    id: 'cy092', lv: 4, word: '不學無術', zhuyin: 'ㄅㄨˋ ㄒㄩㄝˊ ㄨˊ ㄕㄨˋ', src: '《漢書．霍光傳》',
    quote: '然光不學亡術，闇於大理',
    facts: ['語出《漢書．霍光傳》：班固評論霍光對漢室功勞很大，「然光不學亡術，闇於大理」｜教育部《成語典》典源', '漢武帝臨終把八歲的太子託付給霍光；霍光盡心輔佐昭帝，後來又擁立宣帝｜教育部《成語典》典故說明', '霍光的妻子為了讓女兒當皇后而犯下大錯，霍光知道後隱瞞不說；霍光死後事情揭發，霍家受到嚴懲｜教育部《成語典》典故說明', '典源作「不學亡術」，「亡」通「無」；後來泛指人未經學習而沒有學問才幹｜教育部《成語典》釋義'],
    story: [
      '西漢的時候，有一位大將軍叫霍光。他從小就在皇宮裡做事，個性小心謹慎，做事認真，很受漢武帝信任。',
      '漢武帝快要過世時，太子才八歲。武帝把小太子託付給霍光，請他好好輔佐。霍光盡心盡力，幫助年幼的漢昭帝治理國家，把國家管理得井井有條。',
      '後來漢昭帝年紀輕輕就生病過世了。霍光和大臣們先立了一位新皇帝，可是新皇帝行為放縱，霍光只好請太后把他廢掉，再改立漢宣帝。霍光為漢朝立了很大的功勞，大家都很敬重他。',
      '可是，霍光有一個很大的缺點。他的妻子為了讓女兒當上皇后，私下做了傷害皇后的壞事。事情發生以後，妻子才告訴霍光。霍光非常震驚，卻選擇把這件事隱瞞下來，沒有說出真相，後來還讓自己的女兒當上了皇后。',
      '霍光過世以後，這件事終於被揭發。霍家的人不但沒有悔改，還想做出更危險的事，結果整個家族都受到了嚴厲的懲罰。',
      '寫《漢書》的班固評論霍光：他對國家的功勞很大，可惜「不學亡術，闇於大理」。這是班固的原話，意思是霍光沒有好好學習、不明白大道理；這裡的「亡」就是「無」。《成語典》再進一步解釋：霍光沒有精通書中的道理，用了不適當的方法處理事情，才會隱瞞妻子做的壞事、又讓女兒當上皇后，最後讓家族遭到大禍。',
      '「不學無術」原本是說一個人不研讀經典、不懂道理，所以做事有偏差。後來，大家就用它泛指一個人沒有學習，所以沒有學問，也沒有真本事。'
    ],
    mean: '原指不研讀經典、不懂道理，以致做事有偏差。今天泛指一個人沒有學習，所以沒有學問也沒有本事。',
    usage: ['今天用來批評人沒有學問、沒有真本事（貶義），語氣很重，不要隨便拿來說別人。', '「術」是本事、才幹；只是不會某一件小事（例如不會游泳、不會剪紙），不能說成不學無術。', '「不學無術」側重沒有學習而沒有能力；「胸無點墨」側重學問少、肚子裡沒有墨水。'],
    misuse: ['「我不會游泳，真是不學無術。」✗　不學無術是說整個人沒有學問、沒有本事；只是不會一項技能，不能這樣說。', '「弟弟才三歲，還不認得字，真是不學無術。」✗　三歲的孩子本來就還在學，而且這是很重的批評，不能這樣用。'],
    eg: ['他不肯讀書，什麼都不想學，只會到處吹牛，大家都說他不學無術。', '想當好一個班長，要懂得規劃和溝通，不學無術是做不好的。'],
    syn: ['胸無點墨', '才疏學淺'], ant: ['博學多才', '學富五車'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '漢武帝快過世時，把什麼事託付給霍光？', opts: ['輔佐八歲的小太子', '帶兵到遠方打仗', '管理皇宮的寶庫', '替皇帝編寫史書'], a: 0, why: '第二段：「武帝把小太子託付給霍光，請他好好輔佐。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '霍光知道妻子做的壞事以後，馬上向皇帝報告。', a: false, why: '第四段：霍光「選擇把這件事隱瞞下來，沒有說出真相」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '班固為什麼說霍光「不學無術」？', opts: ['不懂書裡的道理，做錯了決定', '霍光不認得字，不會寫名字', '霍光不會騎馬，也不會射箭', '霍光不懂得管理國家大事'], a: 0, why: '第六段：班固說霍光「不學亡術，闇於大理」，《成語典》解釋為沒有精通書中的道理，用了不適當的方法處理家裡的錯事。霍光其實很會治理國家，也不是不認得字。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '霍光功勞很大，最後霍家卻遭到大禍。從故事來看，最主要的原因是什麼？', opts: ['遇到家裡的錯事，選擇隱瞞', '他帶兵打仗常常打輸', '他沒有把小皇帝輔佐好', '他太晚才當上大將軍'], a: 0, why: '把第四到六段連起來：霍光隱瞞了妻子做的錯事，又讓女兒當上皇后，沒有用對的方法處理，事情揭發後家族才遭到大禍。其他三個選項跟故事寫的相反或沒有提到。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '霍光很有能力、也很忠心，班固卻說他「不學無術」。你覺得一個人「有能力」和「懂道理」，哪一個比較重要？請用故事說明。',
        ref: '我覺得兩個都重要，但懂道理更重要。霍光很會治理國家，可是遇到家人做錯事，他不懂得用對的方法處理，選擇隱瞞，最後害了整個家族。能力可以把事情做好，懂道理才能讓人在困難的時候做出對的選擇。',
        rubric: ['清楚說出自己的看法', '用故事內容當理由（霍光很能幹，卻隱瞞錯事）', '說明能力和懂道理各有什麼作用'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '今天說一個人「不學無術」，是在說他怎麼樣？', opts: ['沒有學習，沒有學問和本事', '不會表演一種特別的魔術', '書讀得很多，非常聰明', '喜歡到處學新的東西'], a: 0, why: '不學無術是說人沒有學習，所以沒有學問、沒有本事。「術」不是魔術。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '某公司請來一位新經理。他常常說自己什麼都懂，可是要他看報表，他看不懂；要他安排工作，他也排得亂七八糟。員工問他問題，他只會說「你們自己想辦法」，也不肯去學。不到三個月，公司的生意就變差了，老闆只好請他離開。', q: '這位新經理，最適合用哪個成語形容？', opts: ['不學無術', '望塵莫及', '奇貨可居', '投鼠忌器'], a: 0, why: '經理沒有真本事又不肯學，做什麼都做不好，就是不學無術。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉今天體育課要跳高，我一次都跳不過去，同學都在笑。我覺得自己真是不學無術。', q: '日記作者說自己「不學無術」，用得恰當。', a: false, why: '只是一項運動做不到，不代表沒有學問、沒有本事，不能說不學無術。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「他整天遊手好閒，什麼也不肯學，長大後找不到工作，親戚都說他不學無術。」這句話的「不學無術」用得恰當。', a: true, why: '他不肯學習，所以沒有本事，用不學無術恰當。' },
      { id: 'p5', k: 'pair', d: 3, type: 'match', q: '這些成語跟「不學無術」是什麼關係？配起來。', pairs: [['胸無點墨', '意思相近'], ['博學多才', '意思相反'], ['望塵莫及', '意思無關']], why: '胸無點墨是肚子裡沒有墨水、沒學問，跟不學無術相近；博學多才是學問廣、才能多，相反；望塵莫及是趕不上別人，無關。' },
      { id: 'p6', k: 'xfer', d: 3, type: 'open', q: '班固覺得，讀書懂道理，能幫助人在遇到難題時做對決定。想一想，你學過的哪一個知識或道理，曾經幫你做出正確的選擇？請舉例說明。',
        ref: '健康課教過，遇到陌生人說要帶我去找爸媽，不能跟他走。有一次在公園，有個不認識的人說我媽媽叫他來接我，我想起老師說的話，就跑去找公園的管理員，後來才知道媽媽根本沒有叫人來。',
        rubric: ['說出一個學過的知識或道理', '說出它幫自己做了什麼選擇', '說明如果不懂這個道理，可能會發生什麼事'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '這家餐廳的老闆不懂料理，也不肯學怎麼管理，大家都說他＿＿＿＿，店開不了多久。', opts: ['不學無術', '望塵莫及', '罄竹難書', '奇貨可居'], a: 0, why: '不懂又不肯學、沒有本事，用不學無術。望塵莫及是趕不上別人，罄竹難書是罪狀多，奇貨可居是囤積謀利，放進句子都不通。' },
      { id: 'x2', k: 'use', d: 3, type: 'mc', ctx: '〈班級日記〉阿明的數學和國語都很好，可是美勞課剪紙剪歪了。小傑笑他：「你連剪紙都不會，真是不學無術！」', q: '小傑用「不學無術」說阿明，恰當嗎？', opts: ['不恰當，只是不會剪紙，說得太重', '恰當，因為阿明真的把紙剪歪了', '恰當，因為美勞也是一種學問', '不恰當，因為阿明的數學比較好'], a: 0, why: '不學無術是說整個人沒學問、沒本事，語氣很重。只是剪紙剪歪，不能這樣說。' }
    ]
  },
  {
    id: 'cy095', lv: 4, word: '罄竹難書', zhuyin: 'ㄑㄧㄥˋ ㄓㄨˊ ㄋㄢˊ ㄕㄨ', src: '《呂氏春秋．季夏紀．明理》',
    quote: '不能勝數，盡荊、越之竹，猶不能書',
    facts: ['語本《呂氏春秋．季夏紀．明理》：亂國出現的各種怪異現象「不能勝數，盡荊、越之竹，猶不能書」｜教育部《成語典》典源', '「罄」讀ㄑㄧㄥˋ，是用盡；「竹」指古代書寫用的竹簡｜教育部《成語典》釋義、典故說明', '同時代的《孫臏兵法．奇正》也有「以楚越之竹書之而不足」，說的是致勝的方法很多，並沒有負面意思｜教育部《成語典》典故說明', '後來專門用來形容罪狀極多（貶義）｜教育部《成語典》釋義、用法說明'],
    story: [
      '在還沒有紙以前，古人是把字寫在「竹簡」上：把竹子剖成一片一片細長的竹片，在上面寫字，再用繩子把竹片串成一卷。寫一本書，要用掉很多很多竹子。',
      '戰國時代末年，秦國的丞相呂不韋召集了很多學者，一起編了一部書，叫做《呂氏春秋》。其中一篇〈明理〉，講到國家混亂的時候，會出現各種奇怪的現象。',
      '書上說：天上的雲，有的像狗、有的像馬、有的像白色的天鵝。地上的怪事更多：牛和馬開口說話，狼跑進了城裡，馬頭上長出角，公雞長了五隻腳，還有豬生出了小狗……',
      '書上說，這些怪事都是國家亂了才會出現，多到數也數不清，就算把荊、越兩個地方的竹子全部砍來做成竹簡，也寫不完。',
      '「罄」是用盡的意思，「罄竹難書」就是：用盡所有的竹子，也難以寫完。',
      '一開始，這句話是形容亂象太多。和《呂氏春秋》差不多時代的《孫臏兵法》，也說過打勝仗的方法多到「用楚越的竹子也寫不完」，那裡的意思並不壞。可見「竹子寫不完」本來只是說「非常多」。',
      '可是後來，人們越來越常用它來形容壞人做的壞事太多。例如古代有人寫文章揭發壞人的罪行，就說用盡南山的竹子，也寫不完他的罪。慢慢的，「罄竹難書」就變成專門形容「罪狀非常多」的成語了。',
      '所以今天用「罄竹難書」時要特別小心：它說的是「壞事多」，不能拿來稱讚好人好事很多。'
    ],
    mean: '用盡所有的竹子做成竹簡，也寫不完。原本形容亂象極多；今天專門用來形容罪狀、壞事多到寫不完。',
    usage: ['今天用來形容一個人做的壞事、犯的罪狀非常多（貶義）。', '不能用來稱讚好人好事很多；要說優點、功勞多，可以說「數不勝數」「不勝枚舉」。', '「罄」讀ㄑㄧㄥˋ，是用盡的意思。'],
    misuse: ['「志工阿姨幫助過的人多到罄竹難書，大家都很感謝她。」✗　罄竹難書今天專門形容罪狀多，用來稱讚好人好事，意思就完全反了。'],
    eg: ['這個詐騙集團騙了上千位老人家的錢，罪行罄竹難書。', '故事裡的大壞蛋欺負村民、搶奪糧食，做的壞事罄竹難書。'],
    syn: ['擢髮難數'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '在還沒有紙的時候，古人把字寫在什麼上面？', opts: ['竹子剖成的竹簡', '石頭做的石板', '晒乾的樹葉', '動物的皮毛'], a: 0, why: '第一段：古人「把字寫在『竹簡』上」，竹簡是把竹子剖成細長的竹片。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '《孫臏兵法》用「竹子寫不完」，是在說罪狀很多。', a: false, why: '第六段：《孫臏兵法》說的是「打勝仗的方法」多到寫不完，「那裡的意思並不壞」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '書上說「把荊、越的竹子全砍來也寫不完」，是想強調什麼？', opts: ['怪事多到數也數不清', '荊越的竹子長得很慢', '寫竹簡是很累的事', '荊越的人都很會寫字'], a: 0, why: '第四段：這些怪事「多到數也數不清」，所以用「竹子寫不完」來強調數量多。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '「罄竹難書」的意思，從古到今有什麼變化？', opts: ['從「非常多」變成專指「罪狀多」', '從「罪狀多」變成也能說「好事多」', '從「竹簡用完」變成專指「書很難寫」', '古今的意思完全一樣'], a: 0, why: '第六段說它本來只是「非常多」，第七段說後來「變成專門形容罪狀非常多」。不是從罪狀多變成好事多，今天也不能拿來說好事；「難書」是寫不完，不是書很難寫。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '「罄竹難書」最早並沒有壞的意思，可是今天大家都用來說罪狀多。如果有人用它來稱讚好人好事，你會怎麼跟他說明？請用文章內容當理由。',
        ref: '我會跟他說：「這個成語最早只是說很多，可是後來大家都用它來說壞人的罪狀，今天聽到罄竹難書，大家都會想到壞事。你用它稱讚好人，別人會誤會你在罵他。要稱讚好事多，可以說『不勝枚舉』。」',
        rubric: ['說出罄竹難書今天的用法（形容罪狀多）', '用文章內容說明意思的變化', '提出可以替換的正確說法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「罄竹難書」的「罄」是什麼意思？', opts: ['用盡', '敲打', '聲音', '種植'], a: 0, why: '「罄」是用盡，「罄竹」就是把竹子用完。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '新聞報導，一名男子假裝成工人，到處跟老人家說要修水管，收了錢卻不修；他還偷走別人的機車，又在網路上賣假貨。被他騙的人超過三百位，警察抓到他時，光是整理他的犯罪紀錄，就裝滿了好幾大箱。', q: '這名男子做的壞事，最適合用哪個成語形容？', opts: ['罄竹難書', '望塵莫及', '不學無術', '奇貨可居'], a: 0, why: '他做的壞事、犯的罪非常多，多到紀錄裝滿好幾箱，就是罄竹難書。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈頒獎典禮〉主持人介紹得到「熱心公益獎」的林伯伯：「林伯伯三十年來幫助過的家庭，多到罄竹難書，讓我們給他熱烈的掌聲！」', q: '主持人用「罄竹難書」稱讚林伯伯，恰當嗎？', opts: ['不恰當，它專門形容罪狀多，不能稱讚好事', '恰當，因為林伯伯做的好事真的多得數不清', '恰當，因為好事多到竹簡也寫不完', '不恰當，因為現在大家已經不用竹簡寫字了'], a: 0, why: '罄竹難書今天專門形容罪狀多，是貶義。用來稱讚林伯伯，聽起來反而像在說他做了很多壞事。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「這位暴君欺壓百姓、浪費國家的財產，罪狀罄竹難書。」這句話的「罄竹難書」用得恰當。', a: true, why: '暴君做了很多壞事，用罄竹難書形容罪狀多，恰當。' },
      { id: 'p5', k: 'pair', d: 3, type: 'mc', q: '哪一個成語的意思和「罄竹難書」最接近？', opts: ['擢髮難數', '罄其所有', '竹報平安', '知書達禮'], a: 0, why: '擢髮難數是拔下頭髮來數也數不完，也是比喻罪狀非常多。其他三個只是有相同的字，意思都不一樣。' },
      { id: 'p6', k: 'xfer', d: 3, type: 'open', q: '「罄竹難書」原本只是說「很多」，後來才專門用在壞事。在寫作文、說話時，你可以怎麼避免把成語用錯？請說出至少兩個方法。',
        ref: '第一，用之前先查字典，看它今天是褒義還是貶義。第二，不要只看字面猜意思，像「罄竹難書」字面上看不出是壞事。第三，用完念給家人聽，問他們會不會誤會我的意思。',
        rubric: ['說出至少兩個避免用錯成語的方法', '方法具體、做得到', '能連結到罄竹難書「意思會改變」的例子'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '這名貪官收賄又欺壓百姓，罪狀＿＿＿＿，最後被關進了監牢。', opts: ['罄竹難書', '望塵莫及', '投鼠忌器', '每況愈下'], a: 0, why: '形容貪官的罪狀很多，用罄竹難書。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 3, type: 'tf', ctx: '〈作文〉我的媽媽每天煮飯、洗衣服、陪我寫功課，她為我們家做的事，真是罄竹難書。', q: '作文裡用「罄竹難書」形容媽媽做的事，用得恰當。', a: false, why: '罄竹難書今天專門形容罪狀多，不能拿來說媽媽為家裡做的好事。可以改成「多得數不清」。' }
    ]
  },
  {
    id: 'cy098', lv: 4, word: '投鼠忌器', zhuyin: 'ㄊㄡˊ ㄕㄨˇ ㄐㄧˋ ㄑㄧˋ', src: '《漢書．賈誼傳》',
    quote: '里諺曰：「欲投鼠而忌器。」此善諭也',
    facts: ['語出《漢書．賈誼傳》：賈誼引用民間俗語「欲投鼠而忌器」，說老鼠靠近器物，大家尚且不敢丟，更何況是靠近君主的貴臣｜教育部《成語典》典源', '賈誼原文接著說：古代君王用廉恥節禮對待大臣，大臣有罪也不施加羞辱的刑罰，因為大臣「離主上不遠」｜《漢書．賈誼傳》', '《成語典》解讀為：賈誼把皇上比喻成珍貴的器物，把皇上身邊的奸佞比喻成老鼠｜教育部《成語典》典故說明','「投鼠忌器」比喻想要除害，但因有所顧忌而不敢下手｜教育部《成語典》釋義', '反義成語是「肆無忌憚」｜教育部《成語典》辨識'],
    story: [
      '西漢的時候，有一位很有學問的年輕人叫賈誼，常常寫文章向漢文帝提出建議。',
      '有一次，賈誼談到皇帝該怎麼對待身邊的大臣。他覺得大臣離皇帝很近，怎麼處置大臣，也會牽連到皇帝的尊嚴。',
      '賈誼在給皇帝的文章裡，引用了一句民間的俗語：「想要拿東西丟老鼠，又怕打破旁邊的器物。」',
      '他解釋：家裡有一隻討厭的老鼠，跑到一個珍貴的花瓶旁邊。你很想拿東西丟牠，可是又怕一丟，把花瓶也打破了，只好忍住不丟。賈誼說，這個比喻說得真好！老鼠靠近器物，大家都還會顧忌，更何況是靠近皇帝的大臣呢？',
      '在賈誼原本的文章裡，他接著說：古代聖明的君王把官位分成很多等級，讓皇帝高高在上；對待大臣，用禮義廉恥要求他們，就算大臣犯了大錯，也不用羞辱人的刑罰，因為大臣離皇帝很近。也就是說，賈誼是用這句俗語，勸皇帝要顧到大臣的體面。',
      '教育部《成語典》把這段話解讀得更白：皇帝就像珍貴的器物，皇帝身邊做壞事的大臣就像老鼠。大家明明想處罰他們，卻怕連帶傷到皇帝的尊嚴，只好遲遲不敢下手。這是後人對賈誼這段話的說明。',
      '後來，「投鼠忌器」就用來比喻：想要除掉壞人、壞事，卻因為有所顧忌，怕傷到旁邊重要的人或東西，而不敢下手。'
    ],
    mean: '想拿東西丟老鼠，又怕打破老鼠旁邊的器物。比喻想要除掉壞人或壞事，卻因為有所顧忌，怕傷到重要的人或東西，而不敢下手。',
    usage: ['用在「想處理一個問題，可是怕連帶傷到重要的人或東西，所以不敢動手」的時候。', '要同時有「想除掉的壞事」和「怕傷到的重要東西」。只是自己膽小、怕失敗而不敢做，不能用投鼠忌器。', '做事完全不顧一切、什麼都不怕，是「肆無忌憚」，意思相反。'],
    misuse: ['「我很想參加演講比賽，可是怕講不好被笑，只好投鼠忌器，不敢報名。」✗　這只是怕失敗，沒有「想除掉的壞事」和「怕傷到的重要東西」，不能用投鼠忌器。'],
    eg: ['書櫃後面有一窩螞蟻，可是旁邊放著爺爺最寶貝的老相簿，怕噴藥弄壞相簿，大家都投鼠忌器。', '校隊裡有人常常遲到，可是他是隊上最強的投手，教練投鼠忌器，一直沒有嚴格處罰。'],
    syn: [], ant: ['肆無忌憚'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '賈誼引用的俗語，說的是什麼情形？', opts: ['想丟老鼠，又怕打破旁邊的器物', '想養老鼠，又怕老鼠咬壞東西', '想買花瓶，又怕價錢太貴', '想抓老鼠，卻找不到老鼠躲在哪'], a: 0, why: '第三段：「想要拿東西丟老鼠，又怕打破旁邊的器物。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '在賈誼的比喻裡，皇帝就像珍貴的器物。', a: true, why: '第四段：老鼠靠近器物都不敢丟，「更何況是靠近皇帝的大臣」，皇帝就是那件珍貴的器物；第六段也這樣說明。' },
      { id: 'r6', p: 2, d: 2, type: 'mc', q: '照《成語典》的說明，大家為什麼不敢處罰皇帝身邊做壞事的大臣？', opts: ['怕連帶傷到皇帝的尊嚴', '大臣們的力氣都很大', '大臣們早就躲起來了', '大家都很喜歡這些大臣'], a: 0, why: '第六段：大家「怕連帶傷到皇帝的尊嚴，只好遲遲不敢下手」，就像怕打破花瓶而不敢丟老鼠。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '賈誼用「丟老鼠」的俗語，主要是想讓皇帝明白什麼？', opts: ['處理身邊的人，會牽涉到皇帝', '家裡一定要養貓來抓老鼠', '珍貴的花瓶要放在高處', '老鼠是最可怕的動物'], a: 0, why: '把第二、四、五段連起來：大臣離皇帝很近，怎麼處置他們就會牽涉到皇帝的尊嚴，所以賈誼用老鼠和器物來比喻。' },
      { id: 'r7', p: 4, d: 3, type: 'open', q: '賈誼勸皇帝要顧到大臣的體面；可是照《成語典》的說明，這樣一來，大家也不敢處罰做壞事的大臣。如果你是皇帝，要怎麼做才能兩邊都顧到？請說明理由。',
        ref: '我會先訂清楚的規矩，讓大臣知道做錯事一定會受到處罰，但是處罰的方式不用當眾羞辱他。這樣處罰是照規矩來，不會傷到皇帝的尊嚴，大臣也保有體面，大家不用再怕東怕西，壞事就不會一直留著。',
        rubric: ['提出具體的建議', '建議能同時顧到「處理壞事」和「顧及尊嚴、體面」兩件事', '說明理由，前後說得通'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「投鼠忌器」的「忌」是什麼意思？', opts: ['顧忌、害怕', '忘記、遺忘', '生日、紀念', '喜歡、愛好'], a: 0, why: '「忌」是顧忌、害怕。「忌器」就是怕傷到器物。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小真家的電視櫃後面住了一隻壁虎，晚上常常爬出來嚇人。爸爸想用掃把把牠趕出去，可是壁虎剛好躲在媽媽最心愛的玻璃燈旁邊。爸爸拿著掃把站了好久，怕一揮下去燈就破了，最後只好先放下掃把，等壁虎自己爬出來。', q: '爸爸拿著掃把卻不敢揮下去，最適合用哪個成語形容？', opts: ['投鼠忌器', '奇貨可居', '罄竹難書', '不學無術'], a: 0, why: '想趕走壁虎（想除掉的東西），又怕打破玻璃燈（怕傷到的重要東西），就是投鼠忌器。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉明天要上台報告，可是我怕講錯被同學笑，心裡一直想請假不去學校。我現在真是投鼠忌器。', q: '日記作者說自己「投鼠忌器」，用得恰當。', a: false, why: '作者只是怕講錯被笑，沒有「想除掉的壞事」和「怕傷到的重要東西」，不能用投鼠忌器。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「那棵老樹的樹根把人行道頂得凹凸不平，市政府想挖掉樹根，又怕老樹因此枯死，只好投鼠忌器，先用圍欄圍起來。」這句話的「投鼠忌器」用得恰當。', a: true, why: '想處理凹凸不平的人行道，又怕傷到珍貴的老樹，所以不敢下手，用得恰當。' },
      { id: 'p5', k: 'pair', d: 3, type: 'mc', q: '哪一個成語的意思和「投鼠忌器」相反？', opts: ['肆無忌憚', '左右為難', '瞻前顧後', '畏首畏尾'], a: 0, why: '投鼠忌器是有顧忌不敢下手；肆無忌憚是毫無顧忌、什麼都不怕，意思相反。其他三個都有猶豫、顧慮的意思。' },
      { id: 'p6', k: 'xfer', d: 3, type: 'open', q: '生活中，有時候想處理一個問題，卻怕傷到別的人或東西（例如想提醒好朋友改掉壞習慣，又怕傷感情）。請舉一個例子，說說你會怎麼做，才能「趕走老鼠又不打破器物」。',
        ref: '我的好朋友常常講話太大聲，吵到別人，我想提醒他又怕他生氣。我會找只有我們兩個人的時候，先說我很喜歡跟他玩，再小聲的告訴他：「剛才圖書館的人好像被吵到了。」這樣他比較不會覺得丟臉，也比較願意改。',
        rubric: ['舉出一個「想處理問題又怕傷到人或東西」的例子', '提出兼顧兩邊的具體做法', '說明這樣做為什麼比較好'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '弟弟的玩具車卡在魚缸後面，用力拉怕把魚缸撞倒，大家只能＿＿＿＿，想別的辦法慢慢拿出來。', opts: ['投鼠忌器', '罄竹難書', '奇貨可居', '望塵莫及'], a: 0, why: '想拿出玩具車，又怕撞倒魚缸，所以不敢用力，是投鼠忌器。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 3, type: 'mc', ctx: '班上有一位同學常常在打掃時間偷懶，大家都很不滿。可是他是班長最好的朋友，也是班上最會帶活動的人。大家擔心如果直接說出來，班長會不高興，班上的氣氛也會變差，所以拖了好幾個星期，一直沒有人敢提。', q: '班上同學想說又不敢說的情形，像哪一個成語？', opts: ['投鼠忌器', '每況愈下', '不學無術', '奇貨可居'], a: 0, why: '大家想處理偷懶的問題，又怕傷到班長的感情和班上的氣氛，所以不敢下手，就是投鼠忌器。' }
    ]
  }
]);
window.DATA_CY_READ = (window.DATA_CY_READ || []).concat([
  {
    id: 'cyr02', lv: 1, genre: '應用文', domain: ['生活', '藝術'], title: '班會紀錄：合唱比賽怎麼準備',
    uses: ['cy012', 'cy013', 'cy016', 'cy019'],
    facts: ['班級、人物、比賽都是虛構的｜虛構情境'],
    body: [
      { h: '五年三班　第六次班會紀錄' },
      { title: '會議資料', box: ['時間：十月十五日（星期三）第七節', '地點：五年三班教室', '主席：班長林小芸', '紀錄：學藝股長陳阿凱', '出席：全班二十八人'] },
      { h: '一、主席報告' },
      '下個月十八日是全校合唱比賽，每班要唱一首指定曲和一首自選曲。距離比賽只剩五個星期，今天要討論自選曲和練習的方法。',
      { h: '二、討論事項' },
      '（一）自選曲要唱哪一首？上星期大家先選了〈小星星〉，週一又改成〈野餐〉，昨天又有人提議換成〈海洋之歌〉。音樂老師提醒：一直換歌，前面練的都白費了，這樣朝三暮四，永遠練不熟。大家同意今天投票決定，決定了就不再改。投票結果：〈海洋之歌〉十六票、〈野餐〉九票、〈小星星〉三票。',
      '（二）高音唱不好怎麼辦？去年比賽時，我們在高音的地方破音，台下有人笑出聲。從那次以後，好幾位同學一唱到高音就緊張得不敢出聲，像驚弓之鳥一樣。小真提議：高音先用輕聲唱，練熟了再慢慢放大聲；老師也答應每天幫大家暖聲五分鐘。',
      '（三）有人只張嘴、不出聲。風紀股長說，練習時有幾位同學只動嘴巴、沒有發出聲音，以為混在大家裡面沒人發現。阿哲說：「這是濫竽充數，到了比賽，評審一聽就知道。」大家同意分成四個小組，每組輪流唱給全班聽，讓每個人都真的出聲。',
      '（四）練習時間怎麼安排？有同學覺得五個星期太短，一定來不及。老師說：「每天練一點，就像愚公移山，一擔一擔的挖，總有挖完的一天。」大家決定每天早自習練十分鐘，每週五午休再全班合唱一次。',
      { h: '三、決議' },
      { title: '本次決議', box: ['自選曲確定為〈海洋之歌〉，不再更換。', '高音先輕聲唱，每天早自習前暖聲五分鐘。', '分四組輪流唱，每個人都要出聲。', '每天早自習練十分鐘，週五午休全班合唱。'] },
      { h: '四、臨時動議' },
      '小美提議比賽當天全班穿白上衣、繫藍色領巾，全體同意。散會時間：下午三點四十分。'
    ],
    qs: [
      { id: 'q1', p: 1, d: 1, type: 'mc', q: '這次班會最後決定自選曲唱哪一首？', opts: ['〈海洋之歌〉', '〈野餐〉', '〈小星星〉', '還沒有決定'], a: 0, why: '討論事項（一）：投票結果〈海洋之歌〉十六票最多；決議第一條也寫「自選曲確定為〈海洋之歌〉」。' },
      { id: 'q2', p: 1, d: 1, type: 'mc', q: '班會決定每天什麼時候練唱十分鐘？', opts: ['早自習', '午休', '放學後', '第七節'], a: 0, why: '討論事項（四）：「每天早自習練十分鐘」；週五午休是全班合唱。' },
      { id: 'q3', p: 2, d: 2, type: 'mc', q: '好幾位同學「一唱到高音就緊張得不敢出聲」，最主要的原因是什麼？', opts: ['去年在高音破音，被人笑過', '他們的聲音本來就很小', '音樂老師不准他們唱高音', '〈海洋之歌〉沒有高音'], a: 0, why: '討論事項（二）：去年比賽在高音破音、有人笑出聲，「從那次以後」大家就怕唱高音，所以紀錄說他們像驚弓之鳥。' },
      { id: 'q4', p: 3, d: 2, type: 'match', q: '把班會討論的事情和紀錄裡用的成語配起來。', pairs: [['自選曲一直換來換去', '朝三暮四'], ['唱到高音就緊張不敢出聲', '驚弓之鳥'], ['只張嘴、不出聲混在裡面', '濫竽充數'], ['每天練一點，不怕時間短', '愚公移山']], why: '反覆不定＝朝三暮四；受過驚嚇而害怕＝驚弓之鳥；沒有真本事混在團體裡＝濫竽充數；一點一點堅持做＝愚公移山。' },
      { id: 'q5', p: 4, d: 3, type: 'mc', q: '如果把「像驚弓之鳥一樣」改成「像愚公移山一樣」，這句話會怎麼樣？', opts: ['說不通，同學是害怕，不是努力', '意思一樣，都是在說練習', '意思更清楚，大家很努力', '說得通，因為都和比賽有關'], a: 0, why: '那幾位同學是因為去年被笑而害怕，驚弓之鳥說的是害怕；愚公移山說的是堅持努力，放在這裡跟事實對不起來。' },
      { id: 'q6', p: 4, d: 3, type: 'open', q: '這份班會紀錄做了四項決議。你覺得哪一項對合唱比賽最有幫助？請用紀錄裡的內容說明理由。',
        ref: '我覺得「分四組輪流唱，每個人都要出聲」最有幫助。紀錄裡說有人只張嘴不出聲，如果大家都濫竽充數，合唱的聲音就不夠飽滿。輪流唱給全班聽，每個人都要練熟，比賽時全班的聲音才會整齊又響亮。',
        rubric: ['選出一項決議', '用紀錄裡的內容當理由（例如討論事項中發生的問題）', '說明這項決議怎麼幫助比賽'] }
    ]
  },
  {
    id: 'cyr05', lv: 2, genre: '新聞', domain: ['健康', '社會'], title: '最後一棒逆轉勝！五年二班奪下大隊接力冠軍',
    uses: ['cy042', 'cy043', 'cy044', 'cy050'],
    facts: ['學校、班級、人物、成績都是虛構的｜虛構情境'],
    body: [
      '【本報記者陳小芳／綠谷國小報導】昨天（十月二十四日）上午，綠谷國小舉行一年一度的運動會。全場最受矚目的五年級大隊接力，由五年二班拿下冠軍，成績是三分十二秒。',
      { h: '不留後路　全班決定全力衝' },
      '賽前，五年二班的教練建議後面幾棒穩穩跑，保住名次就好。全班討論後，卻決定「不保守，最後五棒全力衝」。班長小翔說：「我們破釜沉舟，不留後路，練了一個月就是為了今天！」這一個月來，全班每天早上七點到操場練交棒，沒有一個人缺席。',
      '比賽前，第一棒的小美緊張得不得了，聽到廣播的聲音、氣球爆開的聲音，都以為是起跑的槍聲，差點衝出跑道。她笑著說：「那時候真是草木皆兵。」',
      { h: '掉棒落後　彎道連超兩班' },
      '比賽開始後，二班一路保持在第二名。沒想到第十二棒交棒時，接力棒掉在地上，二班一下子落到最後一名。撿起棒子的跑者被擠在跑道內側，前後左右都是別班的選手，隊友在場邊也幫不上忙。看台上有同學說：「這下真是四面楚歌了！」',
      '二班的跑者沒有放棄。平常練短跑的阿哲被安排跑彎道，他最擅長壓低身體過彎，一上場就如魚得水，連續超過兩個班。最後一棒小翔接棒時，只落後第一名兩公尺，他在終點前五公尺衝過對手，全場歡聲雷動。',
      { table: { cap: '五年級大隊接力成績', head: ['名次', '班級', '成績'], rows: [['1', '五年二班', '3分12秒'], ['2', '五年四班', '3分13秒'], ['3', '五年一班', '3分15秒'], ['4', '五年三班', '3分18秒']] } },
      { h: '跑得快　也要跑得健康' },
      '校長在頒獎時說，大隊接力考驗的不只是速度，還有團隊合作和不放棄的精神。體育老師也提醒大家，跑完後不要馬上坐下，要先慢走、補充水分；比賽前一晚要早點睡，才能跑出好成績，又不容易受傷。'
    ],
    qs: [
      { id: 'q1', p: 1, d: 1, type: 'mc', q: '五年級大隊接力的冠軍是哪一班？', opts: ['五年二班', '五年四班', '五年一班', '五年三班'], a: 0, why: '第一段：「由五年二班拿下冠軍」；表格第一名也是五年二班。' },
      { id: 'q2', p: 1, d: 1, type: 'mc', q: '根據表格，第一名和第二名的成績差了多少？', opts: ['一秒', '兩秒', '三秒', '六秒'], a: 0, why: '表格：五年二班3分12秒，五年四班3分13秒，只差一秒。' },
      { id: 'q3', p: 2, d: 2, type: 'mc', q: '班長說「我們破釜沉舟」，是想表達什麼？', opts: ['下定決心，全力拚到底', '把家裡的鍋子打破', '練習時間已經不夠了', '只想保住第三名就好'], a: 0, why: '全班決定「不保守，最後五棒全力衝」，班長又說「不留後路」，表示大家下定決心拚到底。' },
      { id: 'q4', p: 2, d: 2, type: 'mc', q: '小美說自己那時候「草木皆兵」，從文中看，她當時是什麼心情？', opts: ['非常緊張，一點聲音就嚇一跳', '很生氣，覺得旁邊的人太吵了', '很開心，因為終於要上場比賽了', '很無聊，想快點比完回家'], a: 0, why: '她聽到廣播、氣球爆開的聲音都以為是槍聲，差點衝出跑道，可見緊張到有一點聲音就以為出事了。' },
      { id: 'q5', p: 3, d: 2, type: 'match', q: '把報導裡的事情和成語配起來。', pairs: [['全班決定不保守、全力衝', '破釜沉舟'], ['聽到聲音就以為是起跑槍聲', '草木皆兵'], ['掉棒後被別班選手團團圍住', '四面楚歌'], ['阿哲跑他最擅長的彎道', '如魚得水']], why: '下定決心不留退路＝破釜沉舟；緊張到疑神疑鬼＝草木皆兵；四周都是對手、陷入困境＝四面楚歌；到了最適合自己的位置＝如魚得水。' },
      { id: 'q6', p: 4, d: 3, type: 'open', q: '校長說大隊接力考驗的「不只是速度」。你同意嗎？請從報導中找出兩件事當證據，說明它還考驗了什麼。',
        ref: '我同意。第一，二班每天早上七點練交棒，一個月都沒人缺席，這是團隊合作。第二，第十二棒掉棒落到最後，大家還是沒放棄，阿哲在彎道連超兩班，這是不放棄的精神。只靠速度，掉棒以後可能就輸了。',
        rubric: ['清楚說出同不同意', '從報導中找出兩件具體的事當證據', '說明這兩件事考驗的是速度以外的什麼（例如合作、不放棄、安排位置）'] }
    ]
  },
  {
    id: 'cyr08', lv: 3, genre: '圖表資料', domain: ['語文', '數學'], title: '五年六班閱讀存摺：一學期的統計',
    uses: ['cy071', 'cy074', 'cy076', 'cy079'],
    facts: ['班級、人物、數字都是虛構的｜虛構情境'],
    body: [
      '五年六班從九月開學起使用「閱讀存摺」：每讀完一本書，就在存摺上寫下書名和一句心得，再請小老師蓋章。開學第一天，全班就約法三章：一、每個人每個月至少讀四本書；二、心得要自己寫，不能抄書上的介紹；三、借來的書要準時歸還。全班二十八人，所以每個月的目標是一百一十二本，整個學期的目標是五百六十本。',
      '學期末，學藝股長把全班的閱讀紀錄整理成下面的長條圖和表格。',
      { svg: '<svg viewBox="0 0 640 360" xmlns="http://www.w3.org/2000/svg" font-size="18" text-anchor="middle"><rect x="0" y="0" width="640" height="360" rx="16" fill="#fffaf0"/><line x1="70" y1="300" x2="610" y2="300" stroke="#555" stroke-width="2"/><line x1="70" y1="40" x2="70" y2="300" stroke="#555" stroke-width="2"/><line x1="70" y1="120.8" x2="610" y2="120.8" stroke="#d9534f" stroke-width="2" stroke-dasharray="8 6"/><line x1="440" y1="25" x2="480" y2="25" stroke="#d9534f" stroke-width="2" stroke-dasharray="8 6"/><text x="490" y="31" fill="#d9534f" font-size="16" text-anchor="start">每月目標112本</text><g fill="#4a90d9"><rect x="95" y="133.6" width="70" height="166.4"/><rect x="200" y="95.2" width="70" height="204.8"/><rect x="305" y="200.8" width="70" height="99.2"/><rect x="410" y="82.4" width="70" height="217.6"/><rect x="515" y="95.2" width="70" height="204.8"/></g><g fill="#222"><text x="130" y="125">104</text><text x="235" y="87">128</text><text x="340" y="192">62</text><text x="445" y="74">136</text><text x="550" y="87">128</text></g><g fill="#333"><text x="130" y="326">九月</text><text x="235" y="326">十月</text><text x="340" y="326">十一月</text><text x="445" y="326">十二月</text><text x="550" y="326">一月</text></g><text x="40" y="30" fill="#333" font-size="15">本數</text></svg>', cap: '圖一：五年六班每月讀書總本數（虛線是每月目標112本）', alt: '長條圖：九月104本、十月128本、十一月62本、十二月136本、一月128本。十二月最多，十一月最少；十月、十二月、一月超過每月目標112本，九月和十一月沒有達到。' },
      { table: { cap: '表一：各小組每月讀書本數（每組7人）', head: ['小組', '九月', '十月', '十一月', '十二月', '一月', '合計'], rows: [['A組', 27, 31, 25, 33, 32, 148], ['B組', 10, 40, 4, 38, 30, 122], ['C組', 33, 28, 17, 32, 31, 141], ['D組', 34, 29, 16, 33, 35, 147]] } },
      '從長條圖可以看到，十一月的本數掉得特別多。原來十一月要準備運動會和期中考，很多人都沒有時間讀書。十二月大家趕快把進度補回來，成為全學期讀最多的月份。',
      '表格裡，B組的數字特別引人注意：十月和十二月都讀了將近四十本，九月和十一月卻少得可憐。B組的組長不好意思的說：「我們常常想到就拚命讀，讀完一陣子又忘了，真是一暴十寒。」',
      '全學期加起來，全班一共讀了五百五十八本，離目標只差兩本。學藝股長報告時嘆了一口氣：「只差兩本，真是功虧一簣！」',
      '老師卻笑著說：「雖然沒有達到目標，但是比上學期多讀了一百多本，大部分的同學也養成了每週讀書的習慣，整體來說還算差強人意。下學期只要每天讀一點、不要忽冷忽熱，一定做得到。」'
    ],
    qs: [
      { id: 'q1', p: 1, d: 1, type: 'mc', q: '根據圖一，哪一個月全班讀的書最多？', opts: ['十二月', '十月', '一月', '九月'], a: 0, why: '圖一：十二月136本最多；十月和一月都是128本。' },
      { id: 'q2', p: 1, d: 1, type: 'mc', q: '開學時全班約法三章，下面哪一項「不是」約定的內容？', opts: ['每週要上台分享一本書', '每個人每個月至少讀四本書', '心得要自己寫', '借來的書要準時歸還'], a: 0, why: '第一段的三條約定是：每月至少讀四本、心得自己寫、借的書準時還。沒有說要上台分享。' },
      { id: 'q3', p: 2, d: 2, type: 'mc', q: '學藝股長說全班「功虧一簣」，從文中可以推知是什麼意思？', opts: ['全學期只差兩本就達到目標', '十一月全班一本書都沒有讀', '有一組借的書全部都弄丟了', '一月借的書都還沒有還回去'], a: 0, why: '全班讀了558本，目標560本，「只差兩本」。功虧一簣就是只差最後一點點而沒有成功。' },
      { id: 'q4', p: 3, d: 2, type: 'mc', q: '從表一看，哪一組的讀書情形最像「一暴十寒」？', opts: ['B組', 'A組', 'C組', 'D組'], a: 0, why: 'B組九月10本、十月40本、十一月只有4本、十二月又38本，忽多忽少，就像一暴十寒。其他組每個月的本數比較平均。' },
      { id: 'q5', p: 3, d: 3, type: 'mc', q: '老師說這學期的成績「差強人意」。下面哪一個說法最符合老師的意思？', opts: ['沒有達到目標，但整體還算不錯', '全班表現非常差，讓人失望', '全班表現完美，沒有缺點', '老師不想評論這學期的表現'], a: 0, why: '老師說「雖然沒有達到目標」，但多讀了一百多本、養成了習慣。差強人意是「不夠好，但大致還能讓人滿意」，不是很差。' },
      { id: 'q6', p: 4, d: 3, type: 'open', q: '如果你是五年六班的同學，下學期想真正達到目標，你會建議全班怎麼做？請用圖一或表一裡的數字當理由。',
        ref: '我會建議每個人每週固定讀一本，不要等到月底才趕。圖一的十一月只有62本，是因為大家忙運動會和考試就不讀了；表一的B組也是忽多忽少。如果每週都讀一本，忙的月份也不會掉太多，全學期就不會只差兩本。',
        rubric: ['提出具體的建議', '用圖一或表一的數字當理由', '說明建議怎麼解決資料中看到的問題（例如十一月太少、B組不平均）'] }
    ]
  }
]);
